/* =========================================================================
   CAMADA DE OTIMIZAÇÃO DE FLUIDEZ & CACHE DE DOM (PERFORMANCE RUNTIME)
   ========================================================================= */
(function initPerformanceRuntime() {
  const domCache = new Map();

  window.__getEl = function(id) {
    if (!id) return null;
    const cached = domCache.get(id);
    if (cached && cached.isConnected) return cached;
    const el = document.getElementById(id);
    if (el) domCache.set(id, el);
    return el;
  };

  window.__clearDomCache = function() {
    domCache.clear();
  };

  window.__rafThrottle = function(fn) {
    let scheduled = false;
    let lastArgs = null;
    return function(...args) {
      lastArgs = args;
      if (scheduled) return;
      scheduled = true;
      requestAnimationFrame(() => {
        scheduled = false;
        fn.apply(this, lastArgs);
      });
    };
  };

  window.__debounce = function(fn, wait) {
    let timer = null;
    return function(...args) {
      clearTimeout(timer);
      timer = setTimeout(() => fn.apply(this, args), wait);
    };
  };
})();

// =========================================================================
// MÓDULO 0: CAMADA DE INTEGRAÇÃO ENTRE MÓDULOS (PlatformHub)
// =========================================================================
window.PlatformHub = (function() {
      const stateHub = {
        activeModule: 'proposta',
        linkedAgendaUid: null,
        sidebarCollapsed: false
      };

      function closeMobileSidebar() {
        const sb = document.getElementById('unified-sidebar');
        const bd = document.getElementById('mobile-shell-backdrop');
        if (sb) sb.classList.remove('mobile-open');
        if (bd) bd.classList.add('hidden');
      }

      function toggleSidebar() {
        const sb = document.getElementById('unified-sidebar');
        const bd = document.getElementById('mobile-shell-backdrop');
        if (!sb) return;
        if (window.innerWidth < 1024) {
          const opening = !sb.classList.contains('mobile-open');
          sb.classList.toggle('mobile-open', opening);
          if (bd) bd.classList.toggle('hidden', !opening);
        } else {
          stateHub.sidebarCollapsed = !stateHub.sidebarCollapsed;
          sb.classList.toggle('is-collapsed', stateHub.sidebarCollapsed);
          if (stateHub.activeModule === 'proposta' && window.PropostaBridge) {
            setTimeout(() => window.PropostaBridge.autoFitZoom(), 220);
          }
        }
      }

      function setOpenSubmenu(mod) {
        const valid = ['proposta', 'agenda', 'produtos', 'edital'];
        valid.forEach(m => {
          const sub = document.getElementById('sb-submenu-' + m);
          const btn = document.getElementById('nav-mod-' + m);
          const open = (m === mod);
          if (sub) sub.classList.toggle('hidden', !open);
          if (btn) btn.classList.toggle('is-open', open);
        });
      }

      function onSidebarModuleClick(mod, defaultSubView) {
        const sub = document.getElementById('sb-submenu-' + mod);
        const btn = document.getElementById('nav-mod-' + mod);
        if (stateHub.activeModule === mod && sub) {
          const willOpen = sub.classList.contains('hidden');
          sub.classList.toggle('hidden', !willOpen);
          if (btn) btn.classList.toggle('is-open', willOpen);
          return;
        }
        switchModule(mod, defaultSubView);
      }

      function switchModule(mod, subView) {
        const valid = ['proposta', 'agenda', 'produtos', 'edital'];
        if (!valid.includes(mod)) mod = 'proposta';
        stateHub.activeModule = mod;

        valid.forEach(m => {
          const container = document.getElementById('module-' + m);
          const navBtn = document.getElementById('nav-mod-' + m);
          const isTarget = (m === mod);
          if (container) {
            container.classList.toggle('hidden', !isTarget);
            if (m === 'proposta') container.classList.toggle('flex', isTarget);
            else container.classList.toggle('flex', isTarget);
          }
          if (navBtn) navBtn.classList.toggle('is-active', isTarget);
        });
        setOpenSubmenu(mod);

        if (mod === 'proposta') {
          if (subView && window.PropostaBridge) window.PropostaBridge.switchTab(subView);
          if (window.PropostaBridge) {
            setTimeout(() => window.PropostaBridge.autoFitZoom(), 80);
          }
        } else if (mod === 'agenda') {
          if (window.AgendaModule) {
            window.AgendaModule.switchTab(subView || 'list');
          }
        } else if (mod === 'produtos') {
          if (window.ProdutosModule && subView) {
            window.ProdutosModule.showView(subView);
          }
        } else if (mod === 'edital') {
          if (window.EditalModule) {
            window.EditalModule.showView(subView || 'analise');
          }
        }

        closeMobileSidebar();
        try { history.replaceState(null, '', '#' + mod); } catch (e) {}
      }

      function highlightPropostaTab(tabName) {
        ['licitacao', 'itens', 'empresa', 'historico'].forEach(t => {
          const el = document.getElementById('sb-prop-' + t);
          if (el) el.classList.toggle('is-active', t === tabName);
        });
      }

      function highlightAgendaTab(tabName) {
        ['list', 'calendar', 'alerts'].forEach(t => {
          const el = document.getElementById('sideNav-' + t);
          if (el) el.classList.toggle('is-active', t === tabName);
        });
      }

      function highlightProdutosView(viewName) {
        ['search', 'catalog', 'import', 'history'].forEach(v => {
          const el = document.getElementById('sb-prod-' + v);
          if (el) el.classList.toggle('is-active', v === viewName);
        });
      }

      function highlightEditalView(viewName) {
        ['analise', 'busca', 'itens', 'historico'].forEach(v => {
          const el = document.getElementById('sb-edital-' + v);
          if (el) el.classList.toggle('is-active', v === viewName);
        });
      }

      function syncShellTheme(companyId, companyData, themeObj) {
        const isNext = companyId === 'next';
        document.body.classList.toggle('shell-theme-next', isNext);
        const sub = document.getElementById('shell-brand-sub');
        if (sub && themeObj) sub.textContent = themeObj.shortName;
      }

      function updateSidebarBadges() {
        if (window.PropostaBridge) {
          const st = window.PropostaBridge.getState();
          const itEl = document.getElementById('sb-prop-items-count');
          const drEl = document.getElementById('sb-prop-drafts-count');
          if (itEl) itEl.textContent = window.PropostaBridge.getAllItemsFlat().length;
          if (drEl) drEl.textContent = (st.drafts || []).length;
        }
        if (window.AgendaModule) {
          const agStats = window.AgendaModule.getStats();
          const totEl = document.getElementById('sb-ag-total-badge');
          if (totEl) totEl.textContent = agStats.total;
        }
      }

      const serverModes = { proposta: 'local', agenda: 'local', produtos: 'local' };

      function refreshOverallServerStatus() {
        const dot = document.getElementById('sb-server-dot');
        const txt = document.getElementById('sb-server-txt');
        if (!dot || !txt) return;
        const modes = Object.values(serverModes);
        if (!navigator.onLine || modes.every(m => m === 'offline')) {
          dot.className = 'w-1.5 h-1.5 rounded-full bg-rose-400 shrink-0';
          txt.textContent = 'OFFLINE (Local)';
          txt.className = 'text-rose-300';
        } else if (modes.some(m => m === 'saving')) {
          dot.className = 'w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse shrink-0';
          txt.textContent = 'Salvando...';
          txt.className = 'text-amber-200';
        } else if (modes.some(m => m === 'offline')) {
          dot.className = 'w-1.5 h-1.5 rounded-full bg-amber-400 shrink-0';
          txt.textContent = 'Parcial (ON)';
          txt.className = 'text-amber-200';
        } else if (modes.some(m => m === 'synced')) {
          dot.className = 'w-1.5 h-1.5 rounded-full bg-emerald-400 shrink-0';
          txt.textContent = 'ONLINE';
          txt.className = 'text-emerald-300';
        } else {
          dot.className = 'w-1.5 h-1.5 rounded-full bg-sky-400 shrink-0';
          txt.textContent = 'Local';
          txt.className = 'text-sky-200';
        }
      }

      function updateFirebaseStatus(which, mode, label) {
        const colors = {
          synced: 'bg-emerald-400',
          saving: 'bg-amber-400 animate-pulse',
          offline: 'bg-rose-400',
          local: 'bg-sky-400'
        };
        const cls = 'w-1.5 h-1.5 rounded-full shrink-0 ' + (colors[mode] || 'bg-amber-400');
        if (which in serverModes) serverModes[which] = mode;
        if (which === 'proposta') {
          const d = document.getElementById('sb-fb-prop-dot');
          const t = document.getElementById('sb-fb-prop-txt');
          if (d) d.className = cls;
          if (t) t.textContent = label;
        } else if (which === 'agenda') {
          const d = document.getElementById('sb-fb-ag-dot');
          const t = document.getElementById('sb-fb-ag-txt');
          if (d) d.className = cls;
          if (t) t.textContent = label;
        } else if (which === 'produtos') {
          const d = document.getElementById('sb-fb-prod-dot');
          const t = document.getElementById('sb-fb-prod-txt');
          if (d) d.className = cls;
          if (t) t.textContent = label;
        }
        refreshOverallServerStatus();
      }

      // Monitoramento automático de rede + verificação periódica para evitar perda de dados
      function verifyServerHealth() {
        if (!navigator.onLine) {
          updateFirebaseStatus('proposta', 'offline', 'Sem internet');
          updateFirebaseStatus('agenda', 'offline', 'Sem internet');
          updateFirebaseStatus('produtos', 'offline', 'Sem internet');
          return;
        }
        refreshOverallServerStatus();
        // Garante envio de eventuais alterações pendentes na nuvem
        if (window.PropostaBridge && typeof window.PropostaBridge.flushCloudSaves === 'function') {
          try { window.PropostaBridge.flushCloudSaves(false); } catch (e) {}
        }
      }
      window.addEventListener('online', () => {
        refreshOverallServerStatus();
        setTimeout(verifyServerHealth, 1200);
      });
      window.addEventListener('offline', () => {
        verifyServerHealth();
      });
      setInterval(verifyServerHealth, 30000);

      function updateLinkedAgendaBanner() {
        const bar = document.getElementById('prop-agenda-link-bar');
        const txt = document.getElementById('prop-agenda-link-text');
        if (!bar || !txt) return;
        if (!stateHub.linkedAgendaUid || !window.AgendaModule) {
          bar.classList.add('hidden');
          return;
        }
        const rec = window.AgendaModule.getRecordByUid(stateHub.linkedAgendaUid);
        if (!rec) {
          bar.classList.add('hidden');
          return;
        }
        txt.textContent = `Vinculado à Agenda: ${rec.orgao || 'Órgão'} • Edital ${rec.edital || 'S/N'} (${rec.status || 'Aberto'})`;
        bar.classList.remove('hidden');
      }

      function unlinkAgendaBid() {
        stateHub.linkedAgendaUid = null;
        if (window.PropostaBridge) {
          const st = window.PropostaBridge.getState();
          delete st.bid.linkedAgendaUid;
          window.PropostaBridge.saveToStorage();
        }
        updateLinkedAgendaBanner();
      }

      function mapAgendaModalidade(modStr) {
        const s = String(modStr || '').toLowerCase();
        if (s.includes('dispensa')) return 'Dispensa Eletrônica';
        if (s.includes('concorr')) return 'Concorrência Eletrônica';
        if (s.includes('presencial')) return 'Pregão Presencial';
        if (s.includes('cota')) return 'Cotação Eletrônica';
        return 'Pregão Eletrônico';
      }

      // === SINCRONIZAÇÃO REAL 1: AGENDA -> PROPOSTA DE LICITAÇÃO ===
      function sendAgendaBidToProposta(rec) {
        if (!rec || !window.PropostaBridge) return;

        // Detecta automaticamente a empresa (Brava vs Next)
        const empNorm = String(rec.empresa || '').toLowerCase();
        if (empNorm.includes('next')) {
          window.PropostaBridge.switchCompanyProfile('next', true);
        } else if (empNorm.includes('brava')) {
          window.PropostaBridge.switchCompanyProfile('brava', true);
        }

        if (window.CheckpointManager) window.CheckpointManager.capture('proposta', 'Antes de carregar pregão da Agenda');
        const st = window.PropostaBridge.getState();
        st.bid.linkedAgendaUid = rec.uid;
        stateHub.linkedAgendaUid = rec.uid;

        if (rec.orgao && !/^https?:\/\//i.test(rec.orgao)) {
          st.bid.orgao = rec.orgao + (rec.uf ? ' / ' + rec.uf : '');
        }
        if (rec.edital) st.bid.numero = rec.edital;
        st.bid.modalidade = mapAgendaModalidade(rec.modalidade);
        if (rec.data) {
          const [y, m, d] = rec.data.split('-');
          const dtBR = (y && m && d) ? `${d}/${m}/${y}` : rec.data;
          st.bid.sessao = rec.horario ? `${dtBR} às ${rec.horario}` : dtBR;
        }
        if (rec.prazoEntrega) st.bid.prazoEntrega = rec.prazoEntrega;
        if (rec.objeto) st.bid.objeto = rec.objeto;

        window.PropostaBridge.saveToStorage();
        window.PropostaBridge.populateFormFromState();
        updateLinkedAgendaBanner();
        switchModule('proposta', 'licitacao');
        window.PropostaBridge.showToast(`Pregão ${rec.edital || ''} (${rec.orgao}) carregado e vinculado à Proposta!`);
      }

      // === SINCRONIZAÇÃO REAL 2: AGENDA -> BUSCAR PRODUTOS ===
      function sendAgendaBidToProdutos(rec) {
        if (!rec || !window.ProdutosModule) return;
        const query = (rec.objeto && rec.objeto.trim()) ? rec.objeto.trim() : (rec.orgao || '');
        switchModule('produtos', 'search');
        window.ProdutosModule.searchFromExternal(query);
      }

      // === SINCRONIZAÇÃO REAL 3: CATÁLOGO / LOTE -> PROPOSTA DE LICITAÇÃO ===
      function sendProdutosToProposta(itemsList, mode) {
        if (!Array.isArray(itemsList) || itemsList.length === 0 || !window.PropostaBridge) return;
        const st = window.PropostaBridge.getState();
        const existingItems = window.PropostaBridge.getAllItemsFlat().map(e => e.item);
        const hasRealExisting = existingItems.some(it => (it.descricao && it.descricao.trim()) || Number(it.unitario) > 0);

        let action = mode;
        if (mode === 'ask') {
          if (hasRealExisting) {
            action = confirm(`A Proposta atual já possui ${existingItems.length} item(ns).

Clique em OK para SOMAR os ${itemsList.length} item(ns) do Lote aos itens atuais, ou CANCELAR para SUBSTITUIR a tabela atual.`) ? 'append' : 'replace';
          } else {
            action = 'replace';
          }
        }

        const startNum = action === 'append' && hasRealExisting ? existingItems.length + 1 : 1;
        if (window.CheckpointManager) window.CheckpointManager.capture('proposta', `Antes de receber ${itemsList.length} item(ns) na Proposta`);
        const converted = itemsList.map((it, idx) => {
          const descFull = (it.fullSpec && String(it.fullSpec).trim())
            ? String(it.fullSpec).trim()
            : (it.specs ? `${it.name} — ${it.specs}` : it.name);
          return {
            id: window.PropostaBridge.generateId(),
            numero: String(startNum + idx),
            quant: Number(it.qty) || 1,
            unid: it.unit || 'UN',
            descricao: descFull,
            marca: it.brand || '',
            modelo: it.code || '',
            unitario: Number(it.price) || 0,
            unitarioInicial: Number(it.price) || 0,
            ganho: true
          };
        });

        if (!st.bid.groups || st.bid.groups.length === 0) {
          st.bid.groups = [{ id: window.PropostaBridge.generateId(), numero: '01', titulo: '', items: [] }];
        }

        if (action === 'replace' || !hasRealExisting) {
          st.bid.groups = [{ id: window.PropostaBridge.generateId(), numero: '01', titulo: '', items: converted }];
        } else {
          st.bid.groups[st.bid.groups.length - 1].items.push(...converted);
        }

        window.PropostaBridge.saveToStorage();
        window.PropostaBridge.populateFormFromState();
        switchModule('proposta', 'itens');
        window.PropostaBridge.showToast(`${converted.length} ${converted.length === 1 ? 'produto enviado' : 'produtos enviados'} do Catálogo para a Proposta!`);
      }

      // === SINCRONIZAÇÃO REAL 4: PROPOSTA DE LICITAÇÃO -> AGENDA ===
      function syncPropostaToAgenda() {
        if (!window.PropostaBridge || !window.AgendaModule) return;
        const st = window.PropostaBridge.getState();
        const theme = window.PropostaBridge.getActiveTheme();
        const total = window.PropostaBridge.computeGrandTotal();
        const itemCount = window.PropostaBridge.getAllItemsFlat().length;

        if (!st.bid.orgao.trim() && !st.bid.numero.trim()) {
          window.PropostaBridge.showToast('Preencha ao menos o Órgão Licitante ou Nº do Edital antes de sincronizar com a Agenda.');
          return;
        }

        const res = window.AgendaModule.syncFromProposta({
          linkedUid: stateHub.linkedAgendaUid || st.bid.linkedAgendaUid || null,
          orgao: st.bid.orgao.trim(),
          edital: st.bid.numero.trim(),
          data: st.bid.data,
          modalidade: st.bid.modalidade,
          objeto: st.bid.objeto.trim(),
          prazoEntrega: st.bid.prazoEntrega.trim(),
          empresa: theme.shortName,
          companyName: st.company.razao || theme.shortName,
          phase: st.bid.tipoProposta,
          valor: total,
          itemCount: itemCount
        });

        if (res && res.record) {
          stateHub.linkedAgendaUid = res.record.uid;
          st.bid.linkedAgendaUid = res.record.uid;
          window.PropostaBridge.saveToStorage();
          updateLinkedAgendaBanner();
          updateSidebarBadges();
          window.PropostaBridge.showToast(res.created
            ? `Novo pregão criado na Agenda (${res.record.orgao} — ${res.record.edital})!`
            : `Pregão atualizado na Agenda com valor e registro da Proposta!`);
        }
      }

      // === SINCRONIZAÇÃO REAL 5: EDIÇÃO NA AGENDA -> ATUALIZA PROPOSTA VINCULADA ===
      function onAgendaRecordUpdated(rec) {
        if (!rec || !window.PropostaBridge) return;
        const st = window.PropostaBridge.getState();
        const linkedId = stateHub.linkedAgendaUid || st.bid.linkedAgendaUid;
        if (!linkedId || linkedId !== rec.uid) return;

        if (rec.orgao && !/^https?:\/\//i.test(rec.orgao)) {
          st.bid.orgao = rec.orgao + (rec.uf ? ' / ' + rec.uf : '');
        }
        if (rec.edital) st.bid.numero = rec.edital;
        if (rec.data) {
          const [y, m, d] = rec.data.split('-');
          const dtBR = (y && m && d) ? `${d}/${m}/${y}` : rec.data;
          st.bid.sessao = rec.horario ? `${dtBR} às ${rec.horario}` : dtBR;
        }
        if (rec.objeto) st.bid.objeto = rec.objeto;
        if (rec.prazoEntrega) st.bid.prazoEntrega = rec.prazoEntrega;

        window.PropostaBridge.saveToStorage();
        window.PropostaBridge.populateFormFromState();
        updateLinkedAgendaBanner();
      }

      function openCatalogForProposta() {
        if (window.ProdutosModule) {
          const stats = window.ProdutosModule.getStats();
          if (stats.quote > 0) {
            switchModule('produtos', 'search');
            window.ProdutosModule.openQuote();
          } else {
            switchModule('produtos', 'search');
          }
        }
      }

      window.addEventListener('DOMContentLoaded', () => {
        setTimeout(() => {
          if (window.PropostaBridge) {
            const st = window.PropostaBridge.getState();
            if (st.bid && st.bid.linkedAgendaUid) {
              stateHub.linkedAgendaUid = st.bid.linkedAgendaUid;
              updateLinkedAgendaBanner();
            }
          }
          updateSidebarBadges();
          const hash = (window.location.hash || '').replace('#', '').toLowerCase();
          if (hash === 'agenda' || hash === 'produtos' || hash === 'proposta' || hash === 'edital') {
            switchModule(hash);
          }
        }, 60);
      });

      return {
        get activeModule() { return stateHub.activeModule; },
        toggleSidebar,
        closeMobileSidebar,
        switchModule,
        onSidebarModuleClick,
        highlightPropostaTab,
        highlightAgendaTab,
        highlightProdutosView,
        highlightEditalView,
        syncShellTheme,
        updateSidebarBadges,
        updateFirebaseStatus,
        unlinkAgendaBid,
        sendAgendaBidToProposta,
        sendAgendaBidToProdutos,
        sendProdutosToProposta,
        syncPropostaToAgenda,
        onAgendaRecordUpdated,
        openCatalogForProposta
      };
    })();

