      merged.compactLayout = merged.pdfDensity !== 'normal';
      if (!merged.pdfPageMode) merged.pdfPageMode = 'smart';
      if (merged.pdfRepeatHead === undefined) merged.pdfRepeatHead = true;
      if (merged.pdfKeepEndTogether === undefined) merged.pdfKeepEndTogether = true;
      if (merged.pdfBreakBetweenLots === undefined) merged.pdfBreakBetweenLots = false;
