    // =========================================================================
    // UTILITÁRIOS DE FORMATAÇÃO, ORTOGRAFIA, SEGURANÇA E VALOR POR EXTENSO
    // =========================================================================
    function escapeHtml(str) {
      if (str === null || str === undefined) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    function nl2br(str) {
      return escapeHtml(str).replace(/\n/g, '<br>');
    }

    function normalizeHeaderStr(str) {
      return String(str || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9\s]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function formatBRL(value) {
      const n = isNaN(value) ? 0 : Number(value);
      return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    }

    function formatNumberInput(value) {
      const n = isNaN(value) ? 0 : Number(value);
      return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }

    // Interpreta moeda PT-BR (R$ 19 284,69 | R$ 124.248,00 | 621,24) e formato US (621.24)
    function parseBRL(str) {
      if (typeof str === 'number') return isNaN(str) ? 0 : str;
      if (str === null || str === undefined) return 0;
      let s = String(str).replace(/[R$\u00A0\s]/g, '').trim();
      if (!s) return 0;

      const hasComma = s.includes(',');
      const hasDot = s.includes('.');

      if (hasComma && hasDot) {
        if (s.lastIndexOf(',') > s.lastIndexOf('.')) {
          s = s.replace(/\./g, '').replace(',', '.');
        } else {
          s = s.replace(/,/g, '');
        }
      } else if (hasComma) {
        s = s.replace(',', '.');
      } else if (hasDot) {
        // Ex.: "1.200" ou "10.000" (separador de milhar sem decimais) vs "621.24"
        const parts = s.split('.');
        if (parts.length > 2 || (parts.length === 2 && parts[1].length === 3 && parts[0].length <= 3)) {
          s = s.replace(/\./g, '');
        }
      }

      const parsed = parseFloat(s);
      return isNaN(parsed) ? 0 : parsed;
    }

    function parseQuantity(val) {
      if (typeof val === 'number') return isNaN(val) ? 0 : val;
      const s = String(val || '').replace(/[\u00A0\s]/g, '').trim();
      if (!s) return 0;
      if (s.includes(',') && !s.includes('.')) {
        return parseFloat(s.replace(',', '.')) || 0;
      }
      if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
        return parseFloat(s.replace(/\./g, '')) || 0;
      }
      return parseBRL(s);
    }

    function formatNumeroEdital(num) {
      const clean = String(num || '').trim();
      if (!clean) return 'nº ____/____';
      if (/^(n[º°o.]?\s*)/i.test(clean)) return clean;
      return `nº ${clean}`;
    }

    function maskCNPJ(input) {
      let v = input.value.replace(/\D/g, '').slice(0, 14);
      v = v.replace(/^(\d{2})(\d)/, '$1.$2');
      v = v.replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3');
      v = v.replace(/\.(\d{3})(\d)/, '.$1/$2');
      v = v.replace(/(\d{4})(\d)/, '$1-$2');
      input.value = v;
    }

    function maskCPF(input) {
      let v = input.value.replace(/\D/g, '').slice(0, 11);
      v = v.replace(/(\d{3})(\d)/, '$1.$2');
      v = v.replace(/(\d{3})(\d)/, '$1.$2');
      v = v.replace(/(\d{3})(\d{1,2})$/, '$1-$2');
      input.value = v;
    }

    function maskCEP(input) {
      let v = input.value.replace(/\D/g, '').slice(0, 8);
      v = v.replace(/^(\d{5})(\d)/, '$1-$2');
      input.value = v;
    }

    function maskPhone(input) {
      let v = input.value.replace(/\D/g, '').slice(0, 11);
      if (v.length > 10) {
        v = v.replace(/^(\d{2})(\d{5})(\d{4}).*/, '($1) $2-$3');
      } else if (v.length > 6) {
        v = v.replace(/^(\d{2})(\d{4})(\d{0,4}).*/, '($1) $2-$3');
      } else if (v.length > 2) {
        v = v.replace(/^(\d{2})(\d{0,5})/, '($1) $2');
      } else if (v.length > 0) {
        v = v.replace(/^(\d*)/, '($1');
      }
      input.value = v;
    }


    // =========================================================================
    // SINCRONIZAÇÃO AUTOMÁTICA DA DATA DO SISTEMA & VALIDADE DINÂMICA
    // =========================================================================
    function formatDateBRShort(isoDate) {
      if (!isoDate || !/^\d{4}-\d{2}-\d{2}$/.test(isoDate)) isoDate = getTodayISO();
      const [y, m, d] = isoDate.split('-');
      return `${d}/${m}/${y}`;
    }

    function addDaysToISO(isoDate, days) {
      const base = (isoDate && /^\d{4}-\d{2}-\d{2}$/.test(isoDate)) ? isoDate : getTodayISO();
      const [y, m, d] = base.split('-').map(Number);
      const dt = new Date(y, m - 1, d);
      dt.setDate(dt.getDate() + Number(days || 0));
      const ry = dt.getFullYear();
      const rm = String(dt.getMonth() + 1).padStart(2, '0');
      const rd = String(dt.getDate()).padStart(2, '0');
      return `${ry}-${rm}-${rd}`;
    }

    function computeFormattedValidade(validadeStr, baseIsoDate) {
      const raw = String(validadeStr || '').trim();
      if (!raw) return 'Conforme Edital';
      // Se contiver número de dias (ex: "60 dias", "90 dias corridos", "30 dias úteis"), recalcula data limite a partir da data atual
      const m = raw.match(/^(\d{1,3})\s*dias?(\s+(?:corridos|uteis|úteis))?$/i);
      if (m) {
        const qtdDias = parseInt(m[1], 10);
        if (qtdDias > 0 && qtdDias <= 730) {
          const expIso = addDaysToISO(baseIsoDate || getTodayISO(), qtdDias);
          return `${raw} (válida até ${formatDateBRShort(expIso)})`;
        }
      }
      return raw;
    }

    function ensureCurrentSystemDate(forceToday = false) {
      const today = getTodayISO();
      let changed = false;
      for (const pid of ['brava', 'next']) {
        if (state.bids[pid]) {
          if (forceToday || !state.bids[pid].data || state.bids[pid].data !== today) {
            state.bids[pid].data = today;
            changed = true;
          }
        }
      }
      const dateInput = document.getElementById('bid-data');
      if (dateInput && dateInput.value !== today) {
        dateInput.value = today;
      }
      if (changed) {
        try {
          localStorage.setItem(getBidStorageKey('brava'), JSON.stringify(state.bids.brava));
          localStorage.setItem(getBidStorageKey('next'), JSON.stringify(state.bids.next));
        } catch (e) {}
      }
      return today;
    }

    function formatDateExtenso(isoDate) {
      if (!isoDate || !/^\d{4}-\d{2}-\d{2}$/.test(isoDate)) {
        isoDate = getTodayISO();
      }
      const parts = isoDate.split('-').map(Number);
      const meses = [
        'janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho',
        'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'
      ];
      return `${String(parts[2]).padStart(2, '0')} de ${meses[parts[1] - 1]} de ${parts[0]}`;
    }

    function valorPorExtenso(valor) {
      const num = Math.round((Number(valor) || 0) * 100) / 100;
      if (num === 0) return 'Zero reais';

      const unidades = ['', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove'];
      const especiais = ['dez', 'onze', 'doze', 'treze', 'quatorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
      const dezenas = ['', 'dez', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
      const centenas = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos', 'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];

      function grupoParaTexto(n) {
        if (n === 0) return '';
        if (n === 100) return 'cem';
        const c = Math.floor(n / 100);
        const d = Math.floor((n % 100) / 10);
        const u = n % 10;
        const partes = [];
        if (c > 0) partes.push(centenas[c]);
        if (d === 1) {
          partes.push(especiais[u]);
        } else {
          if (d > 1) partes.push(dezenas[d]);
          if (u > 0) partes.push(unidades[u]);
        }
        return partes.join(' e ');
      }

      const inteiro = Math.floor(num);
      const centavos = Math.round((num - inteiro) * 100);

      const escalas = [
        { div: 1000000000000, sing: 'trilhão', plur: 'trilhões' },
        { div: 1000000000, sing: 'bilhão', plur: 'bilhões' },
        { div: 1000000, sing: 'milhão', plur: 'milhões' },
        { div: 1000, sing: 'mil', plur: 'mil' },
        { div: 1, sing: '', plur: '' }
      ];

      let resto = inteiro;
      const blocos = [];
      for (const esc of escalas) {
        const qtd = Math.floor(resto / esc.div);
        resto = resto % esc.div;
        if (qtd > 0) {
          let txt = '';
          if (esc.div === 1000 && qtd === 1 && blocos.length === 0) {
            txt = 'mil';
          } else {
            txt = grupoParaTexto(qtd) + (esc.sing ? ' ' + (qtd === 1 ? esc.sing : esc.plur) : '');
          }
          blocos.push({ valor: qtd, div: esc.div, texto: txt });
        }
      }

      let parteReais = '';
      if (blocos.length > 0) {
        for (let i = 0; i < blocos.length; i++) {
          if (i === 0) {
            parteReais += blocos[i].texto;
          } else {
            const isLast = i === blocos.length - 1;
            const b = blocos[i];
            if (isLast && b.div === 1 && (b.valor < 100 || b.valor % 100 === 0)) {
              parteReais += ' e ' + b.texto;
            } else if (isLast && b.div >= 1000 && blocos.length === 2 && (b.valor < 100 || b.valor % 100 === 0)) {
              parteReais += ' e ' + b.texto;
            } else {
              parteReais += ', ' + b.texto;
            }
          }
        }
        const usaDeReais = inteiro >= 1000000 && inteiro % 1000000 === 0;
        parteReais += inteiro === 1 ? ' real' : (usaDeReais ? ' de reais' : ' reais');
      }

      let parteCentavos = '';
      if (centavos > 0) {
        parteCentavos = grupoParaTexto(centavos) + (centavos === 1 ? ' centavo' : ' centavos');
      }

      let finalStr = '';
      if (parteReais && parteCentavos) {
        finalStr = parteReais + ' e ' + parteCentavos;
      } else {
        finalStr = parteReais || parteCentavos;
      }

      return finalStr.charAt(0).toUpperCase() + finalStr.slice(1);
    }

    function showToast(msg) {
      const el = document.getElementById('toast');
      document.getElementById('toast-msg').textContent = msg;
      el.classList.remove('hidden');
      clearTimeout(window._toastTimer);
      window._toastTimer = setTimeout(() => el.classList.add('hidden'), 3400);
    }

