    function restoreDefaultSignature() {
      const t = getActiveTheme();
      if (!t.defaultSignature) {
        showToast(`A ${t.shortName} não possui assinatura padrão embutida. Use "Trocar Imagem" para enviar a assinatura da ${t.shortName}.`);
        return;
      }
      state.company.signature = t.defaultSignature;
      state.company.signatureRemovedManually = false;
      saveToStorage();
      updateImagePreviews();
      renderPreview();
      showToast(`Assinatura padrão da ${t.shortName} restaurada!`);
    }

