    // Ignora SEMPRE: Unitário do Edital, Total do Edital, Total Final, Descrição, etc.
    // =========================================================================
    function setProposalType(type) {
      const next = type === 'readequada' ? 'readequada' : 'inicial';
      state.bid.tipoProposta = next;
      // Garante que em Readequada o rótulo de preço nunca fique preso em "do Edital"
      if (next === 'readequada' && state.bid.colPrecoEstilo === 'edital') {
        state.bid.colPrecoEstilo = 'auto';
        const sel = document.getElementById('bid-col-preco-estilo');
        if (sel) sel.value = 'auto';
      }
      saveToStorage();
      updateProposalPhaseUI();
      renderItemsEditor();
      renderPreview();
      showToast(next === 'readequada'
        ? 'Modo Proposta Readequada ativo! Puxa somente Item, Quantidade, Marca, Modelo e Unitário Final.'
        : 'Modo Proposta Inicial (Antes da Disputa) ativado!');
    }

