    // Detector ESTRITO por nomenclatura para Proposta Readequada:
    // Aceita SOMENTE: Item | Quantidade | Marca | Modelo | Unitário Final
    // Bloqueia explicitamente qualquer coluna com "Edital", "Total", "Descrição", "Lote/Grupo", etc.
    function detectReadequadaHeaderColumns(row) {
      const map = {};
      const ignored = [];
      let hits = 0;

      row.forEach((cell, idx) => {
        const rawLabel = String(cell || '').trim();
        const h = normalizeHeaderStr(rawLabel);
        if (!h) return;

        // 1. Bloqueio absoluto: NUNCA puxar nada de "Edital", "Total", "Subtotal", "Descrição" ou "Lote/Grupo"
        if (/\bedital\b/.test(h)) {
          ignored.push(rawLabel);
          return;
        }
        if (/\b(total|subtotal|v total|vlr total|valor total|preco total)\b/.test(h)) {
          ignored.push(rawLabel);
          return;
        }
        if (/\b(desc|descricao|especificacao|especificacoes|objeto|discriminacao|detalhamento|produto|produtos|material|servico|servicos)\b/.test(h)) {
          ignored.push(rawLabel);
          return;
        }
        if (/\b(lote|lotes|grupo|grupos|agrupamento)\b/.test(h) && !/\bitem\b/.test(h)) {
          ignored.push(rawLabel);
          return;
        }
        if (/\b(unid|unidade|und|medida|embalagem)\b/.test(h) && !/\b(unit|unitario|final)\b/.test(h)) {
          ignored.push(rawLabel);
          return;
        }

        // 2. Nomenclatura exata dos 5 campos permitidos:
        //    Unitário Final (OBRIGATÓRIO conter palavra de preço final/readequado — nunca "Unitário" genérico ou "do Edital")
        const isUnitFinal = /\b(unit|unitario|un|preco|valor|vlr)\b/.test(h) && /\b(final|readequado|readequada|ganho|vencedor|lance|realinhado)\b/.test(h);

        if (map.unitario === undefined && isUnitFinal) {
          map.unitario = idx; hits++;
        } else if (map.quant === undefined && /\b(quantidade|quant|qtd|qtde|qnt|qntd)\b/.test(h)) {
          map.quant = idx; hits++;
        } else if (map.marca === undefined && /\b(marca|fabricante)\b/.test(h)) {
          map.marca = idx; hits++;
        } else if (map.modelo === undefined && /\b(modelo|modelos)\b/.test(h)) {
          map.modelo = idx; hits++;
        } else if (map.item === undefined && /\b(item|itens)\b/.test(h) && !/\b(total|unit|unitario|desc|valor|preco|quant|edital)\b/.test(h)) {
          map.item = idx; hits++;
        } else {
          // Outras colunas (ex.: "Unitário" avulso sem "Final", observações, etc.) ficam explicitamente ignoradas
          ignored.push(rawLabel);
        }
      });

      return { map, hits, ignored };
    }

    function trimEmptyOuterColumns(rows) {
      const nonEmptyRows = rows.filter(r => Array.isArray(r) && r.some(c => String(c === null || c === undefined ? '' : c).trim() !== ''));
      if (nonEmptyRows.length === 0) return [];
      const maxCols = nonEmptyRows.reduce((m, r) => Math.max(m, r.length), 0);

      let firstUsed = 0;
      while (firstUsed < maxCols && nonEmptyRows.every(r => String(r[firstUsed] === undefined || r[firstUsed] === null ? '' : r[firstUsed]).trim() === '')) {
        firstUsed++;
      }
      let lastUsed = maxCols - 1;
      while (lastUsed >= firstUsed && nonEmptyRows.every(r => String(r[lastUsed] === undefined || r[lastUsed] === null ? '' : r[lastUsed]).trim() === '')) {
        lastUsed--;
      }
      return nonEmptyRows.map(r => r.slice(firstUsed, lastUsed + 1));
    }

    function parseReadequadaMatrix(rawRows) {
      const rows = trimEmptyOuterColumns(rawRows);
      if (rows.length === 0) {
        return { error: 'Nenhum dado encontrado. Cole ou suba a tabela com: Item, Quantidade, Marca, Modelo e Unitário Final.' };
      }

      // 1. Procura a linha de cabeçalho nas primeiras 15 linhas, dando prioridade absoluta à linha com "Unitário Final"
      let headerIdx = -1;
      let colMap = {};
      let ignoredHeaders = [];
      let bestScore = 0;

      for (let i = 0; i < Math.min(rows.length, 15); i++) {
        const res = detectReadequadaHeaderColumns(rows[i]);
        const score = res.hits + (res.map.unitario !== undefined ? 10 : 0);
        if (res.hits >= 2 && score > bestScore) {
          bestScore = score;
          headerIdx = i;
          colMap = res.map;
          ignoredHeaders = res.ignored;
        }
      }

      const startRow = headerIdx >= 0 ? headerIdx + 1 : 0;

      // 2. Validação rígida de nomenclatura:
      if (headerIdx >= 0) {
        if (colMap.unitario === undefined) {
          return {
            error: 'Coluna "Unitário Final" não encontrada no cabeçalho! Na Proposta Readequada, o sistema ignora "Unitário do Edital" e "Total do Edital" e puxa exclusivamente a coluna chamada "Unitário Final".'
          };
        }
      } else {
        // Colou SEM linha de cabeçalho: só aceita se forem exatamente 5 colunas na ordem da imagem
        // (Item | Quantidade | Marca | Modelo | Unitário Final) para NUNCA puxar Unitário do Edital por engano!
        const colCount = rows.reduce((m, r) => Math.max(m, r.length), 0);
        if (colCount === 5) {
          colMap = { item: 0, quant: 1, marca: 2, modelo: 3, unitario: 4 };
        } else {
          return {
            error: `Foram detectadas ${colCount} colunas sem cabeçalho. Cole incluindo a linha de cabeçalho (Item, Quantidade, Marca, Modelo, Unitário Final) para o sistema identificar exatamente a coluna "Unitário Final" e ignorar o restante.`
          };
        }
      }

      const onlyFilled = document.getElementById('readequada-only-filled')
        ? document.getElementById('readequada-only-filled').checked
        : true;

      const items = [];
      let skippedNoPrice = 0;

      for (let i = startRow; i < rows.length; i++) {
        const r = rows[i];
        if (r.every(c => String(c === null || c === undefined ? '' : c).trim() === '')) continue;
        if (isSummaryOrNoiseRow(r)) continue;

        // Ignora cabeçalhos repetidos no meio da planilha
        if (headerIdx >= 0 && detectReadequadaHeaderColumns(r).hits >= 3) continue;

        const rawItem = colMap.item !== undefined ? String(r[colMap.item] === undefined || r[colMap.item] === null ? '' : r[colMap.item]).trim() : '';
        const rawQuant = colMap.quant !== undefined ? r[colMap.quant] : '';
        const rawMarca = colMap.marca !== undefined ? String(r[colMap.marca] === undefined || r[colMap.marca] === null ? '' : r[colMap.marca]).trim() : '';
        const rawModelo = colMap.modelo !== undefined ? String(r[colMap.modelo] === undefined || r[colMap.modelo] === null ? '' : r[colMap.modelo]).trim() : '';
        const rawUnit = colMap.unitario !== undefined ? r[colMap.unitario] : '';

        const quant = parseQuantity(rawQuant);
        const unitario = parseBRL(rawUnit);

        // Ignora linha totalmente vazia nos 5 campos
        if (!rawItem && !rawMarca && !rawModelo && unitario <= 0) continue;

        // Se marcado "somente itens com Unitário Final preenchido", pula itens não ganhos
        if (onlyFilled && unitario <= 0) {
          skippedNoPrice++;
          continue;
        }

        items.push({
          id: generateId(),
          numero: rawItem || String(items.length + 1),
          quant: quant > 0 ? quant : 1,
          unid: 'UN',
          descricao: '',
          marca: rawMarca,
          modelo: rawModelo,
          unitario: unitario
        });
      }

      if (items.length === 0) {
        if (skippedNoPrice > 0) {
          return {
            error: `A coluna "Unitário Final" foi localizada, mas nenhuma das ${skippedNoPrice} linhas tem valor preenchido (> R$ 0,00). Preencha o Unitário Final dos itens ganhos ou desmarque o filtro acima.`
          };
        }
        return { error: 'Nenhum item encontrado abaixo do cabeçalho. Cole também as linhas com os dados ganhos.' };
      }

      const total = items.reduce((sum, it) => {
        const sub = Math.round(((Number(it.quant) || 0) * (Number(it.unitario) || 0)) * 100) / 100;
        return Math.round((sum + sub) * 100) / 100;
      }, 0);

      return {
        items,
        total,
        colMap,
        ignoredHeaders,
        skippedNoPrice,
        usedHeader: headerIdx >= 0
      };
    }

    function renderReadequadaResult(res, forceToast = false) {
      const box = document.getElementById('readequada-preview-box');
      const errBox = document.getElementById('readequada-error-box');

      if (!res || res.error) {
        importState.readequadaItems = null;
        box.classList.add('hidden');
        if (res && res.error) {
          errBox.textContent = '⚠️ ' + res.error;
          errBox.classList.remove('hidden');
          if (forceToast) showToast(res.error);
        } else {
          errBox.classList.add('hidden');
        }
        return;
      }

      errBox.classList.add('hidden');
      importState.readequadaItems = res.items;
      box.classList.remove('hidden');

      document.getElementById('readequada-summary-title').textContent =
        `${res.items.length} ${res.items.length === 1 ? 'item pronto' : 'itens prontos'} para a Proposta Readequada`;
      document.getElementById('readequada-summary-total').textContent =
        `Total Final: ${formatBRL(res.total)} (${valorPorExtenso(res.total)})`;

      // Exibe badges exatas das colunas puxadas e das colunas ignoradas
      const colLabels = {
        item: 'Item',
        quant: 'Quantidade',
        marca: 'Marca',
        modelo: 'Modelo',
        unitario: 'Unitário Final'
      };
      const pickedBadges = ['item', 'quant', 'marca', 'modelo', 'unitario']
        .filter(k => res.colMap[k] !== undefined)
        .map(k => `<span class="px-1.5 py-0.5 rounded bg-white border border-emerald-300 text-emerald-900 text-[10px] font-semibold">✓ ${colLabels[k]}</span>`)
        .join('');

      let infoHtml = `<div class="flex flex-wrap gap-1">${pickedBadges}</div>`;
      if (res.ignoredHeaders && res.ignoredHeaders.length > 0) {
        infoHtml += `<p class="text-[10px] text-slate-600"><strong>Ignoradas:</strong> ${escapeHtml(res.ignoredHeaders.join(', '))}</p>`;
      }
      if (res.skippedNoPrice > 0) {
        infoHtml += `<p class="text-[10px] text-amber-800 font-medium">${res.skippedNoPrice} ${res.skippedNoPrice === 1 ? 'linha sem Unitário Final preenchido foi ignorada' : 'linhas sem Unitário Final preenchido foram ignoradas'}.</p>`;
      }
      document.getElementById('readequada-cols-info').innerHTML = infoHtml;

      document.getElementById('readequada-preview-tbody').innerHTML = res.items.map(it => {
        const sub = Math.round(((Number(it.quant) || 0) * (Number(it.unitario) || 0)) * 100) / 100;
        return `
          <tr>
            <td class="px-1.5 py-1 text-center font-bold text-[#1e2f53]">${escapeHtml(it.numero)}</td>
            <td class="px-1.5 py-1 text-center">${Number(it.quant).toLocaleString('pt-BR')}</td>
            <td class="px-1.5 py-1 text-left">${escapeHtml(it.marca || '-')}</td>
            <td class="px-1.5 py-1 text-left">${escapeHtml(it.modelo || '-')}</td>
            <td class="px-1.5 py-1 text-right whitespace-nowrap">${formatBRL(it.unitario)}</td>
            <td class="px-1.5 py-1 text-right whitespace-nowrap font-bold text-emerald-700">${formatBRL(sub)}</td>
          </tr>
        `;
      }).join('');

      const existingHasDesc = getAllItemsFlat().some(e => e.item.descricao && e.item.descricao.trim() !== '');
      const mergeBtn = document.getElementById('btn-read-keep-desc');
      if (mergeBtn) {
        mergeBtn.classList.toggle('hidden', !existingHasDesc);
      }
    }

    function handleReadequadaPaste(forceToast = false) {
      const area = document.getElementById('readequada-paste-area');
      const text = area ? area.value : '';

      if (!text.trim()) {
        importState.readequadaLastRows = null;
        renderReadequadaResult(null);
        if (forceToast) showToast('Cole a tabela no campo acima primeiro.');
        return;
      }

      const rawRows = parseDelimitedText(text);
      importState.readequadaLastRows = rawRows;
      renderReadequadaResult(parseReadequadaMatrix(rawRows), forceToast);
    }

    function reanalyzeCurrentReadequadaSource() {
      if (importState.readequadaLastRows) {
        renderReadequadaResult(parseReadequadaMatrix(importState.readequadaLastRows), false);
      }
    }

    function clearReadequadaPaste() {
      const area = document.getElementById('readequada-paste-area');
      if (area) area.value = '';
      importState.readequadaLastRows = null;
      importState.readequadaItems = null;
      document.getElementById('readequada-preview-box').classList.add('hidden');
      document.getElementById('readequada-error-box').classList.add('hidden');
    }

    // Upload de arquivo Excel / ODS / CSV na aba Readequada
    function handleReadDropzoneOver(e) {
      e.preventDefault();
      document.getElementById('read-file-dropzone').classList.add('dropzone-active');
    }

    function handleReadDropzoneLeave(e) {
      e.preventDefault();
      document.getElementById('read-file-dropzone').classList.remove('dropzone-active');
    }

    function handleReadDropzoneDrop(e) {
      e.preventDefault();
      document.getElementById('read-file-dropzone').classList.remove('dropzone-active');
      const file = e.dataTransfer && e.dataTransfer.files ? e.dataTransfer.files[0] : null;
      if (file) processReadequadaFile(file);
    }

    function handleReadequadaFile(event) {
      const file = event.target.files[0];
      if (file) processReadequadaFile(file);
      event.target.value = '';
    }

    function processReadequadaFile(file) {
      const ext = (file.name.split('.').pop() || '').toLowerCase();
      if ((ext === 'csv' || ext === 'tsv' || ext === 'txt') && typeof XLSX === 'undefined') {
        const reader = new FileReader();
        reader.onload = e => {
          const rows = parseDelimitedText(e.target.result);
          importState.readequadaLastRows = rows;
          renderReadequadaResult(parseReadequadaMatrix(rows), true);
        };
        reader.readAsText(file, 'UTF-8');
        return;
      }

      if (typeof XLSX === 'undefined') {
        showToast('Biblioteca Excel indisponível offline. Copie as células e use "Copiar e Colar".');
        return;
      }

      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const data = new Uint8Array(e.target.result);
          const wb = XLSX.read(data, { type: 'array' });
          importState.readequadaWorkbook = wb;

          const wrap = document.getElementById('read-sheet-selector-wrap');
          const sel = document.getElementById('read-sheet-selector');
          sel.innerHTML = wb.SheetNames.map(name => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('');

          // Se houver uma aba cujo nome contenha "final" ou "readequada", seleciona automaticamente!
          const autoTab = wb.SheetNames.find(n => /final|readequa|ganh/i.test(normalizeHeaderStr(n)));
          if (autoTab) sel.value = autoTab;

          wrap.classList.toggle('hidden', wb.SheetNames.length <= 1);
          parseSelectedReadequadaSheet();
        } catch (err) {
          console.error(err);
          showToast('Não foi possível ler a planilha.');
        }
      };
      reader.readAsArrayBuffer(file);
    }

    function parseSelectedReadequadaSheet() {
      if (!importState.readequadaWorkbook) return;
      const sheetName = document.getElementById('read-sheet-selector').value || importState.readequadaWorkbook.SheetNames[0];
      const ws = importState.readequadaWorkbook.Sheets[sheetName];
      if (!ws) return;
      const rows = extractRowsWithMerges(ws);
      importState.readequadaLastRows = rows;
      renderReadequadaResult(parseReadequadaMatrix(rows), true);
    }

    function applyReadequadaPaste(mode) {
      const pasted = importState.readequadaItems;
      if (!pasted || pasted.length === 0) return;
      if (window.CheckpointManager) window.CheckpointManager.capture('proposta', `Antes de aplicar Proposta Readequada (${pasted.length} itens)`);

      const normalizeItemKey = v => String(v || '').trim().replace(/^0+(?=\d)/, '').toLowerCase();

      if (mode === 'merge_desc') {
        const descByItem = new Map();
        const unidByItem = new Map();
        getAllItemsFlat().forEach(({ item }) => {
          const k = normalizeItemKey(item.numero);
          if (k && item.descricao && item.descricao.trim()) {
            descByItem.set(k, item.descricao);
          }
          if (k && item.unid) unidByItem.set(k, item.unid);
        });

        const mergedItems = pasted.map(it => {
          const k = normalizeItemKey(it.numero);
          return {
            ...it,
            id: generateId(),
            descricao: descByItem.get(k) || '',
            unid: unidByItem.get(k) || it.unid || 'UN'
          };
        });

        state.bid.modoDisputa = 'item';
        state.bid.groups = [{
          id: generateId(),
          numero: '01',
          titulo: '',
          items: mergedItems
        }];
      } else {
        // Puxa exclusivamente os 5 campos colados (Item, Quantidade, Marca, Modelo, Unitário Final)
        const cleanItems = pasted.map(it => ({ ...it, id: generateId(), descricao: '' }));
        state.bid.modoDisputa = 'item';
        state.bid.groups = [{
          id: generateId(),
          numero: '01',
          titulo: '',
          items: cleanItems
        }];
      }

      saveToStorage();
      populateFormFromState();
      clearReadequadaPaste();
      showToast(`Proposta Readequada montada com ${pasted.length} ${pasted.length === 1 ? 'item' : 'itens'} (Unitário Final)!`);
    }

    // =========================================================================
    // GERENCIADOR DINÂMICO DE ITENS E GRUPOS / LOTES
    // =========================================================================
    function setDisputaMode(mode) {
      state.bid.modoDisputa = mode === 'lote' ? 'lote' : 'item';
      if (!state.bid.groups || state.bid.groups.length === 0) {
        state.bid.groups = [createEmptyGroup('01', '')];
      }
      saveToStorage();
      updateModeButtonsUI();
      renderItemsEditor();
      renderPreview();
    }

    function updateModeButtonsUI() {
      const isLote = state.bid.modoDisputa === 'lote';
      const label = state.bid.rotuloGrupo || 'Lote';

      const btnItem = document.getElementById('mode-btn-item');
      const btnLote = document.getElementById('mode-btn-lote');
      const loteControls = document.getElementById('lote-controls-bar');
      const btnAddGroup = document.getElementById('btn-add-group');
      const btnAddGroupText = document.getElementById('btn-add-group-text');
      const btnAddFlat = document.getElementById('btn-add-flat-item');
      const sectionTitle = document.getElementById('items-section-title');

      if (isLote) {
        btnLote.classList.add('bg-[#1e2f53]', 'text-white', 'shadow-sm');
        btnLote.classList.remove('text-slate-600');
        btnItem.classList.remove('bg-[#1e2f53]', 'text-white', 'shadow-sm');
        btnItem.classList.add('text-slate-600');

        loteControls.classList.remove('hidden');
        btnAddGroup.classList.remove('hidden');
        btnAddGroupText.textContent = `Adicionar ${label}`;
        btnAddFlat.classList.add('hidden');
        sectionTitle.textContent = `${label}s e Itens da Proposta`;
      } else {
        btnItem.classList.add('bg-[#1e2f53]', 'text-white', 'shadow-sm');
        btnItem.classList.remove('text-slate-600');
        btnLote.classList.remove('bg-[#1e2f53]', 'text-white', 'shadow-sm');
        btnLote.classList.add('text-slate-600');

        loteControls.classList.add('hidden');
        btnAddGroup.classList.add('hidden');
        btnAddFlat.classList.remove('hidden');
        sectionTitle.textContent = 'Itens da Proposta';
      }
    }

    function getAllItemsFlat() {
      const list = [];
      (state.bid.groups || []).forEach((g, gIdx) => {
        (g.items || []).forEach((item, iIdx) => {
          list.push({ gIdx, iIdx, item, group: g });
        });
      });
      return list;
    }

    function getActiveItemsFlat() {
      return getAllItemsFlat();
    }

    function computeGroupTotal(group) {
      return (group.items || []).reduce((acc, it) => {
        const sub = Math.round(((Number(it.quant) || 0) * (Number(it.unitario) || 0)) * 100) / 100;
        return Math.round((acc + sub) * 100) / 100;
      }, 0);
    }

    function computeGrandTotal() {
      return (state.bid.groups || []).reduce((acc, g) => {
        return Math.round((acc + computeGroupTotal(g)) * 100) / 100;
      }, 0);
    }

    function renderItemCardHTML(item, gIdx, iIdx, visualIndex) {
      const isRead = state.bid.tipoProposta === 'readequada';
      const sub = (Number(item.quant) || 0) * (Number(item.unitario) || 0);

      const descSectionHtml = isRead ? `
          <details ${item.descricao && item.descricao.trim() ? 'open' : ''} class="pt-0.5">
            <summary class="text-[11px] font-semibold text-slate-500 cursor-pointer select-none hover:text-slate-700">
              Descrição do Edital (opcional na readequada)
            </summary>
            <textarea rows="2" placeholder="Opcional — deixe vazio para exibir somente Item, Quantidade, Marca, Modelo, Unitário Final e Total Final..." oninput="updateItemField(${gIdx}, ${iIdx}, 'descricao', this.value)" class="mt-1 w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]">${escapeHtml(item.descricao)}</textarea>
          </details>
      ` : `
          <div>
            <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Descrição Detalhada (do Edital) *</label>
            <textarea rows="3" placeholder="Cole aqui a especificação do produto/serviço conforme o Termo de Referência..." oninput="updateItemField(${gIdx}, ${iIdx}, 'descricao', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]">${escapeHtml(item.descricao)}</textarea>
          </div>
      `;

      return `
        <div class="border border-slate-200 bg-white rounded-xl p-3 space-y-2.5 shadow-sm">
          <div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-2">
            <span class="text-xs font-bold text-[#1e2f53]">Registro #${visualIndex} — Item <span id="item-num-lbl-${gIdx}-${iIdx}">${escapeHtml(item.numero || '-')}</span></span>
            <div class="flex items-center gap-1.5">
              <button onclick="duplicateItem(${gIdx}, ${iIdx})" title="Duplicar item" class="px-2 py-1 rounded bg-slate-50 border border-slate-200 hover:bg-slate-100 text-[11px] font-medium text-slate-600">Duplicar</button>
              <button onclick="removeItem(${gIdx}, ${iIdx})" title="Remover item" class="px-2 py-1 rounded bg-red-50 border border-red-200 hover:bg-red-100 text-[11px] font-semibold text-red-600">Excluir</button>
            </div>
          </div>

          <div class="grid grid-cols-12 gap-2">
            <div class="col-span-4 sm:col-span-3">
              <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Item *</label>
              <input type="text" value="${escapeHtml(item.numero)}" placeholder="Ex: 1" oninput="updateItemField(${gIdx}, ${iIdx}, 'numero', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]" />
            </div>
            <div class="col-span-4 sm:col-span-3">
              <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Quantidade *</label>
              <input type="number" step="any" min="0" value="${item.quant}" oninput="updateItemField(${gIdx}, ${iIdx}, 'quant', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]" />
            </div>
            <div class="col-span-4 sm:col-span-2">
              <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Unid.</label>
              <input type="text" value="${escapeHtml(item.unid || 'UN')}" placeholder="UN" oninput="updateItemField(${gIdx}, ${iIdx}, 'unid', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]" />
            </div>
            <div class="col-span-12 sm:col-span-4">
              <label class="block text-[11px] font-semibold ${isRead ? 'text-emerald-800' : 'text-slate-600'} mb-0.5">${isRead ? 'Unitário Final (R$) *' : 'Valor Unitário (R$) *'}</label>
              <input type="text" value="${formatNumberInput(item.unitario)}" oninput="updateItemCurrency(${gIdx}, ${iIdx}, this.value)" onblur="this.value = formatNumberInput(state.bid.groups[${gIdx}].items[${iIdx}].unitario)" class="w-full rounded-lg border ${isRead ? 'border-emerald-400 bg-emerald-50/40' : 'border-slate-300 bg-white'} px-2.5 py-1.5 text-xs font-semibold text-right outline-none focus:ring-2 focus:ring-[#1fa6da]" />
            </div>
          </div>

          <div class="grid grid-cols-12 gap-2 items-end">
            <div class="col-span-6 sm:col-span-4">
              <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Marca</label>
              <input type="text" value="${escapeHtml(item.marca)}" placeholder="Informe a marca" oninput="updateItemField(${gIdx}, ${iIdx}, 'marca', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]" />
            </div>
            <div class="col-span-6 sm:col-span-4">
              <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Modelo</label>
              <input type="text" value="${escapeHtml(item.modelo)}" placeholder="Informe o modelo" oninput="updateItemField(${gIdx}, ${iIdx}, 'modelo', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]" />
            </div>
            <div class="col-span-12 sm:col-span-4 bg-slate-50 border border-slate-200 rounded-lg px-2.5 py-1.5 text-right">
              <span class="block text-[10px] uppercase text-slate-500 font-semibold">${isRead ? 'Total Final' : 'Subtotal do Item'}</span>
              <span id="item-sub-${gIdx}-${iIdx}" class="text-xs font-bold text-emerald-700">${formatBRL(sub)}</span>
            </div>
          </div>

          ${descSectionHtml}
        </div>
      `;
    }

    function renderItemsEditor() {
      const container = document.getElementById('items-editor-list');
      const allFlat = getAllItemsFlat();
      document.getElementById('items-count-badge').textContent = allFlat.length;
      if (window.PlatformHub) window.PlatformHub.updateSidebarBadges();

      const isLote = state.bid.modoDisputa === 'lote';
      const label = state.bid.rotuloGrupo || 'Lote';

      if (!isLote) {
        if (allFlat.length === 0) {
          container.innerHTML = `
            <div class="text-center py-8 bg-slate-50 border border-dashed border-slate-300 rounded-xl">
              <p class="text-sm text-slate-500 mb-3">Nenhum item adicionado nesta proposta.</p>
              <button onclick="addItem(0)" class="px-4 py-2 rounded-lg bg-[#1e2f53] text-white text-xs font-semibold">+ Adicionar Primeiro Item</button>
            </div>`;
          updateGrandTotalSummary();
          return;
        }

        container.innerHTML = allFlat
          .map((entry, idx) => renderItemCardHTML(entry.item, entry.gIdx, entry.iIdx, idx + 1))
          .join('');
      } else {
        if (state.bid.groups.length === 0) {
          container.innerHTML = `
            <div class="text-center py-8 bg-slate-50 border border-dashed border-slate-300 rounded-xl">
              <p class="text-sm text-slate-500 mb-3">Nenhum ${escapeHtml(label.toLowerCase())} adicionado.</p>
              <button onclick="addGroup()" class="px-4 py-2 rounded-lg bg-[#1e2f53] text-white text-xs font-semibold">+ Adicionar ${escapeHtml(label)} 01</button>
            </div>`;
          updateGrandTotalSummary();
          return;
        }

        container.innerHTML = state.bid.groups.map((group, gIdx) => {
          const gTotal = computeGroupTotal(group);
          const itemsHtml = group.items.length > 0
            ? group.items.map((it, iIdx) => renderItemCardHTML(it, gIdx, iIdx, iIdx + 1)).join('')
            : `<div class="text-center py-4 bg-white border border-dashed border-slate-300 rounded-lg text-xs text-slate-500">Nenhum item neste ${escapeHtml(label.toLowerCase())}.</div>`;

          return `
            <div class="border-2 border-[#1e2f53]/25 rounded-xl overflow-hidden bg-slate-50 shadow-sm">
              <!-- Cabeçalho do Grupo / Lote -->
              <div class="bg-[#1e2f53] text-white px-3.5 py-2.5 flex flex-wrap items-center justify-between gap-2 border-b-2 border-[#1fa6da]">
                <div class="flex flex-wrap items-center gap-2">
                  <span id="group-badge-${gIdx}" class="px-2 py-0.5 rounded bg-[#1fa6da] text-white text-[11px] font-bold uppercase">${escapeHtml(label)} ${escapeHtml(group.numero || String(gIdx + 1).padStart(2, '0'))}</span>
                  <span class="text-xs font-semibold text-sky-100">(${group.items.length} ${group.items.length === 1 ? 'item' : 'itens'})</span>
                </div>
                <div class="flex items-center gap-1.5">
                  <button onclick="duplicateGroup(${gIdx})" class="px-2 py-1 rounded bg-white/10 hover:bg-white/20 text-[11px] font-medium transition">Duplicar ${escapeHtml(label)}</button>
                  <button onclick="removeGroup(${gIdx})" class="px-2 py-1 rounded bg-red-500/80 hover:bg-red-500 text-[11px] font-semibold transition">Excluir</button>
                </div>
              </div>

              <!-- Campos de Identificação do Grupo / Lote -->
              <div class="p-3 bg-sky-50/60 border-b border-slate-200 grid grid-cols-12 gap-2">
                <div class="col-span-4 sm:col-span-3">
                  <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Nº do ${escapeHtml(label)} *</label>
                  <input type="text" value="${escapeHtml(group.numero)}" placeholder="Ex: 01" oninput="updateGroupField(${gIdx}, 'numero', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs font-semibold outline-none focus:ring-2 focus:ring-[#1fa6da]" />
                </div>
                <div class="col-span-8 sm:col-span-9">
                  <label class="block text-[11px] font-semibold text-slate-600 mb-0.5">Título / Descrição do ${escapeHtml(label)} (Opcional)</label>
                  <input type="text" value="${escapeHtml(group.titulo)}" placeholder="Ex: Equipamentos Esportivos" oninput="updateGroupField(${gIdx}, 'titulo', this.value)" class="w-full rounded-lg border border-slate-300 bg-white px-2.5 py-1.5 text-xs outline-none focus:ring-2 focus:ring-[#1fa6da]" />
                </div>
              </div>

              <!-- Itens do Grupo / Lote -->
              <div class="p-3 space-y-2.5">
                ${itemsHtml}

                <div class="flex flex-wrap items-center justify-between gap-2 pt-1">
                  <button onclick="addItem(${gIdx})" class="px-3 py-1.5 rounded-lg bg-white border border-[#1e2f53] text-[#1e2f53] hover:bg-[#1e2f53] hover:text-white text-xs font-semibold transition">
                    + Adicionar Item no ${escapeHtml(label)} ${escapeHtml(group.numero || '')}
                  </button>
                  <div class="text-right">
                    <span class="text-[11px] font-semibold uppercase text-slate-500 mr-1.5">Subtotal do ${escapeHtml(label)}:</span>
                    <span id="group-sub-${gIdx}" class="text-sm font-extrabold text-[#1e2f53]">${formatBRL(gTotal)}</span>
                  </div>
                </div>
              </div>
            </div>
          `;
        }).join('');
      }

      updateGrandTotalSummary();
    }

    function updateGroupField(gIdx, field, value) {
      state.bid.groups[gIdx][field] = value;
      if (field === 'numero') {
        const badge = document.getElementById(`group-badge-${gIdx}`);
        if (badge) badge.textContent = `${state.bid.rotuloGrupo || 'Lote'} ${value || String(gIdx + 1).padStart(2, '0')}`;
      }
      saveToStorage();
      renderPreview();
    }

    function addGroup() {
      const nextNum = String(state.bid.groups.length + 1).padStart(2, '0');
      state.bid.groups.push(createEmptyGroup(nextNum, ''));
      saveToStorage();
      renderItemsEditor();
      renderPreview();
      showToast(`${state.bid.rotuloGrupo || 'Lote'} ${nextNum} adicionado!`);
    }

    function duplicateGroup(gIdx) {
      const orig = state.bid.groups[gIdx];
      const nextNum = String(state.bid.groups.length + 1).padStart(2, '0');
      const copy = {
        id: generateId(),
        numero: nextNum,
        titulo: orig.titulo,
        items: orig.items.map(it => ({ ...it, id: generateId() }))
      };
      state.bid.groups.splice(gIdx + 1, 0, copy);
      saveToStorage();
      renderItemsEditor();
      renderPreview();
      showToast(`${state.bid.rotuloGrupo || 'Lote'} duplicado!`);
    }

    function removeGroup(gIdx) {
      const label = state.bid.rotuloGrupo || 'Lote';
      if (state.bid.groups.length === 1) {
        if (!confirm(`Este é o único ${label.toLowerCase()}. Deseja limpar os itens dele?`)) return;
        state.bid.groups[0] = createEmptyGroup('01', '');
      } else {
        if (!confirm(`Deseja excluir o ${label} ${state.bid.groups[gIdx].numero} e todos os seus itens?`)) return;
        state.bid.groups.splice(gIdx, 1);
      }
      saveToStorage();
      renderItemsEditor();
      renderPreview();
    }

    function updateItemField(gIdx, iIdx, field, value) {
      const item = state.bid.groups[gIdx].items[iIdx];
      if (field === 'quant') {
        item.quant = parseFloat(value) || 0;
        const sub = item.quant * (Number(item.unitario) || 0);
        const subEl = document.getElementById(`item-sub-${gIdx}-${iIdx}`);
        if (subEl) subEl.textContent = formatBRL(sub);
        const gSubEl = document.getElementById(`group-sub-${gIdx}`);
        if (gSubEl) gSubEl.textContent = formatBRL(computeGroupTotal(state.bid.groups[gIdx]));
      } else {
        item[field] = value;
        if (field === 'numero') {
          const lbl = document.getElementById(`item-num-lbl-${gIdx}-${iIdx}`);
          if (lbl) lbl.textContent = value || '-';
        }
      }
      saveToStorage();
      updateGrandTotalSummary();
      renderPreview();
    }

    function updateItemCurrency(gIdx, iIdx, rawValue) {
      const parsed = parseBRL(rawValue);
      const item = state.bid.groups[gIdx].items[iIdx];
      item.unitario = parsed;
      if (state.bid.tipoProposta !== 'readequada') {
        item.unitarioInicial = parsed;
      }
      const sub = (Number(item.quant) || 0) * parsed;
      const subEl = document.getElementById(`item-sub-${gIdx}-${iIdx}`);
      if (subEl) subEl.textContent = formatBRL(sub);
      const gSubEl = document.getElementById(`group-sub-${gIdx}`);
      if (gSubEl) gSubEl.textContent = formatBRL(computeGroupTotal(state.bid.groups[gIdx]));
      saveToStorage();
      updateGrandTotalSummary();
      renderPreview();
    }

    function addItem(gIdx) {
      if (!state.bid.groups || state.bid.groups.length === 0) {
        state.bid.groups = [createEmptyGroup('01', '')];
        gIdx = 0;
      }
      const targetIdx = (state.bid.modoDisputa === 'item')
        ? state.bid.groups.length - 1
        : Math.min(gIdx, state.bid.groups.length - 1);

      const group = state.bid.groups[targetIdx];
      const existing = state.bid.modoDisputa === 'item' ? getAllItemsFlat().map(e => e.item) : group.items;
      const lastItem = existing.length > 0 ? existing[existing.length - 1] : null;
      const nextNum = lastItem
        ? String((parseInt(lastItem.numero, 10) || existing.length) + 1)
        : '1';

      group.items.push(createEmptyItem(nextNum));
      saveToStorage();
      renderItemsEditor();
      renderPreview();
    }

    function duplicateItem(gIdx, iIdx) {
      const copy = { ...state.bid.groups[gIdx].items[iIdx], id: generateId() };
      state.bid.groups[gIdx].items.splice(iIdx + 1, 0, copy);
      saveToStorage();
      renderItemsEditor();
      renderPreview();
      showToast('Item duplicado.');
    }

    function removeItem(gIdx, iIdx) {
      state.bid.groups[gIdx].items.splice(iIdx, 1);
      saveToStorage();
      renderItemsEditor();
      renderPreview();
    }

    function updateGrandTotalSummary() {
      const total = computeGrandTotal();
      document.getElementById('editor-grand-total').textContent = formatBRL(total);
      document.getElementById('editor-grand-total-words').textContent = `(${valorPorExtenso(total)})`;
    }

    // =========================================================================
    // VALIDAÇÃO VISUAL DE CAMPOS OBRIGATÓRIOS
    // =========================================================================
    function validateProposal() {
      const missing = [];
      const b = state.bid;
      const c = state.company;

      if (!b.orgao.trim()) missing.push('Órgão Licitante');
      if (!b.numero.trim()) missing.push('Nº do Pregão/Edital');
      if (!b.validade.trim()) missing.push('Validade da Proposta');
      if (!b.localEntrega.trim()) missing.push('Local de Entrega');
      if (!b.prazoEntrega.trim()) missing.push('Prazo de Entrega');
      if (!c.razao.trim()) missing.push('Razão Social');
      if (!c.cnpj.trim()) missing.push('CNPJ');
      if (!c.repNome.trim()) missing.push('Representante Legal');
      if (!c.repCpf.trim()) missing.push('CPF do Representante');

      const activeItems = getActiveItemsFlat().map(e => e.item);
      const isRead = b.tipoProposta === 'readequada';
      if (b.modoDisputa === 'lote' && (b.groups || []).some(g => !g.items || g.items.length === 0)) {
        missing.push(`${b.rotuloGrupo || 'Lote'} sem nenhum item cadastrado`);
      }
      if (activeItems.length === 0) {
        missing.push('Pelo menos 1 item na tabela');
      } else {
        const hasInvalidItem = isRead
          ? activeItems.some(it => !(Number(it.quant) > 0) || !(Number(it.unitario) > 0))
          : activeItems.some(it => !String(it.descricao || '').trim() || !(Number(it.quant) > 0) || !(Number(it.unitario) > 0));
        if (hasInvalidItem) {
          missing.push(isRead ? 'Item com quantidade ou unitário final zerado' : 'Item com descrição, quantidade ou valor zerado');
        }
      }

      const banner = document.getElementById('validation-banner');
      const text = document.getElementById('validation-text');
      if (missing.length > 0) {
        banner.classList.remove('hidden');
        text.textContent = ' ' + missing.join(' • ');
      } else {
        banner.classList.add('hidden');
      }

      document.querySelectorAll('#module-proposta .req-field').forEach(el => {
        if (!el.value.trim()) {
          el.classList.add('border-amber-400', 'bg-amber-50/40');
        } else {
          el.classList.remove('border-amber-400', 'bg-amber-50/40');
        }
      });

      return missing;
    }

    // =========================================================================
    // RENDERIZAÇÃO DO DOCUMENTO A4 (COMPATÍVEL COM PDF E WORD)
    // =========================================================================
    // Medidor preciso via Canvas para cortar a descrição exatamente em N linhas reais (funciona igual na Tela, PDF e Word)
    let _measureCtx = null;
    function getMeasureCtx(fontCss) {
      if (!_measureCtx) {
        const cv = document.createElement('canvas');
        _measureCtx = cv.getContext('2d');
      }
      _measureCtx.font = fontCss;
      return _measureCtx;
    }

    function truncateDescriptionToLines(rawText, maxLines, showUnid, density) {
      const cleaned = String(rawText || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
      if (!cleaned) return '';
      if (!maxLines || maxLines <= 0) return cleaned;

      // Calcula a largura útil real da coluna Descrição na folha A4 (96dpi), com margem de segurança
      const tablePx = density === 'ultra' ? 726 : (density === 'compact' ? 710 : 688);
      const descPct = showUnid ? 0.40 : 0.45;
      const cellPadPx = density === 'ultra' ? 10 : (density === 'compact' ? 12 : 15);
      const maxLineWidth = Math.max(180, (tablePx * descPct - cellPadPx) * 0.93);
      const fontSpec = density === 'ultra'
        ? '10.27px Arial, Helvetica, sans-serif'
        : (density === 'compact' ? '10.93px Arial, Helvetica, sans-serif' : '11.6px Arial, Helvetica, sans-serif');
      const ctx = getMeasureCtx(fontSpec);

      const paragraphs = cleaned.split('\n').map(p => p.replace(/\s+/g, ' ').trim()).filter(Boolean);
      const lines = [];
      let truncated = false;

      outerLoop:
      for (let pIdx = 0; pIdx < paragraphs.length; pIdx++) {
        const words = paragraphs[pIdx].split(' ').filter(Boolean);
        let current = '';

        for (let wIdx = 0; wIdx < words.length; wIdx++) {
          let word = words[wIdx];
          const candidate = current ? `${current} ${word}` : word;

          if (ctx.measureText(candidate).width <= maxLineWidth) {
            current = candidate;
          } else {
            if (current) {
              lines.push(current);
              if (lines.length >= maxLines) {
                truncated = true;
                break outerLoop;
              }
              current = '';
            }

            if (ctx.measureText(word).width > maxLineWidth) {
              let chunk = '';
              for (let ch of word) {
                if (ctx.measureText(chunk + ch).width <= maxLineWidth) {
                  chunk += ch;
                } else {
                  lines.push(chunk);
                  if (lines.length >= maxLines) {
                    truncated = true;
                    break outerLoop;
                  }
                  chunk = ch;
                }
              }
              current = chunk;
            } else {
              current = word;
            }
          }
        }

        if (current) {
          lines.push(current);
          if (lines.length >= maxLines) {
            if (pIdx < paragraphs.length - 1) truncated = true;
            break outerLoop;
          }
        }
      }

      if (truncated && lines.length > 0) {
        let last = lines[lines.length - 1].replace(/[\s,;:-]+$/, '');
        while (last.length > 1 && ctx.measureText(last + '...').width > maxLineWidth) {
          const lastSpace = last.lastIndexOf(' ');
          if (lastSpace > 4 && ctx.measureText(last.slice(0, lastSpace) + '...').width <= maxLineWidth) {
            last = last.slice(0, lastSpace).replace(/[\s,;:-]+$/, '');
            break;
          }
          last = last.slice(0, -1).replace(/[\s,;:-]+$/, '');
        }
        lines[lines.length - 1] = last + '...';
      }

      return lines.join('\n');
    }

    function getPriceColumnLabels() {
      const b = state.bid;
      const estilo = b.colPrecoEstilo || 'auto';
      if (estilo === 'edital') return { unit: 'Unitário do Edital', total: 'Total do Edital' };
      if (estilo === 'final') return { unit: 'Unitário Final', total: 'Total Final' };
      if (estilo === 'readequado') return { unit: 'Unitário Readequado', total: 'Total Readequado' };
      if (estilo === 'simples') return { unit: 'Valor Unitário', total: 'Valor Total' };
      // Automático conforme a fase da disputa
      return b.tipoProposta === 'readequada'
        ? { unit: 'Unitário Final', total: 'Total Final' }
        : { unit: 'Unitário do Edital', total: 'Total do Edital' };
    }

    function getProposalDocumentTitle() {
      const b = state.bid;
      if (b.tituloPreset && b.tituloPreset !== 'auto') return b.tituloPreset;
      return b.tipoProposta === 'readequada' ? 'PROPOSTA COMERCIAL READEQUADA' : 'PROPOSTA COMERCIAL';
    }

    function shouldShowDescriptionColumn(itemsList) {
      if (state.bid.tipoProposta !== 'readequada') return true;
      // Na proposta readequada, só mostra a coluna Descrição se algum item tiver descrição preenchida
      return (itemsList || []).some(it => it && it.descricao && it.descricao.trim() !== '');
    }

    function buildItemRowHTML(it, showUnid, showDesc = true) {
      const b = state.bid;
      const q = Number(it.quant) || 0;
      const u = Number(it.unitario) || 0;
      const tot = Math.round(q * u * 100) / 100;
      const maxLines = b.descMaxLines !== undefined ? Number(b.descMaxLines) : 2;
      const density = b.pdfDensity || 'compact';

      if (!showDesc) {
        return `
          <tr>
            <td style="text-align:center; font-weight:bold; width:8%;">${escapeHtml(it.numero || '-')}</td>
            <td style="text-align:center; width:12%;">${q.toLocaleString('pt-BR')}</td>
            ${showUnid ? `<td style="text-align:center; width:8%;">${escapeHtml(it.unid || 'UN')}</td>` : ''}
            <td style="text-align:center;">${escapeHtml(it.marca || '-')}</td>
            <td style="text-align:center;">${escapeHtml(it.modelo || '-')}</td>
            <td style="text-align:right; white-space:nowrap; width:16%;">${formatBRL(u)}</td>
            <td style="text-align:right; white-space:nowrap; font-weight:bold; width:17%;">${formatBRL(tot)}</td>
          </tr>
        `;
      }

      let descHtml = '<span style="color:#94a3b8; font-style:italic;">[Preencha a descrição do item na aba 2. Itens/Lotes]</span>';
      if (it.descricao && it.descricao.trim()) {
        const displayDesc = maxLines > 0
          ? truncateDescriptionToLines(it.descricao, maxLines, showUnid, density)
          : it.descricao.trim();
        descHtml = `<span class="doc-desc-clamp">${nl2br(displayDesc)}</span>`;
      }

      const descAlign = maxLines > 0 ? 'left' : 'justify';

      return `
        <tr>
          <td style="text-align:center; font-weight:bold; width:5%;">${escapeHtml(it.numero || '-')}</td>
          <td style="text-align:center; width:6%;">${q.toLocaleString('pt-BR')}</td>
          ${showUnid ? `<td style="text-align:center; width:5%;">${escapeHtml(it.unid || 'UN')}</td>` : ''}
          <td style="text-align:${descAlign};">${descHtml}</td>
          <td style="text-align:center; width:10%;">${escapeHtml(it.marca || '-')}</td>
          <td style="text-align:center; width:10%;">${escapeHtml(it.modelo || '-')}</td>
          <td style="text-align:right; white-space:nowrap; width:12%;">${formatBRL(u)}</td>
          <td style="text-align:right; white-space:nowrap; font-weight:bold; width:12%;">${formatBRL(tot)}</td>
        </tr>
      `;
    }

    function buildItemsSectionHTML() {
      const b = state.bid;
      const allActiveItems = getActiveItemsFlat().map(e => e.item);
      const showDesc = shouldShowDescriptionColumn(allActiveItems);
      const colSpan = (showDesc ? 7 : 6) + (b.showUnid ? 1 : 0);
      const priceLabels = getPriceColumnLabels();

      const colHead = `
        <tr class="doc-items-head">
          <th>Item</th>
          <th>${showDesc ? 'Quant.' : 'Quantidade'}</th>
          ${b.showUnid ? '<th>Unid.</th>' : ''}
          ${showDesc ? '<th>Descrição (do Edital)</th>' : ''}
          <th>Marca</th>
          <th>Modelo</th>
          <th>${escapeHtml(priceLabels.unit)}</th>
          <th>${escapeHtml(priceLabels.total)}</th>
        </tr>
      `;

      if (b.modoDisputa !== 'lote') {
        const rows = allActiveItems.length > 0
          ? allActiveItems.map(it => buildItemRowHTML(it, b.showUnid, showDesc)).join('')
          : `<tr><td colspan="${colSpan}" style="text-align:center; color:#64748b; padding:12px;">Nenhum item cadastrado.</td></tr>`;

        return `
          <table class="doc-items-table">
            <thead class="doc-items-head">
              ${colHead}
            </thead>
            <tbody>
              ${rows}
            </tbody>
          </table>
        `;
      } else {
        const label = (b.rotuloGrupo || 'Lote').toUpperCase();
        if (!b.groups || b.groups.length === 0) {
          return `<table class="doc-items-table"><tbody><tr><td style="text-align:center; color:#64748b; padding:12px;">Nenhum ${escapeHtml(label.toLowerCase())} cadastrado.</td></tr></tbody></table>`;
        }

        return b.groups.map((group, gIdx) => {
          const gNum = escapeHtml((group.numero || String(gIdx + 1).padStart(2, '0')).trim());
          const gTitulo = group.titulo && group.titulo.trim() ? ` — ${escapeHtml(group.titulo.trim())}` : '';
          const gTotal = computeGroupTotal(group);
          const gExtenso = b.mostrarExtensoGrupo
            ? `<div style="font-weight:normal; font-style:italic; font-size:8pt; color:#334155; margin-top:2px;">(${escapeHtml(valorPorExtenso(gTotal))})</div>`
            : '';

          const rows = (group.items && group.items.length > 0)
            ? group.items.map(it => buildItemRowHTML(it, b.showUnid, showDesc)).join('')
            : `<tr><td colspan="${colSpan}" style="text-align:center; color:#64748b; padding:10px;">Nenhum item cadastrado neste ${escapeHtml(label.toLowerCase())}.</td></tr>`;

          return `
            <table class="doc-items-table" data-lote-table="1">
              <thead>
                <tr>
                  <td colspan="${colSpan}" class="doc-group-banner">${escapeHtml(label)} ${gNum}${gTitulo}</td>
                </tr>
                ${colHead}
              </thead>
              <tbody>
                ${rows}
                <tr class="doc-group-subtotal">
                  <td colspan="${colSpan - 1}" style="text-align:right;">
                    SUBTOTAL DO ${escapeHtml(label)} ${gNum}:
                    ${gExtenso}
                  </td>
                  <td style="text-align:right; white-space:nowrap;">${formatBRL(gTotal)}</td>
                </tr>
              </tbody>
            </table>
          `;
        }).join('');
      }
    }

    function buildDocumentHTML() {
      const b = state.bid;
      const c = state.company;
      const t = getActiveTheme();
      const isRead = b.tipoProposta === 'readequada';
      const grandTotal = computeGrandTotal();
      const grandTotalWords = valorPorExtenso(grandTotal);

      const telefonesEmpresa = [c.tel1, c.tel2].filter(Boolean).join(' / ');
      const enderecoCompleto = [c.endereco, c.cep ? `CEP: ${c.cep}` : ''].filter(Boolean).join(' — ');

      const numeroFormatado = formatNumeroEdital(b.numero);
      const modalidadeNome = b.modalidade || 'Pregão Eletrônico';
      const modalidadeLabel = `${modalidadeNome} ${numeroFormatado}`;
      const editalRefFull = `${(b.refEdital || 'Edital Seleção Pública').trim()} ${numeroFormatado}`;
      const docTitle = getProposalDocumentTitle();

      const introComplementos = [];
      if (b.processo && b.processo.trim()) introComplementos.push(`Processo Administrativo nº ${escapeHtml(b.processo.trim())}`);
      if (b.sessao && b.sessao.trim()) introComplementos.push(`Sessão Pública: ${escapeHtml(b.sessao.trim())}`);

      const introQualificador = isRead
        ? 'readequada ao(s) lance(s) final(is) vencedor(es), '
        : '';

      const introObjeto = (b.objeto && b.objeto.trim())
        ? `${introQualificador}para <strong>${escapeHtml(b.objeto.trim())}</strong>, referente ao <strong>${escapeHtml(modalidadeLabel)}</strong>`
        : `${introQualificador}para a aquisição dos itens descritos no Termo de Referência do <strong>${escapeHtml(modalidadeLabel)}</strong>`;

      let headerHtml = '';
      const logoH = c.logoHeight || 48;
      if (c.logo && (c.logoLayout || 'side') === 'side') {
        headerHtml = `
          <table class="doc-header-table doc-keep">
            <tr>
              <td style="width:48%; text-align:left; vertical-align:middle;">
                <img src="${c.logo}" style="height:${logoH}px; max-width:240px; width:auto; display:block;" alt="Logomarca" />
              </td>
              <td style="width:52%; text-align:right; vertical-align:middle;">
                <div style="font-size:12.5pt; font-weight:bold; letter-spacing:0.6px; color:${t.primary}; line-height:1.15;">${escapeHtml(docTitle)}</div>
                <div style="font-size:8.2pt; font-weight:bold; color:${t.accent}; margin-top:2px;">${escapeHtml(modalidadeLabel.toUpperCase())}</div>
                <div style="font-size:7.6pt; color:#475569; margin-top:2px;">CNPJ: ${escapeHtml(c.cnpj || '-')}</div>
              </td>
            </tr>
          </table>
        `;
      } else {
        const centeredLogo = c.logo
          ? `<div style="text-align:center; margin-bottom:7px;">
               <img src="${c.logo}" style="height:${logoH}px; max-width:260px; width:auto; display:inline-block;" alt="Logomarca" />
             </div>`
          : '';
        headerHtml = `
          <div class="doc-keep">
            ${centeredLogo}
            <div style="text-align:center; border-bottom:2.5px solid ${t.primary}; padding-bottom:6px; margin-bottom:10px;">
              <div style="font-size:13.5pt; font-weight:bold; letter-spacing:0.9px; color:${t.primary};">${escapeHtml(docTitle)}</div>
              <div style="font-size:8.3pt; font-weight:bold; color:${t.accent}; margin-top:2px;">${escapeHtml(modalidadeLabel.toUpperCase())}</div>
            </div>
          </div>
        `;
      }

      const alineasLines = (b.declAlineas || DEFAULT_DECL_ALINEAS)
        .split('\n')
        .map(line => line.trim())
        .filter(Boolean)
        .map(line => line.replace(/\{\{EDITAL\}\}/g, editalRefFull));

      if (b.incluirLei14133 && alineasLines.length > 0) {
        const lastIdx = alineasLines.length - 1;
        alineasLines[lastIdx] = alineasLines[lastIdx].replace(/\.$/, ';');
        alineasLines.push(CLAUSULA_LEI_14133);
      }

      const alineasHtml = alineasLines
        .map(line => `<p style="margin:0 0 4px 0;">${escapeHtml(line)}</p>`)
        .join('');

      const sigImageHtml = c.signature
        ? `<div style="margin-bottom:4px; text-align:center;">
             <img src="${c.signature}" style="height:${c.sigHeight || 68}px; max-width:260px; width:auto; display:inline-block; vertical-align:bottom;" alt="Assinatura" />
           </div>`
        : `<div style="height:34px;"></div>`;

      const tratamento = escapeHtml(b.tratamento || 'Ao');
      const orgaoHtml = (b.orgao && b.orgao.trim())
        ? escapeHtml(b.orgao.trim())
        : '<span style="color:#94a3b8; font-style:italic;">[INFORME O ÓRGÃO LICITANTE]</span>';

      const declBlockHtml = `
        <div class="doc-decl doc-keep">
          <p style="margin:0 0 5px 0;"><strong>Ao apresentar a proposta de preços, assumo de forma total e irretratável o seguinte:</strong></p>
          ${alineasHtml}
        </div>
      `;

      const sigBlockHtml = `
        <div class="doc-signature doc-keep">
          <p style="text-align:right; margin:0 0 16px 0;">
            ${escapeHtml(c.cidade || 'Balneário Camboriú')}, ${formatDateExtenso(b.data)}.
          </p>
          ${sigImageHtml}
          <div style="border-top:1px solid ${t.primary}; width:74%; margin:0 auto 6px auto;"></div>
          <div style="font-weight:bold; font-size:9.5pt; color:${t.primary};">${escapeHtml(c.razao || '')}</div>
          <div style="font-size:8.8pt;">CNPJ: ${escapeHtml(c.cnpj || '')}</div>
          <div style="font-size:9pt; margin-top:3px; font-weight:bold;">${escapeHtml(c.repNome || '')}</div>
          <div style="font-size:8.6pt;">CPF: ${escapeHtml(c.repCpf || '')} — RG: ${escapeHtml(c.repRg || '')}</div>
        </div>
      `;

      const quoteBlockHtml = `
        <div class="doc-quote doc-keep">
          "${escapeHtml(b.declPrecos || DEFAULT_DECL_PRECOS)}"
        </div>
      `;

      // Sempre agrupa Declarações Irretratáveis + Local/Data + Assinatura no mesmo bloco indivisível
      const declAndSigHtml = `<div class="doc-keep doc-decl-sig-pair">${declBlockHtml}${sigBlockHtml}</div>`;
      const closingHtml = b.pdfKeepEndTogether !== false
        ? `<div class="doc-keep doc-closing-group">${quoteBlockHtml}${declAndSigHtml}</div>`
        : `${quoteBlockHtml}${declAndSigHtml}`;

      return `
        <!-- CABEÇALHO TIMBRADO -->
        ${headerHtml}

        <!-- ENDEREÇAMENTO E INTRODUÇÃO -->
        <div class="doc-keep" style="margin-bottom:10px; text-align:justify;">
          <p style="margin:0 0 3px 0;"><strong>Prezados Senhores,</strong></p>
          <p style="margin:0 0 5px 0;"><strong>${tratamento} ${orgaoHtml}</strong></p>
          ${introComplementos.length > 0 ? `<p style="margin:0 0 5px 0; font-size:8.5pt; color:#334155;">${introComplementos.join(' &nbsp;|&nbsp; ')}</p>` : ''}
          <p style="margin:0;">
            Apresentamos a V. Sa. nossa proposta de preços ${introObjeto}, conforme a seguir:
          </p>
        </div>

        <!-- DADOS DA EMPRESA -->
        <table class="doc-data-table doc-keep">
          <tr>
            <td colspan="2" class="doc-sec-title">DADOS DA EMPRESA</td>
          </tr>
          <tr>
            <td style="width:45%;"><strong>CNPJ:</strong> ${escapeHtml(c.cnpj || '-')}</td>
            <td style="width:55%;"><strong>Razão Social:</strong> ${escapeHtml(c.razao || '-')}</td>
          </tr>
          <tr>
            <td><strong>Inscrição Estadual:</strong> ${escapeHtml(c.ie || 'Isento')}</td>
            <td><strong>Inscrição Municipal:</strong> ${escapeHtml(c.im || '-')}</td>
          </tr>
          ${enderecoCompleto ? `
          <tr>
            <td colspan="2"><strong>Endereço:</strong> ${escapeHtml(enderecoCompleto)}</td>
          </tr>` : ''}
          <tr>
            <td><strong>Telefone:</strong> ${escapeHtml(telefonesEmpresa || '-')}</td>
            <td><strong>E-mail:</strong> ${escapeHtml(c.email || '-')}</td>
          </tr>
        </table>

        <!-- REPRESENTANTE LEGAL -->
        <table class="doc-data-table doc-keep">
          <tr>
            <td colspan="2" class="doc-sec-title">REPRESENTANTE LEGAL</td>
          </tr>
          <tr>
            <td style="width:55%;"><strong>Nome:</strong> ${escapeHtml(c.repNome || '-')}</td>
            <td style="width:45%;"><strong>Cargo/Função:</strong> ${escapeHtml(c.repCargo || '-')}</td>
          </tr>
          <tr>
            <td><strong>RG:</strong> ${escapeHtml(c.repRg || '-')}</td>
            <td><strong>CPF:</strong> ${escapeHtml(c.repCpf || '-')}</td>
          </tr>
          <tr>
            <td><strong>Telefone:</strong> ${escapeHtml(c.repTel || '-')}</td>
            <td><strong>E-mail:</strong> ${escapeHtml(c.repEmail || '-')}</td>
          </tr>
        </table>

        <!-- DADOS BANCÁRIOS -->
        <table class="doc-data-table doc-keep">
          <tr>
            <td colspan="3" class="doc-sec-title">DADOS BANCÁRIOS</td>
          </tr>
          <tr>
            <td style="width:46%;"><strong>Banco:</strong> ${escapeHtml(c.banco || '-')}</td>
            <td style="width:27%;"><strong>Agência:</strong> ${escapeHtml(c.agencia || '-')}</td>
            <td style="width:27%;"><strong>Conta:</strong> ${escapeHtml(c.conta || '-')}</td>
          </tr>
          ${c.pix ? `
          <tr>
            <td colspan="3"><strong>Chave PIX:</strong> ${escapeHtml(c.pix)}</td>
          </tr>` : ''}
        </table>

        <!-- TABELA DE ITENS / GRUPOS / LOTES -->
        ${buildItemsSectionHTML()}

        <!-- VALOR TOTAL GLOBAL -->
        <div class="doc-total-box doc-keep">
          ${isRead ? 'VALOR TOTAL GLOBAL READEQUADO' : 'VALOR TOTAL GLOBAL'}: ${formatBRL(grandTotal)} (${escapeHtml(grandTotalWords)})
        </div>

        <!-- CONDIÇÕES COMERCIAIS -->
        <table class="doc-data-table doc-keep" style="margin-bottom:8px;">
          <tr>
            <td style="width:50%;"><strong>Prazo de validade da proposta:</strong> ${escapeHtml(computeFormattedValidade(b.validade, b.data || getTodayISO()))}</td>
            <td style="width:50%;"><strong>Local de entrega:</strong> ${escapeHtml(b.localEntrega || 'Conforme Edital')}</td>
          </tr>
          <tr>
            <td><strong>Prazo de entrega:</strong> ${escapeHtml(b.prazoEntrega || 'Conforme Edital')}</td>
            <td><strong>Garantia dos produtos:</strong> ${escapeHtml(b.garantia || 'Conforme Edital')}</td>
          </tr>
        </table>

        <!-- DECLARAÇÃO DE PREÇOS + DECLARAÇÕES IRRETRATÁVEIS + LOCAL, DATA E ASSINATURA (SEMPRE JUNTOS) -->
        ${closingHtml}
      `;
    }

    function applyDensityClass(el, density) {
      el.classList.remove('compact-doc', 'ultra-doc');
      if (density === 'ultra') el.classList.add('ultra-doc');
      else if (density === 'compact') el.classList.add('compact-doc');
    }

    function updatePreviewPageGuides() {
      const docEl = document.getElementById('proposal-document');
      if (!docEl) return;
      docEl.querySelectorAll('.a4-page-guide').forEach(g => g.remove());

      // Altura de 1 folha A4 em pixels CSS (297mm * 96 / 25.4 ≈ 1122.5px)
      const a4HeightPx = 1122.5;
      const contentH = docEl.scrollHeight;
      const estPages = Math.max(1, Math.ceil((contentH - 6) / a4HeightPx));

      const pageBadge = document.getElementById('preview-page-count');
      if (pageBadge) {
        const pageMode = state.bid.pdfPageMode || 'smart';
        if (pageMode === 'fit1') {
          pageBadge.textContent = '1 pág. A4 (Ajuste 1 Pág.)';
        } else {
          pageBadge.textContent = `~${estPages} ${estPages === 1 ? 'pág.' : 'págs.'} A4`;
        }
      }

      if (state.bid.pdfShowGuides !== false && estPages > 1) {
        for (let p = 1; p < estPages; p++) {
          const guide = document.createElement('div');
          guide.className = 'a4-page-guide';
          guide.style.top = `${Math.round(p * a4HeightPx)}px`;
          guide.innerHTML = `<span>Fim da Pág. ${p} (o PDF organiza automaticamente sem cortar linhas)</span>`;
          docEl.appendChild(guide);
        }
      }
    }

    function _renderPreviewImmediate() {
      const docEl = window.__getEl('proposal-document');
      if (!docEl) return;
      const density = state.bid.pdfDensity || 'compact';
      applyDensityClass(docEl, density);
      applySheetThemeClass(docEl);
      docEl.innerHTML = buildDocumentHTML();

      const badge = window.__getEl('preview-compact-badge');
      if (badge) {
        const lines = state.bid.descMaxLines !== undefined ? Number(state.bid.descMaxLines) : 2;
        const densLabel = density === 'ultra' ? 'Ultra' : (density === 'compact' ? 'Compacto' : 'Normal');
        const phaseLabel = state.bid.tipoProposta === 'readequada' ? 'Readequada' : 'Inicial';
        badge.textContent = `${phaseLabel} • ${lines > 0 ? lines + 'L' : 'Completa'} • ${densLabel}`;
      }

      requestAnimationFrame(updatePreviewPageGuides);
      validateProposal();
    }

    let _previewRafPending = false;
    function renderPreview() {
      if (_previewRafPending) return;
      _previewRafPending = true;
      requestAnimationFrame(() => {
        _previewRafPending = false;
        _renderPreviewImmediate();
      });
    }

    function togglePdfSettingsDrawer(forceOpen) {
      const drawer = document.getElementById('pdf-settings-drawer');
      if (!drawer) return;
      if (window.innerWidth < 1024) {
        setMobileView('preview');
      }
      if (forceOpen === true) drawer.classList.remove('hidden');
      else if (forceOpen === false) drawer.classList.add('hidden');
      else drawer.classList.toggle('hidden');
    }

    // =========================================================================
    // EXPORTAÇÃO: PDF (html2pdf.js), WORD (.DOC) E IMPRESSÃO NATIVA
    // =========================================================================
    function buildFilename(ext) {
      const t = getActiveTheme();
      const orgao = (state.bid.orgao || 'Orgao').replace(/[^a-zA-Z0-9À-ÿ]+/g, '_').slice(0, 28);
      const num = (state.bid.numero || 'Proposta').replace(/[^a-zA-Z0-9]+/g, '-');
      const tag = state.bid.tipoProposta === 'readequada' ? '_Readequada' : '';
      return `Proposta${tag}_${t.fileSlug}_${orgao}_${num}.${ext}`;
    }

    // =========================================================================
    // MOTOR DE PAGINAÇÃO REAL PÁGINA A PÁGINA PARA PDF
    // Constrói cada folha A4 individualmente no DOM real (medindo altura exata
    // com imagens decodificadas e colapso de margem real) e renderiza folha por
    // folha no jsPDF — ZERO cortes de linha e assinatura SEMPRE junto das declarações!
    // =========================================================================
    async function waitForImagesInContainer(container) {
      const imgs = Array.from(container.querySelectorAll('img'));
      if (imgs.length === 0) return;
      await Promise.all(imgs.map(img => {
        if (img.complete && img.naturalHeight > 0) return Promise.resolve();
        if (typeof img.decode === 'function') {
          return img.decode().catch(() => {});
        }
        return new Promise(resolve => {
          img.onload = resolve;
          img.onerror = resolve;
          setTimeout(resolve, 1500);
        });
      }));
    }

    function createPdfPageShell(density, widthPx) {
      const page = document.createElement('div');
      page.className = 'proposal-sheet';
      applyDensityClass(page, density);
      applySheetThemeClass(page);
      page.style.width = `${widthPx}px`;
      page.style.minHeight = 'auto';
      page.style.padding = '0';
      page.style.margin = '0';
      page.style.boxShadow = 'none';
      page.style.transform = 'none';
      page.style.background = '#ffffff';
      page.style.overflow = 'hidden';
      return page;
    }

    function measurePageHeight(pageEl) {
      return Math.ceil(pageEl.getBoundingClientRect().height);
    }

    function applySqueezeScaleToPage(pageEl, factor) {
      pageEl.style.fontSize = `${(8.3 * factor).toFixed(2)}pt`;
      pageEl.style.lineHeight = '1.18';
      pageEl.querySelectorAll('table.doc-data-table, table.doc-items-table').forEach(t => {
        t.style.fontSize = `${(7.7 * factor).toFixed(2)}pt`;
        t.style.marginBottom = '3px';
      });
      pageEl.querySelectorAll('table.doc-data-table td, table.doc-data-table th, table.doc-items-table td, table.doc-items-table th').forEach(cell => {
        cell.style.padding = '2px 4px';
        cell.style.lineHeight = '1.16';
      });
      pageEl.querySelectorAll('.doc-quote, .doc-decl').forEach(el => {
        el.style.fontSize = `${(7.8 * factor).toFixed(2)}pt`;
        el.style.margin = '3px 0';
        el.style.lineHeight = '1.18';
      });
      pageEl.querySelectorAll('.doc-signature').forEach(el => {
        el.style.marginTop = '6px';
      });
    }

    async function buildRealPdfPages(density, marginsMm) {
      const b = state.bid;
      const marginTop = marginsMm[0];
      const marginRight = marginsMm[1];
      const marginBottom = marginsMm[2];
      const marginLeft = marginsMm[3];

      const printableWidthMm = 210 - marginLeft - marginRight;
      const printableHeightMm = 297 - marginTop - marginBottom;

      // Host oculto com largura real em mm para obter a proporção exata de pixels do navegador atual
      const host = document.createElement('div');
      host.style.position = 'fixed';
      host.style.left = '-15000px';
      host.style.top = '0';
      host.style.width = `${printableWidthMm}mm`;
      host.style.background = '#ffffff';
      host.style.zIndex = '-9999';
      document.body.appendChild(host);

      const pageWidthPx = Math.round(host.getBoundingClientRect().width) || Math.round(printableWidthMm * (96 / 25.4));
      // Folga de segurança de 14px para garantir que nenhuma página estoure por arredondamento de fonte/subpixel
      const pageHeightPx = Math.floor(pageWidthPx * (printableHeightMm / printableWidthMm)) - 14;

      // Renderiza fonte completa para decodificar todas as imagens (logo e assinatura) antes de paginar
      const source = createPdfPageShell(density, pageWidthPx);
      source.innerHTML = buildDocumentHTML();
      host.appendChild(source);
      await waitForImagesInContainer(source);

      const pageMode = b.pdfPageMode || 'smart';
      const initialHeight = measurePageHeight(source);

      // 1) Se já cabe inteiro em 1 única folha A4, retorna direto sem quebrar nada!
      if (initialHeight <= pageHeightPx) {
        return { host, pages: [source], pageWidthPx, pageHeightPx, fittedOnePage: true };
      }

      // 2) Modo "Forçar 1 Página" ou "Evitar Página Quase Vazia" (até +30% de 1 página)
      const shouldSqueezeToOne = (pageMode === 'fit1')
        || (pageMode === 'auto_squeeze' && initialHeight <= pageHeightPx * 1.30);

      if (shouldSqueezeToOne) {
        if (density !== 'ultra') {
          applyDensityClass(source, 'ultra');
          source.style.padding = '0';
        }
        const steps = [0.95, 0.90, 0.85, 0.80, 0.75, 0.70, 0.65];
        for (const factor of steps) {
          if (measurePageHeight(source) <= pageHeightPx) break;
          applySqueezeScaleToPage(source, factor);
        }
        if (measurePageHeight(source) <= pageHeightPx || pageMode === 'fit1') {
          return { host, pages: [source], pageWidthPx, pageHeightPx, fittedOnePage: true };
        }
        // Se auto_squeeze não coube em 1 página, restaura fonte limpa para paginação multi-página
        host.removeChild(source);
        const freshSource = createPdfPageShell(density, pageWidthPx);
        freshSource.innerHTML = buildDocumentHTML();
        host.appendChild(freshSource);
        await waitForImagesInContainer(freshSource);
        return await paginateSourceIntoPages(host, freshSource, density, pageWidthPx, pageHeightPx);
      }

      // 3) Paginação Real Multi-Página (cada página é um container DOM independente <= pageHeightPx)
      return await paginateSourceIntoPages(host, source, density, pageWidthPx, pageHeightPx);
    }

    async function paginateSourceIntoPages(host, source, density, pageWidthPx, pageHeightPx) {
      const b = state.bid;
      const repeatHead = b.pdfRepeatHead !== false;
      const breakBetweenLots = !!b.pdfBreakBetweenLots;

      const blocks = Array.from(source.children);
      host.removeChild(source);

      const pages = [];
      let currentPage = null;

      function startNewPage() {
        const p = createPdfPageShell(density, pageWidthPx);
        host.appendChild(p);
        pages.push(p);
        currentPage = p;
        return p;
      }

      startNewPage();
      let itemsTableSeen = 0;

      function placeIndivisibleBlock(el) {
        currentPage.appendChild(el);
        if (currentPage.children.length > 1 && measurePageHeight(currentPage) > pageHeightPx) {
          currentPage.removeChild(el);
          startNewPage();
          currentPage.appendChild(el);
        }
      }

      for (const block of blocks) {
        // Caso especial: Bloco de fechamento (Declaração de Preços + Declarações Irretratáveis + Assinatura)
        // Mantém TUDO junto na mesma página; se não couber no resto da página atual, pula inteiro para a próxima!
        if (block.classList.contains('doc-closing-group')) {
          currentPage.appendChild(block);
          if (measurePageHeight(currentPage) <= pageHeightPx) {
            continue;
          }
          if (currentPage.children.length > 1) {
            currentPage.removeChild(block);
            startNewPage();
            currentPage.appendChild(block);
          }
          // Somente se o bloco inteiro sozinho for maior que 1 folha A4 inteira (texto customizado gigante),
          // separa a citação de preços mas mantém Declarações + Assinatura sempre juntas!
          if (measurePageHeight(currentPage) > pageHeightPx) {
            const innerKids = Array.from(block.children);
            currentPage.removeChild(block);
            if (currentPage.children.length === 0 && pages.length > 1) {
              // continua usando esta página vazia
            }
            for (const kid of innerKids) {
              placeIndivisibleBlock(kid);
            }
          }
          continue;
        }

        // Caso especial: Tabela de Itens / Lotes (quebra de forma inteligente entre linhas sem cortar texto)
        if (block.classList.contains('doc-items-table')) {
          const isSecondOrMoreLot = itemsTableSeen > 0 && block.getAttribute('data-lote-table') === '1';
          itemsTableSeen++;

          if (breakBetweenLots && isSecondOrMoreLot && currentPage.children.length > 0) {
            startNewPage();
          }

          // Tenta encaixar a tabela inteira primeiro
          currentPage.appendChild(block);
          if (measurePageHeight(currentPage) <= pageHeightPx) {
            continue;
          }
          currentPage.removeChild(block);

          const thead = block.querySelector('thead');
          const tbody = block.querySelector('tbody');
          const rows = tbody ? Array.from(tbody.querySelectorAll('tr')) : [];

          if (rows.length === 0) {
            placeIndivisibleBlock(block);
            continue;
          }

          const tableClass = block.className;

          function createSliceTable(isContinuation) {
            const tbl = document.createElement('table');
            tbl.className = tableClass;
            if (thead && (!isContinuation || repeatHead)) {
              const clonedHead = thead.cloneNode(true);
              if (isContinuation) {
                const banner = clonedHead.querySelector('.doc-group-banner');
                if (banner && !banner.textContent.includes('(continuação)')) {
                  banner.textContent = banner.textContent + ' (continuação)';
                }
              }
              tbl.appendChild(clonedHead);
            }
            const tb = document.createElement('tbody');
            tbl.appendChild(tb);
            return { tbl, tb };
          }

          let sliceCount = 0;
          let activeSlice = createSliceTable(false);
          currentPage.appendChild(activeSlice.tbl);

          for (let rIdx = 0; rIdx < rows.length; rIdx++) {
            const row = rows[rIdx];
            const isLastSubtotal = (rIdx === rows.length - 1) && row.classList.contains('doc-group-subtotal');
            activeSlice.tb.appendChild(row);

            if (measurePageHeight(currentPage) > pageHeightPx) {
              activeSlice.tb.removeChild(row);

              // Se nem o cabeçalho + 1ª linha couberam no resto da página atual, move a tabela toda para nova página
              if (activeSlice.tb.children.length === 0) {
                if (currentPage.children.length > 1) {
                  currentPage.removeChild(activeSlice.tbl);
                  startNewPage();
                  activeSlice = createSliceTable(sliceCount > 0);
                  currentPage.appendChild(activeSlice.tbl);
                  activeSlice.tb.appendChild(row);
                } else {
                  // Página vazia e uma única linha gigante (> 1 folha): mantém para não entrar em loop
                  activeSlice.tb.appendChild(row);
                }
              } else {
                // Evita deixar a linha de Subtotal órfã sozinha no topo da próxima página (puxa o último item junto!)
                let pulledRow = null;
                if (isLastSubtotal && activeSlice.tb.children.length >= 2) {
                  pulledRow = activeSlice.tb.lastElementChild;
                  activeSlice.tb.removeChild(pulledRow);
                }

                sliceCount++;
                startNewPage();
                activeSlice = createSliceTable(true);
                currentPage.appendChild(activeSlice.tbl);
                if (pulledRow) activeSlice.tb.appendChild(pulledRow);
                activeSlice.tb.appendChild(row);
              }
            }
          }
          continue;
        }

        // Demais blocos (Cabeçalho, Intro, Dados Empresa, Representante, Bancários, Total, Condições)
        placeIndivisibleBlock(block);
      }

      // Remove eventual página vazia
      const finalPages = pages.filter(p => p.children.length > 0);
      return { host, pages: finalPages, pageWidthPx, pageHeightPx, fittedOnePage: finalPages.length === 1 };
    }

    async function exportPDF() {
      // Sincroniza data atual do sistema antes de validar e exportar o PDF
      const inputDataEl = document.getElementById('bid-data');
      if (inputDataEl && !inputDataEl.value) {
        ensureCurrentSystemDate(true);
      } else if (inputDataEl) {
        state.bid.data = inputDataEl.value;
      }
      _renderPreviewImmediate();

      const missing = validateProposal();
      if (missing.length > 0) {
        const cont = confirm(`Existem campos obrigatórios pendentes:\n- ${missing.join('\n- ')}\n\nDeseja gerar o PDF mesmo assim?`);
        if (!cont) return;
      }

      if (typeof html2pdf === 'undefined') {
        showToast('Biblioteca PDF indisponível offline. Abrindo impressão nativa (Salvar como PDF)...');
        window.print();
        return;
      }

      const btn = document.getElementById('btn-pdf');
      const originalText = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span>Organizando PDF...</span>';

      const density = state.bid.pdfDensity || 'compact';
      const marginsMm = density === 'ultra'
        ? [7, 8, 7, 8]
        : (density === 'compact' ? [9, 10, 9, 10] : [12, 13, 12, 13]);

      const marginTop = marginsMm[0];
      const marginRight = marginsMm[1];
      const marginBottom = marginsMm[2];
      const marginLeft = marginsMm[3];
      const printableWidthMm = 210 - marginLeft - marginRight;
      const printableHeightMm = 297 - marginTop - marginBottom;

      let buildResult = null;
      try {
        buildResult = await buildRealPdfPages(density, marginsMm);
        const { host, pages, pageWidthPx, fittedOnePage } = buildResult;

        if (!pages || pages.length === 0) {
          throw new Error('Nenhuma página gerada.');
        }

        // Cria instância limpa do jsPDF (compatível com qualquer build do html2pdf.bundle)
        let pdf = null;
        if (window.jspdf && typeof window.jspdf.jsPDF === 'function') {
          pdf = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
        } else if (typeof window.jsPDF === 'function') {
          pdf = new window.jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
        } else {
          const seed = document.createElement('div');
          seed.style.cssText = 'width:8px;height:8px;background:#ffffff;';
          host.appendChild(seed);
          pdf = await html2pdf().set({
            margin: 0,
            html2canvas: { scale: 1, logging: false, backgroundColor: '#ffffff' },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
          }).from(seed).toPdf().get('pdf');
        }

        const canvasOpt = {
          margin: marginsMm,
          html2canvas: {
            scale: 2,
            useCORS: true,
            logging: false,
            letterRendering: true,
            backgroundColor: '#ffffff',
            width: pageWidthPx,
            scrollX: 0,
            scrollY: 0
          },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
          pagebreak: { mode: [] }
        };

        // Renderiza cada folha A4 individualmente — impossível cortar linhas ou isolar assinatura!
        for (let i = 0; i < pages.length; i++) {
          btn.innerHTML = `<span>Gerando pág. ${i + 1}/${pages.length}...</span>`;
          if (i > 0) {
            pdf.addPage('a4', 'portrait');
          }

          const canvas = await html2pdf()
            .set(canvasOpt)
            .from(pages[i])
            .toCanvas()
            .get('canvas');

          const imgData = canvas.toDataURL('image/jpeg', 0.98);
          let drawW = printableWidthMm;
          let drawH = (canvas.height * drawW) / canvas.width;
          let drawX = marginLeft;

          // Proteção extra: se ultrapassar por arredondamento mínimo, escala proporcionalmente dentro da página
          if (drawH > printableHeightMm) {
            const ratio = printableHeightMm / drawH;
            drawH = printableHeightMm;
            drawW = drawW * ratio;
            drawX = marginLeft + (printableWidthMm - drawW) / 2;
          }

          pdf.addImage(imgData, 'JPEG', drawX, marginTop, drawW, drawH);
        }

        pdf.save(buildFilename('pdf'));
        const tPdf = getActiveTheme();
        showToast(fittedOnePage
          ? `PDF da ${tPdf.shortName} organizado em 1 página baixado!`
          : `PDF da ${tPdf.shortName} organizado em ${pages.length} páginas baixado!`);
      } catch (err) {
        console.error(err);
        showToast('Erro ao gerar PDF. Use o botão Imprimir para salvar como PDF.');
      } finally {
        if (buildResult && buildResult.host && buildResult.host.parentNode) {
          buildResult.host.parentNode.removeChild(buildResult.host);
        }
        btn.disabled = false;
        btn.innerHTML = originalText;
      }
    }

    function exportWord() {
      const inputDataEl = document.getElementById('bid-data');
      if (inputDataEl && !inputDataEl.value) ensureCurrentSystemDate(true);
      else if (inputDataEl) state.bid.data = inputDataEl.value;
      _renderPreviewImmediate();

      const missing = validateProposal();
      if (missing.length > 0) {
        const cont = confirm(`Existem campos obrigatórios pendentes:\n- ${missing.join('\n- ')}\n\nDeseja baixar o Word (.DOC) mesmo assim?`);
        if (!cont) return;
      }

      const t = getActiveTheme();
      const density = state.bid.pdfDensity || 'compact';
      const isUltra = density === 'ultra';
      const isCompact = density === 'compact';
      const docHtml = buildDocumentHTML();

      const pageMargin = isUltra ? '0.8cm 0.9cm 0.8cm 0.9cm' : (isCompact ? '1.0cm 1.1cm 1.0cm 1.1cm' : '1.3cm 1.4cm 1.3cm 1.4cm');
      const bodyFont = isUltra ? '8.4pt' : (isCompact ? '9pt' : '9.5pt');
      const bodyLine = isUltra ? '1.24' : (isCompact ? '1.32' : '1.42');
      const tableFont = isUltra ? '7.7pt' : (isCompact ? '8.2pt' : '8.7pt');
      const cellPad = isUltra ? '2.5px 4.5px' : (isCompact ? '3.5px 5.5px' : '5px 6px');
      const secFont = isUltra ? '7.6pt' : (isCompact ? '8pt' : '8.4pt');
      const secPad = isUltra ? '3px 6px' : (isCompact ? '4px 7px' : '5px 8px');
      const quoteFont = isUltra ? '7.8pt' : (isCompact ? '8.4pt' : '8.9pt');

      const wordSource = `
        <html xmlns:o="urn:schemas-microsoft-com:office:office"
              xmlns:w="urn:schemas-microsoft-com:office:word"
              xmlns="http://www.w3.org/TR/REC-html40">
        <head>
          <meta charset="utf-8" />
          <title>${escapeHtml(getProposalDocumentTitle())} - ${escapeHtml(t.shortName)}</title>
          <!--[if gte mso 9]>
          <xml>
            <w:WordDocument>
              <w:View>Print</w:View>
              <w:Zoom>100</w:Zoom>
              <w:DoNotOptimizeForBrowser/>
            </w:WordDocument>
          </xml>
          <![endif]-->
          <style>
            @page {
              size: A4 portrait;
              margin: ${pageMargin};
            }
            body {
              font-family: Arial, Helvetica, sans-serif;
              font-size: ${bodyFont};
              color: #111827;
              line-height: ${bodyLine};
            }
            table.doc-header-table {
              width: 100%;
              border-collapse: collapse;
              margin-bottom: ${isUltra ? '6px' : (isCompact ? '8px' : '12px')};
              border-bottom: 2.5px solid ${t.primary};
            }
            table.doc-header-table td {
              border: none;
              padding: 0 0 6px 0;
              vertical-align: middle;
            }
            table.doc-data-table,
            table.doc-items-table {
              width: 100%;
              border-collapse: collapse;
              margin-bottom: ${isUltra ? '5px' : (isCompact ? '7px' : '10px')};
              font-size: ${tableFont};
            }
            table.doc-data-table th,
            table.doc-data-table td,
            table.doc-items-table th,
            table.doc-items-table td {
              border: 1px solid #334155;
              padding: ${cellPad};
              vertical-align: top;
              line-height: ${isUltra ? '1.22' : (isCompact ? '1.28' : '1.38')};
            }
            tr { page-break-inside: avoid; }
            .doc-keep, .doc-closing-group, .doc-decl-sig-pair, .doc-decl, .doc-signature { page-break-inside: avoid; break-inside: avoid; }
            .doc-sec-title,
            .doc-group-banner {
              background-color: ${t.primary};
              color: #ffffff;
              font-weight: bold;
              text-transform: uppercase;
              font-size: ${secFont};
              padding: ${secPad};
            }
            .doc-items-head th {
              background-color: ${t.softBg};
              color: ${t.primary};
              font-weight: bold;
              text-align: center;
              font-size: ${secFont};
            }
            .doc-group-subtotal td {
              background-color: ${t.subtotalBg};
              color: ${t.primary};
              font-weight: bold;
              font-size: ${tableFont};
            }
            .doc-total-box {
              background-color: ${t.subtotalBg};
              border: 1.5px solid ${t.primary};
              border-left: 5px solid ${t.accent};
              padding: ${isUltra ? '5px 8px' : (isCompact ? '6px 9px' : '8px 10px')};
              margin: ${isUltra ? '5px 0 6px 0' : (isCompact ? '7px 0 9px 0' : '10px 0 12px 0')};
              font-weight: bold;
              font-size: ${isUltra ? '8.5pt' : (isCompact ? '9pt' : '9.4pt')};
              color: ${t.primary};
            }
            .doc-quote {
              background-color: #f8fafc;
              border-left: 3.5px solid ${t.accent};
              padding: ${isUltra ? '5px 8px' : (isCompact ? '6px 9px' : '8px 10px')};
              margin: ${isUltra ? '5px 0' : (isCompact ? '7px 0' : '10px 0')};
              font-style: italic;
              text-align: justify;
              font-size: ${quoteFont};
            }
            .doc-decl {
              margin: ${isUltra ? '5px 0' : (isCompact ? '7px 0' : '10px 0')};
              text-align: justify;
              font-size: ${quoteFont};
            }
            .doc-signature {
              margin-top: ${isUltra ? '10px' : (isCompact ? '14px' : '20px')};
              text-align: center;
              page-break-inside: avoid;
            }
          </style>
        </head>
        <body>
          ${docHtml}
        </body>
        </html>
      `;

      const blob = new Blob(['\ufeff', wordSource], { type: 'application/msword;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = buildFilename('doc');
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      showToast(`Arquivo Word (.DOC) da ${t.shortName} baixado com sucesso!`);
    }

    function printNative() {
      window.print();
    }

    // =========================================================================
    // HISTÓRICO DE RASCUNHOS MULTI-EMPRESA (COMPARTILHADO NO FIREBASE) & BACKUP JSON
    // =========================================================================
    function setDraftCompanyFilter(filter) {
      state.draftFilterCompany = (filter === 'brava' || filter === 'next') ? filter : 'all';
      ['all', 'brava', 'next'].forEach(k => {
        const btn = document.getElementById('draft-filter-' + k);
        if (!btn) return;
        if (k === state.draftFilterCompany) {
          btn.className = 'px-2.5 py-1 rounded-md bg-white text-slate-900 shadow-sm transition';
        } else {
          btn.className = 'px-2.5 py-1 rounded-md text-slate-600 hover:text-slate-900 transition';
        }
      });
      renderDraftsList();
    }

    async function saveDraftPrompt() {
      const t = getActiveTheme();
      const defaultName = `[${t.badgeText}] ${state.bid.orgao || 'Proposta'} — ${state.bid.modalidade} ${state.bid.numero || ''}`.trim();
      const title = prompt(`Salvar proposta da ${t.shortName} no histórico:`, defaultName);
      if (title === null) return;

      const draft = {
        id: generateId(),
        companyId: state.activeCompanyId,
        companyLabel: state.company.razao || t.shortName,
        title: title.trim() || defaultName,
        savedAt: new Date().toLocaleString('pt-BR'),
        updatedAtMs: Date.now(),
        savedBy: getCollaboratorName(),
        total: computeGrandTotal(),
        itemCount: getAllItemsFlat().length,
        mode: state.bid.modoDisputa,
        phase: state.bid.tipoProposta,
        bid: JSON.parse(JSON.stringify(state.bid))
      };

      state.drafts.unshift(draft);
      saveToStorage();
      renderDraftsList();

      if (cloud.ready) {
        await saveDraftToCloud(draft);
        showToast(`Proposta da ${t.shortName} salva no histórico compartilhado!`);
      } else {
        showToast(`Rascunho da ${t.shortName} salvo no histórico local!`);
      }
    }

    function loadDraft(id) {
      const found = state.drafts.find(d => d.id === id);
      if (!found) return;
      if (window.CheckpointManager) window.CheckpointManager.capture('proposta', `Antes de carregar rascunho "${found.title || 'Salvo'}"`);
      const targetCompany = found.companyId === 'next' ? 'next' : 'brava';
      const switched = targetCompany !== state.activeCompanyId;

      if (switched) {
        flushCloudSaves(false);
        state.activeCompanyId = targetCompany;
      }

      state.bids[targetCompany] = normalizeBid(JSON.parse(JSON.stringify(found.bid)));
      bindActivePointers();
      saveToStorage();
      applyActiveCompanyTheme();
      populateFormFromState();
      switchTab('licitacao');

      const t = getActiveTheme();
      showToast(switched
        ? `Perfil alterado para ${t.shortName} e proposta "${found.title}" carregada!`
        : `Proposta "${found.title}" carregada!`);
    }

    async function deleteDraft(id) {
      const msg = cloud.ready
        ? 'Deseja excluir esta proposta do histórico compartilhado da equipe?'
        : 'Deseja excluir este rascunho do histórico?';
      if (!confirm(msg)) return;
      state.drafts = state.drafts.filter(d => d.id !== id);
      saveToStorage();
      renderDraftsList();
      if (cloud.ready) {
        await deleteDraftFromCloud(id);
      }
      showToast('Proposta removida do histórico.');
    }

    function renderDraftsList() {
      const list = document.getElementById('drafts-list');
      document.getElementById('drafts-count-badge').textContent = state.drafts.length;
      if (window.PlatformHub) window.PlatformHub.updateSidebarBadges();

      const searchEl = document.getElementById('drafts-search');
      const query = searchEl ? normalizeHeaderStr(searchEl.value) : '';
      const compFilter = state.draftFilterCompany || 'all';

      const filtered = state.drafts.filter(d => {
        const dComp = d.companyId === 'next' ? 'next' : 'brava';
        if (compFilter !== 'all' && dComp !== compFilter) return false;
        if (!query) return true;
        const hay = normalizeHeaderStr(`${d.title || ''} ${d.savedBy || ''} ${d.savedAt || ''} ${dComp}`);
        return hay.includes(query);
      });

      if (state.drafts.length === 0) {
        list.innerHTML = `
          <div class="text-center py-8 bg-slate-50 border border-dashed border-slate-300 rounded-xl text-xs text-slate-500">
            Nenhuma proposta salva ainda. Clique em <strong>"+ Salvar Atual"</strong> acima para arquivar propostas.
          </div>`;
        return;
      }

      if (filtered.length === 0) {
        list.innerHTML = `
          <div class="text-center py-6 bg-slate-50 border border-dashed border-slate-300 rounded-xl text-xs text-slate-500">
            Nenhuma proposta encontrada para o filtro atual.
          </div>`;
        return;
      }

      list.innerHTML = filtered.map(d => {
        const dComp = d.companyId === 'next' ? 'next' : 'brava';
        const badgeHtml = dComp === 'next'
          ? '<span class="px-1.5 py-0.5 rounded bg-[#111827] text-[#4ade80] text-[9.5px] font-extrabold uppercase shrink-0">NEXT</span>'
          : '<span class="px-1.5 py-0.5 rounded bg-[#1e2f53] text-sky-200 text-[9.5px] font-extrabold uppercase shrink-0">BRAVA</span>';

        const count = typeof d.itemCount === 'number'
          ? d.itemCount
          : (d.bid && d.bid.groups ? d.bid.groups.reduce((s, g) => s + (g.items ? g.items.length : 0), 0) : (d.bid && d.bid.items ? d.bid.items.length : 0));
        const modeTag = (d.mode === 'lote' ? 'Por Lote/Grupo' : 'Por Item') + (d.phase === 'readequada' ? ' • Readequada' : '');
        const authorTag = d.savedBy && d.savedBy !== 'Local'
          ? ` &bull; <span class="text-[#1e2f53] font-medium">${escapeHtml(d.savedBy)}</span>`
          : '';
        return `
          <div class="border border-slate-200 rounded-xl p-3 bg-white hover:border-[#1fa6da] transition flex items-center justify-between gap-3">
            <div class="min-w-0">
              <div class="flex items-center gap-1.5">
                ${badgeHtml}
                <p class="text-xs font-bold text-slate-900 truncate">${escapeHtml(d.title)}</p>
              </div>
              <p class="text-[11px] text-slate-500 mt-0.5">Salvo em ${escapeHtml(d.savedAt)}${authorTag} &bull; <strong class="text-emerald-700">${formatBRL(d.total)}</strong> &bull; ${count} ${count === 1 ? 'item' : 'itens'} (${modeTag})</p>
            </div>
            <div class="flex items-center gap-1.5 shrink-0">
              <button onclick="loadDraft('${d.id}')" class="px-2.5 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-800 text-xs font-semibold">Carregar</button>
              <button onclick="deleteDraft('${d.id}')" class="px-2.5 py-1.5 rounded-lg bg-red-50 hover:bg-red-100 text-red-600 text-xs font-semibold">Excluir</button>
            </div>
          </div>
        `;
      }).join('');
    }

    function exportBackupJSON() {
      const payload = {
        exportedAt: new Date().toISOString(),
        activeCompanyId: state.activeCompanyId,
        companies: state.companies,
        bids: state.bids,
        company: state.company,
        bid: state.bid,
        drafts: state.drafts
      };
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Propostas_Brava_e_Next_Backup_${getTodayISO()}.json`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('Backup completo (Brava + Next) exportado!');
    }

    function importBackupJSON(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async function(e) {
        try {
          const data = JSON.parse(e.target.result);
          if (data.companies) {
            if (data.companies.brava) state.companies.brava = normalizeCompany(data.companies.brava, 'brava');
            if (data.companies.next) state.companies.next = normalizeCompany(data.companies.next, 'next');
          } else if (data.company) {
            state.companies[state.activeCompanyId] = normalizeCompany(data.company, state.activeCompanyId);
          }

          if (data.bids) {
            if (data.bids.brava) state.bids.brava = normalizeBid(data.bids.brava);
            if (data.bids.next) state.bids.next = normalizeBid(data.bids.next);
          } else if (data.bid) {
            state.bids[state.activeCompanyId] = normalizeBid(data.bid);
          }

          if (data.activeCompanyId === 'next' || data.activeCompanyId === 'brava') {
            state.activeCompanyId = data.activeCompanyId;
          }
          bindActivePointers();

          if (Array.isArray(data.drafts)) {
            state.drafts = data.drafts.map(d => ({
              ...d,
              companyId: d.companyId === 'next' ? 'next' : 'brava'
            }));
            if (cloud.ready) {
              for (const d of state.drafts) {
                await saveDraftToCloud({
                  ...d,
                  id: d.id || generateId(),
                  updatedAtMs: d.updatedAtMs || Date.now(),
                  savedBy: d.savedBy || getCollaboratorName()
                });
              }
            }
          }
          saveToStorage();
          if (cloud.ready) {
            await flushCloudSaves(false);
          }
          applyActiveCompanyTheme();
          populateFormFromState();
          showToast(cloud.ready ? 'Backup restaurado e sincronizado no Firebase!' : 'Backup restaurado com sucesso!');
        } catch (err) {
          alert('Arquivo JSON inválido.');
        }
      };
      reader.readAsText(file);
      event.target.value = '';
    }

    // =========================================================================
    // NAVEGAÇÃO, ZOOM E RESET
    // =========================================================================
    function switchTab(tabName) {
      document.querySelectorAll('#module-proposta .tab-content').forEach(el => el.classList.add('hidden'));
      document.getElementById('tab-' + tabName).classList.remove('hidden');

      document.querySelectorAll('#module-proposta .tab-btn').forEach(btn => {
        btn.classList.remove('border-[#1fa6da]', 'text-[#1e2f53]', 'bg-white');
        btn.classList.add('border-transparent', 'text-slate-500');
      });

      const activeBtn = document.getElementById('tab-btn-' + tabName);
      if (window.PlatformHub) window.PlatformHub.highlightPropostaTab(tabName);
      activeBtn.classList.add('border-[#1fa6da]', 'text-[#1e2f53]', 'bg-white');
      activeBtn.classList.remove('border-transparent', 'text-slate-500');
    }

    function setMobileView(view) {
      const editor = document.getElementById('editor-panel');
      const preview = document.getElementById('preview-panel');
      const btnEd = document.getElementById('mob-btn-editor');
      const btnPr = document.getElementById('mob-btn-preview');

      if (view === 'preview') {
        editor.classList.add('hidden');
        preview.classList.remove('hidden');
        preview.classList.add('flex');
        btnPr.classList.add('text-[#1e2f53]', 'border-b-2', 'border-[#1fa6da]');
        btnPr.classList.remove('text-slate-500');
        btnEd.classList.remove('text-[#1e2f53]', 'border-b-2', 'border-[#1fa6da]');
        btnEd.classList.add('text-slate-500');
        autoFitZoom();
      } else {
        editor.classList.remove('hidden');
        preview.classList.add('hidden');
        preview.classList.remove('flex');
        btnEd.classList.add('text-[#1e2f53]', 'border-b-2', 'border-[#1fa6da]');
        btnEd.classList.remove('text-slate-500');
        btnPr.classList.remove('text-[#1e2f53]', 'border-b-2', 'border-[#1fa6da]');
        btnPr.classList.add('text-slate-500');
      }
    }

    function applyZoom() {
      const doc = document.getElementById('proposal-document');
      doc.style.transform = `scale(${state.zoom})`;
      document.getElementById('zoom-label').textContent = `${Math.round(state.zoom * 100)}%`;
    }

    function adjustZoom(delta) {
      state.zoom = Math.min(1.3, Math.max(0.45, Math.round((state.zoom + delta) * 100) / 100));
      applyZoom();
    }

    function autoFitZoom() {
      const scroll = document.getElementById('preview-scroll');
      if (!scroll) return;
      const availableWidth = scroll.clientWidth - 40;
      const a4Px = 794; // ~210mm em 96dpi
      const fit = Math.min(1.0, Math.max(0.45, availableWidth / a4Px));
      state.zoom = Math.round(fit * 20) / 20;
      applyZoom();
    }

    function startNewBid() {
      const t = getActiveTheme();
      if (!confirm(`Limpar os campos da licitação e itens da ${t.shortName} para iniciar uma nova disputa? (Os dados cadastrais e logomarca da ${t.shortName} serão mantidos)`)) return;
      if (window.CheckpointManager) window.CheckpointManager.capture('proposta', 'Antes de limpar para nova disputa');
      const prevMode = state.bid.modoDisputa;
      const prevLabel = state.bid.rotuloGrupo;
      const prevLines = state.bid.descMaxLines;
      const prevDensity = state.bid.pdfDensity;
      const prevPageMode = state.bid.pdfPageMode;
      const prevRepeat = state.bid.pdfRepeatHead;
      const prevKeepEnd = state.bid.pdfKeepEndTogether;
      const prevBreakLots = state.bid.pdfBreakBetweenLots;
      const prevGuides = state.bid.pdfShowGuides;
      state.bids[state.activeCompanyId] = getDefaultBid();
      bindActivePointers();
      state.bid.modoDisputa = prevMode;
      state.bid.rotuloGrupo = prevLabel;
      state.bid.descMaxLines = prevLines !== undefined ? prevLines : 2;
      state.bid.pdfDensity = prevDensity || 'compact';
      state.bid.compactLayout = state.bid.pdfDensity !== 'normal';
      state.bid.pdfPageMode = prevPageMode || 'smart';
      state.bid.pdfRepeatHead = prevRepeat !== undefined ? prevRepeat : true;
      state.bid.pdfKeepEndTogether = prevKeepEnd !== undefined ? prevKeepEnd : true;
      state.bid.pdfBreakBetweenLots = !!prevBreakLots;
      state.bid.pdfShowGuides = prevGuides !== undefined ? prevGuides : true;
      saveToStorage();
      populateFormFromState();
      showToast(`Campos limpos para nova licitação da ${t.shortName}!`);
    }

    function resetCompanyToBase() {
      const t = getActiveTheme();
      if (!confirm(`Restaurar os dados cadastrais e a logomarca oficial da ${t.shortName}?`)) return;
      state.companies[state.activeCompanyId] = getDefaultCompany(state.activeCompanyId);
      bindActivePointers();
      saveToStorage();
      applyActiveCompanyTheme();
      populateFormFromState();
      showToast(`Perfil e logomarca da ${t.shortName} restaurados!`);
    }

    function resetDefaultDeclarations() {
      state.bid.declPrecos = DEFAULT_DECL_PRECOS;
      state.bid.declAlineas = DEFAULT_DECL_ALINEAS;
      saveToStorage();
      populateFormFromState();
      showToast('Declarações originais restauradas!');
    }

    // =========================================================================
    // INICIALIZAÇÃO
    // =========================================================================
    window.addEventListener('DOMContentLoaded', () => {
      loadFromStorage();
      applyActiveCompanyTheme();
      populateFormFromState();
      setSyncStatusUI('local', 'Aguardando login', 'Login');
      setTimeout(autoFitZoom, 120);
      window.addEventListener('resize', window.__rafThrottle(() => {
        if (window.innerWidth >= 1024) autoFitZoom();
      }), { passive: true });
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') {
          flushCloudSaves(false);
        } else if (document.visibilityState === 'visible') {
          ensureCurrentSystemDate(false);
          renderPreview();
        }
      });
    });
  
    window.PropostaBridge = {
      getState: () => state,
      getActiveTheme: () => getActiveTheme(),
      computeGrandTotal: () => computeGrandTotal(),
      getAllItemsFlat: () => getAllItemsFlat(),
      switchCompanyProfile: (id, silent) => switchCompanyProfile(id, silent),
      switchTab: (tab) => switchTab(tab),
      populateFormFromState: () => populateFormFromState(),
      saveToStorage: () => saveToStorage(),
      renderPreview: () => renderPreview(),
      autoFitZoom: () => autoFitZoom(),
      showToast: (m) => showToast(m),
      createEmptyItem: (n) => createEmptyItem(n),
      generateId: () => generateId(),
      initFirebaseAfterAuth: (user) => initFirebaseDirect(user),
      flushCloudSaves: (showFb) => flushCloudSaves(showFb),
      disconnectFirebase: async () => {
        try { await flushCloudSaves(false); } catch (e) {}
        ['brava', 'next'].forEach(pid => {
          if (cloud.unsubCompanies[pid]) { cloud.unsubCompanies[pid](); cloud.unsubCompanies[pid] = null; }
        });
        if (cloud.unsubDrafts) { cloud.unsubDrafts(); cloud.unsubDrafts = null; }
        cloud.ready = false;
        cloud.initialLoaded = false;
        cloud.user = null;
        setSyncStatusUI('local', 'Sessão encerrada', 'Desconectado');
      },
      ensureCurrentSystemDate: (force) => { const d = ensureCurrentSystemDate(force); renderPreview(); return d; },
      setCollaboratorFromAuth: (displayName) => {
        if (displayName) {
          try { localStorage.setItem(STORAGE_KEYS.COLLAB_NAME, displayName); } catch (e) {}
        }
        updateCollaboratorUI();
      },
      captureBidSnapshot: () => ({
        companyId: state.activeCompanyId,
        bid: JSON.parse(JSON.stringify(state.bid))
      }),
      restoreBidSnapshot: (snap) => {
        if (!snap || !snap.bid) return false;
        const pid = snap.companyId === 'next' ? 'next' : (state.activeCompanyId === 'next' ? 'next' : 'brava');
        state.bids[pid] = normalizeBid(JSON.parse(JSON.stringify(snap.bid)));
        if (state.activeCompanyId !== pid) {
          state.activeCompanyId = pid;
        }
        bindActivePointers();
        saveToStorage();
        applyActiveCompanyTheme();
        populateFormFromState();
        return true;
      }
    };

