    const OPEN_STATUSES = new Set([
      'Iniciar', 'Participar', 'Em Adjucação', 'Aguardando Ata',
      'Cotar', 'Lançar', 'Homologada', 'Recurso', 'TI Avaliando',
      'Habilitação', 'Enviado P/ Análise', 'EM RO', 'RO Aprovado', 'Inserir no Pipe', 'Adiada'
    ]);

    let state = {
      records: [],
      filtered: [],
      meta: { source: 'Agenda Participação.xlsx (Base Auditada)', updatedAt: null },
      tab: 'list',
      calendarMode: 'month',
      calendarDate: new Date(),
      period: 'all',
      sortKey: 'data',
      sortDir: 'desc',
      page: 1,
      pageSize: 25,
      selectedUid: null,
      pendingWorkbook: null,
      pendingFileName: ''
    };

    // ==================== DATE & FORMAT HELPERS ====================
    function getTodayISO() {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    }

    function parseISO(iso) {
      if (!iso || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return null;
      const [y, m, d] = iso.split('-').map(Number);
      return new Date(y, m - 1, d);
    }

    function formatDateBR(iso) {
      if (!iso) return 'Sem data';
      const [y, m, d] = iso.split('-');
      return `${d}/${m}/${y}`;
    }

    function formatBRL(val) {
      if (val === null || val === undefined || isNaN(val)) return '—';
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(val);
    }

    function formatBRLWhole(val) {
      if (!val || isNaN(val)) return 'R$ 0';
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(val);
    }

    function diffDaysFromToday(iso) {
      const dt = parseISO(iso);
      if (!dt) return null;
      const now = new Date();
      const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      return Math.round((dt - today) / 86400000);
    }

    function escapeHtml(str) {
      if (str === null || str === undefined) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    function isValidUrl(str) {
      return typeof str === 'string' && /^https?:\/\//i.test(str.trim());
    }

    function displayOrgao(orgao) {
      if (!orgao) return '—';
      if (isValidUrl(orgao)) return '[Link colado no campo Órgão — revisar]';
      return orgao;
    }

    function getStatusStyle(status) {
      const s = (status || '').toLowerCase();
      if (s.includes('ata assinada') || s.includes('homologada') || s.includes('entregue') || s.includes('ganh')) {
        return { badge: 'bg-emerald-50 text-emerald-700 border-emerald-200', dot: 'bg-emerald-500', cal: 'bg-emerald-100 text-emerald-800 border-emerald-200' };
      }
      if (s.includes('perdida') || s.includes('cancelad') || s.includes('fracassad')) {
        return { badge: 'bg-rose-50 text-rose-700 border-rose-200', dot: 'bg-rose-500', cal: 'bg-rose-50 text-rose-700 border-rose-200' };
      }
      if (s.includes('não participa') || s.includes('nao participa') || s.includes('parou')) {
        return { badge: 'bg-slate-100 text-slate-600 border-slate-200', dot: 'bg-slate-400', cal: 'bg-slate-100 text-slate-600 border-slate-200' };
      }
      if (s.includes('iniciar') || s.includes('participar')) {
        return { badge: 'bg-indigo-50 text-indigo-700 border-indigo-200', dot: 'bg-indigo-500', cal: 'bg-indigo-100 text-indigo-800 border-indigo-200' };
      }
      if (s.includes('adjuca') || s.includes('cotar') || s.includes('lançar') || s.includes('aguardando') || s.includes('habilita')) {
        return { badge: 'bg-amber-50 text-amber-800 border-amber-200', dot: 'bg-amber-500', cal: 'bg-amber-100 text-amber-900 border-amber-200' };
      }
      if (s.includes('suspens') || s.includes('revogad') || s.includes('recurso') || s.includes('adiad')) {
        return { badge: 'bg-purple-50 text-purple-700 border-purple-200', dot: 'bg-purple-500', cal: 'bg-purple-100 text-purple-800 border-purple-200' };
      }
      return { badge: 'bg-sky-50 text-sky-700 border-sky-200', dot: 'bg-sky-500', cal: 'bg-sky-100 text-sky-800 border-sky-200' };
    }

    function getDeadlineAlert(rec) {
      const diff = diffDaysFromToday(rec.data);
      const isOpen = OPEN_STATUSES.has(rec.status);
      if (diff === null) {
        if (rec.dataAlerta) return { label: 'Data inválida', cls: 'bg-rose-100 text-rose-800', rowCls: 'border-l-4 border-l-rose-400 bg-rose-50/30' };
        return null;
      }
      if (diff === 0) {
        return { label: 'HOJE', cls: 'bg-rose-600 text-white', rowCls: 'border-l-4 border-l-rose-500 bg-rose-50/60' };
      }
      if (diff === 1 && isOpen) {
        return { label: 'AMANHÃ', cls: 'bg-amber-500 text-white', rowCls: 'border-l-4 border-l-amber-400 bg-amber-50/50' };
      }
      if (diff > 1 && diff <= 3 && isOpen) {
        return { label: `Em ${diff} dias`, cls: 'bg-amber-100 text-amber-800', rowCls: 'border-l-4 border-l-amber-400 bg-amber-50/40' };
      }
      if (diff > 3 && diff <= 7 && isOpen) {
        return { label: `Em ${diff} dias`, cls: 'bg-indigo-100 text-indigo-800', rowCls: 'border-l-4 border-l-indigo-400 bg-indigo-50/20' };
      }
      if (diff < 0 && isOpen) {
        return { label: 'Vencido em aberto', cls: 'bg-orange-100 text-orange-800', rowCls: 'border-l-4 border-l-orange-400 bg-orange-50/30' };
      }
      return null;
    }

    // ==================== PERSISTENCE ====================
    function loadFromStorage() {
      try {
        const saved = localStorage.getItem(STORAGE_KEY_DATA);
        const savedMeta = localStorage.getItem(STORAGE_KEY_META);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed) && parsed.length > 0) {
            state.records = parsed;
            if (savedMeta) state.meta = JSON.parse(savedMeta);
            return;
          }
        }
      } catch (e) { console.warn('Erro ao ler localStorage:', e); }
      state.records = JSON.parse(JSON.stringify(INITIAL_DATA));
      state.meta = { source: 'Agenda Participação.xlsx (Base Auditada)', updatedAt: new Date().toISOString() };
      saveToStorage();
    }

    function saveToStorage() {
      try {
        localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(state.records));
        localStorage.setItem(STORAGE_KEY_META, JSON.stringify(state.meta));
      } catch (e) {
        showToast('Aviso: limite do localStorage atingido. Exporte em Excel para salvar.', '⚠️');
      }
      updateSourceInfo();
    }

    function updateSourceInfo() {
      const el = document.getElementById('sourceInfo');
      const dtStr = state.meta.updatedAt ? ' • Atualizado em ' + new Date(state.meta.updatedAt).toLocaleString('pt-BR', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' }) : '';
      el.textContent = `Base: ${state.meta.source} (${state.records.length} pregões)${dtStr}`;
    }

    // ==================== FILTER & SORT ENGINE ====================
    function populateFilterDropdowns() {
      const statuses = [...new Set([...state.records.map(r => r.status).filter(Boolean), ...REF_LISTS.status])].sort((a,b) => a.localeCompare(b, 'pt-BR'));
      const portals = [...new Set(state.records.map(r => r.portal).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'pt-BR'));
      const empresas = [...new Set(state.records.map(r => r.empresa).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'pt-BR'));
      const ufs = [...new Set(state.records.map(r => r.uf).filter(Boolean))].sort();
      const modalidades = [...new Set([...state.records.map(r => r.modalidade).filter(Boolean), ...REF_LISTS.modalidade])].sort((a,b) => a.localeCompare(b, 'pt-BR'));

      fillSelect('filterStatus', statuses, 'Todos os Status');
      fillSelect('filterPortal', portals, 'Todos os Portais');
      fillSelect('filterEmpresa', empresas, 'Todas as Empresas');
      fillSelect('filterUF', ufs, 'UF');
      fillSelect('editStatus', statuses, null);
      fillSelect('newBidStatusSelect', statuses, null, 'Iniciar');
      fillSelect('newBidModSelect', modalidades, null, 'Registro de Preço');

      document.getElementById('dlEmpresas').innerHTML = empresas.map(e => `<option value="${escapeHtml(e)}">`).join('');
      document.getElementById('dlPortais').innerHTML = portals.map(p => `<option value="${escapeHtml(p)}">`).join('');
    }

    function fillSelect(id, options, placeholder, defaultVal) {
      const sel = document.getElementById(id);
      if (!sel) return;
      const prev = sel.value;
      sel.innerHTML = '';
      if (placeholder !== null) {
        const opt = document.createElement('option');
        opt.value = '';
        opt.textContent = placeholder;
        sel.appendChild(opt);
      }
      options.forEach(v => {
        const opt = document.createElement('option');
        opt.value = v;
        opt.textContent = v;
        sel.appendChild(opt);
      });
      if (prev && options.includes(prev)) sel.value = prev;
      else if (defaultVal && options.includes(defaultVal)) sel.value = defaultVal;
    }

    function hasActiveFilters() {
      return Boolean(
        document.getElementById('searchInput').value.trim() ||
        document.getElementById('filterStatus').value ||
        document.getElementById('filterPortal').value ||
        document.getElementById('filterEmpresa').value ||
        document.getElementById('filterUF').value ||
        state.period !== 'all'
      );
    }

    function applyFilters() {
      const q = document.getElementById('searchInput').value.trim().toLowerCase();
      document.getElementById('ag-clearSearchBtn').classList.toggle('hidden', !q);

      const fStatus = document.getElementById('filterStatus').value;
      const fPortal = document.getElementById('filterPortal').value;
      const fEmpresa = document.getElementById('filterEmpresa').value;
      const fUF = document.getElementById('filterUF').value;
      const dFrom = document.getElementById('dateFrom').value;
      const dTo = document.getElementById('dateTo').value;

      const now = new Date();
      const todayISO = getTodayISO();
      const curYear = now.getFullYear();
      const curMonth = now.getMonth();

      const startOfWeek = new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay());
      const endOfWeek = new Date(startOfWeek.getFullYear(), startOfWeek.getMonth(), startOfWeek.getDate() + 6);

      state.filtered = state.records.filter(r => {
        if (fStatus && r.status !== fStatus) return false;
        if (fPortal && r.portal !== fPortal) return false;
        if (fEmpresa && r.empresa !== fEmpresa) return false;
        if (fUF && r.uf !== fUF) return false;

        if (q) {
          const notesText = (r.notas || []).map(n => n.text).join(' ');
          const hay = `${r.orgao} ${r.objeto} ${r.edital} ${r.empresa} ${r.portal} ${r.uf} ${r.modalidade} ${r.status} ${r.questionamento} ${r.pedidosObs} ${notesText}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }

        if (state.period === 'today') {
          if (r.data !== todayISO) return false;
        } else if (state.period === 'week') {
          const dt = parseISO(r.data);
          if (!dt || dt < startOfWeek || dt > endOfWeek) return false;
        } else if (state.period === 'month') {
          const dt = parseISO(r.data);
          if (!dt || dt.getFullYear() !== curYear || dt.getMonth() !== curMonth) return false;
        } else if (state.period === 'next30') {
          const diff = diffDaysFromToday(r.data);
          if (diff === null || diff < 0 || diff > 30) return false;
        } else if (state.period === 'overdue') {
          const diff = diffDaysFromToday(r.data);
          if (diff === null || diff >= 0 || !OPEN_STATUSES.has(r.status)) return false;
        } else if (state.period === 'custom') {
          if (dFrom && (!r.data || r.data < dFrom)) return false;
          if (dTo && (!r.data || r.data > dTo)) return false;
        }
        return true;
      });

      const dir = state.sortDir === 'asc' ? 1 : -1;
      state.filtered.sort((a, b) => {
        if (state.sortKey === 'valor') {
          const aNull = (a.valor === null || a.valor === undefined);
          const bNull = (b.valor === null || b.valor === undefined);
          if (aNull && bNull) return 0;
          if (aNull) return 1;
          if (bNull) return -1;
          return (a.valor - b.valor) * dir;
        }
        if (state.sortKey === 'data') {
          const aEmpty = !a.data;
          const bEmpty = !b.data;
          if (aEmpty && bEmpty) return 0;
          if (aEmpty) return 1; // Always push empty dates to the bottom
          if (bEmpty) return -1;
          const ka = a.data + ' ' + (a.horario || '00:00');
          const kb = b.data + ' ' + (b.horario || '00:00');
          return ka.localeCompare(kb) * dir;
        }
        return String(a[state.sortKey] || '').localeCompare(String(b[state.sortKey] || ''), 'pt-BR') * dir;
      });

      renderAll();
    }

    function onFilterChange() {
      state.page = 1;
      applyFilters();
    }

    function clearSearch() {
      document.getElementById('searchInput').value = '';
      onFilterChange();
    }

    function setQuickPeriod(p) {
      state.period = p;
      document.getElementById('dateFrom').value = '';
      document.getElementById('dateTo').value = '';
      document.querySelectorAll('#module-agenda .period-pill').forEach(btn => {
        btn.classList.toggle('pill-active', btn.dataset.period === p);
      });
      state.page = 1;
      applyFilters();
    }

    function onCustomDateChange() {
      const f = document.getElementById('dateFrom').value;
      const t = document.getElementById('dateTo').value;
      state.period = (f || t) ? 'custom' : 'all';
      document.querySelectorAll('#module-agenda .period-pill').forEach(btn => {
        btn.classList.toggle('pill-active', btn.dataset.period === state.period);
      });
      state.page = 1;
      applyFilters();
    }

    function resetAllFilters() {
      document.getElementById('searchInput').value = '';
      document.getElementById('filterStatus').value = '';
      document.getElementById('filterPortal').value = '';
      document.getElementById('filterEmpresa').value = '';
      document.getElementById('filterUF').value = '';
      document.getElementById('dateFrom').value = '';
      document.getElementById('dateTo').value = '';
      setQuickPeriod('all');
    }

    function sortBy(key) {
      if (state.sortKey === key) {
        state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
      } else {
        state.sortKey = key;
        state.sortDir = key === 'data' || key === 'valor' ? 'desc' : 'asc';
      }
      ['data','edital','orgao','portal','valor','status'].forEach(k => {
        const el = document.getElementById(`sort-${k}`);
        if (el) el.textContent = k === state.sortKey ? (state.sortDir === 'asc' ? '↑' : '↓') : '';
      });
      applyFilters();
    }

    // ==================== RENDER DASHBOARD KPIs ====================
    function renderKPIs() {
      const now = new Date();
      const todayISO = getTodayISO();
      const curY = now.getFullYear();
      const curM = now.getMonth();
      const monthLabel = now.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
      const filteredActive = hasActiveFilters();

      document.getElementById('kpiFilterBadge1').classList.toggle('hidden', !filteredActive);
      document.getElementById('kpiFilterBadge2').classList.toggle('hidden', !filteredActive);

      const all = state.records;
      const inMonth = all.filter(r => {
        const d = parseISO(r.data);
        return d && d.getFullYear() === curY && d.getMonth() === curM;
      });
      const inMonthOpen = inMonth.filter(r => OPEN_STATUSES.has(r.status)).length;

      const todayBids = all.filter(r => r.data === todayISO);
      const next7Bids = all.filter(r => {
        const diff = diffDaysFromToday(r.data);
        return diff !== null && diff >= 0 && diff <= 7 && OPEN_STATUSES.has(r.status);
      });

      const scoped = state.filtered;
      let valAtas = 0, valBruto = 0, countAtasPriced = 0, countAtasTotal = 0;
      scoped.forEach(r => {
        if (r.status === 'Ata Assinada') {
          countAtasTotal++;
          if (typeof r.valor === 'number') { valAtas += r.valor; countAtasPriced++; }
        }
        if (typeof r.valor === 'number') valBruto += r.valor;
      });

      const openCount = scoped.filter(r => OPEN_STATUSES.has(r.status)).length;
      const overdueCount = scoped.filter(r => {
        const diff = diffDaysFromToday(r.data);
        return diff !== null && diff < 0 && OPEN_STATUSES.has(r.status);
      }).length;
      const atasDecided = scoped.filter(r => r.status === 'Ata Assinada').length;
      const perdidasDecided = scoped.filter(r => r.status === 'Perdida').length;
      const winRate = (atasDecided + perdidasDecided) > 0 ? (atasDecided / (atasDecided + perdidasDecided) * 100) : 0;

      document.getElementById('kpiMonthTotal').textContent = inMonth.length;
      document.getElementById('kpiMonthSub').innerHTML = `<span class="capitalize font-medium text-slate-700">${monthLabel}</span> • ${inMonthOpen} em aberto`;

      document.getElementById('kpiTodayTotal').textContent = todayBids.length;
      document.getElementById('kpiTodaySub').innerHTML = todayBids.length > 0
        ? `<span class="text-rose-600 font-semibold">Atenção hoje!</span> • ${next7Bids.length} nos próx. 7 dias`
        : `Nenhum hoje • <span class="text-indigo-600 font-semibold">${next7Bids.length} em aberto nos próx. 7 dias</span>`;

      document.getElementById('kpiValueAtas').textContent = formatBRLWhole(valAtas);
      document.getElementById('kpiValueAtas').title = `Exato em Atas: ${formatBRL(valAtas)} | Total Bruto na planilha: ${formatBRL(valBruto)}`;
      const diffExtra = valBruto - valAtas;
      document.getElementById('kpiValueSub').textContent = `${countAtasPriced}/${countAtasTotal} atas com valor` + (diffExtra > 0 ? ` • Bruto: ${formatBRLWhole(valBruto)}` : '');

      document.getElementById('kpiOpenTotal').textContent = openCount;
      document.getElementById('kpiWinRateBadge').textContent = `${winRate.toFixed(1)}% Win Rate`;
      document.getElementById('kpiOpenSub').innerHTML = overdueCount > 0
        ? `<span class="text-orange-600 font-semibold">${overdueCount} vencidos sem baixa</span> • ${atasDecided} atas / ${perdidasDecided} perdidas`
        : `${atasDecided} atas assinadas • ${perdidasDecided} perdidas`;
    }

    // ==================== RENDER TABLE VIEW ====================
    function renderTable() {
      const total = state.filtered.length;
      document.getElementById('resultsCount').textContent = `Exibindo ${total} de ${state.records.length} pregões`;

      const tbody = document.getElementById('tableBody');
      const emptyEl = document.getElementById('tableEmpty');
      const pagBar = document.getElementById('paginationBar');

      if (total === 0) {
        tbody.innerHTML = '';
        emptyEl.classList.remove('hidden');
        pagBar.classList.add('hidden');
        return;
      }

      emptyEl.classList.add('hidden');
      pagBar.classList.remove('hidden');

      const totalPages = Math.max(1, Math.ceil(total / state.pageSize));
      if (state.page > totalPages) state.page = totalPages;
      const start = (state.page - 1) * state.pageSize;
      const slice = state.filtered.slice(start, start + state.pageSize);

      document.getElementById('pageInfo').textContent = `Página ${state.page} de ${totalPages} (${start + 1}–${Math.min(start + state.pageSize, total)})`;
      document.getElementById('btnPrevPage').disabled = state.page <= 1;
      document.getElementById('btnNextPage').disabled = state.page >= totalPages;

      tbody.innerHTML = slice.map(r => {
        const st = getStatusStyle(r.status);
        const dl = getDeadlineAlert(r);
        const rowAccent = dl ? dl.rowCls : 'border-l-4 border-l-transparent hover:bg-slate-50/90';
        const hasNotes = (r.notas && r.notas.length > 0);
        const valMismatch = (r.valor > 0 && r.status !== 'Ata Assinada');
        const orgText = displayOrgao(r.orgao);

        return `
          <tr onclick="AgendaModule.openDrawer('${r.uid}')" class="cursor-pointer transition ${rowAccent} hover:bg-indigo-50/30">
            <td class="py-3 pl-4 pr-3 whitespace-nowrap align-top">
              <div class="font-semibold text-slate-900 tabular-nums">${formatDateBR(r.data)}</div>
              <div class="text-xs text-slate-500 flex items-center gap-1.5 mt-0.5">
                <span>${escapeHtml(r.horario || '--:--')}</span>
                ${dl ? `<span class="inline-flex px-1.5 py-0.5 rounded text-[10px] font-bold leading-none ${dl.cls}">${dl.label}</span>` : ''}
              </div>
            </td>
            <td class="py-3 px-3 whitespace-nowrap align-top">
              <div class="font-semibold text-slate-800">${escapeHtml(r.edital || 'S/N')}</div>
              <div class="text-xs text-slate-500 mt-0.5">${escapeHtml(r.empresa || 'Sem empresa')}</div>
            </td>
            <td class="py-3 px-3 align-top max-w-[240px]">
              <div class="font-semibold ${isValidUrl(r.orgao) ? 'text-amber-700 italic' : 'text-slate-900'} truncate" title="${escapeHtml(r.orgao)}">${escapeHtml(orgText)}</div>
              <div class="text-xs text-slate-500 mt-0.5 flex items-center gap-1.5">
                ${r.uf ? `<span class="inline-flex px-1.5 py-0.5 rounded bg-slate-100 text-slate-700 font-semibold text-[10px] leading-none">${escapeHtml(r.uf)}</span>` : ''}
                ${r.prazoEntrega ? `<span class="truncate" title="Prazo de entrega: ${escapeHtml(r.prazoEntrega)}">Entrega: ${escapeHtml(r.prazoEntrega)}</span>` : ''}
              </div>
            </td>
            <td class="py-3 px-3 whitespace-nowrap align-top">
              <div class="text-xs font-semibold text-slate-700">${escapeHtml(r.portal || '—')}</div>
              <div class="text-[11px] text-slate-500 mt-0.5">${escapeHtml(r.modalidade || '—')}</div>
            </td>
            <td class="py-3 px-3 align-top max-w-[260px]">
              <p class="text-xs text-slate-600 line-clamp-2 leading-relaxed" title="${escapeHtml(r.objeto)}">${escapeHtml(r.objeto || '—')}</p>
              ${hasNotes ? `<span class="inline-flex items-center gap-1 mt-1 text-[10px] font-semibold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded">📝 ${r.notas.length} nota(s)</span>` : ''}
            </td>
            <td class="py-3 px-3 whitespace-nowrap text-right align-top">
              <div class="font-semibold tabular-nums ${valMismatch ? 'text-amber-700' : (r.valor ? 'text-emerald-700' : 'text-slate-400')}">${formatBRL(r.valor)}</div>
              ${valMismatch ? `<div class="text-[10px] text-amber-600" title="Valor preenchido em status diferente de Ata Assinada">fora de Ata</div>` : ''}
            </td>
            <td class="py-3 px-3 whitespace-nowrap align-top">
              <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border ${st.badge}">
                <span class="w-1.5 h-1.5 rounded-full ${st.dot}"></span>
                ${escapeHtml(r.status || 'Sem status')}
              </span>
            </td>
            <td class="py-3 pl-2 pr-4 whitespace-nowrap text-right align-top" onclick="event.stopPropagation()">
              <div class="inline-flex items-center gap-1">
                ${isValidUrl(r.linkPasta) ? `<a href="${escapeHtml(r.linkPasta)}" target="_blank" rel="noopener" title="Abrir Pasta no Drive" class="p-1.5 rounded-md text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 transition"><svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M3 7a2 2 0 012-2h4l2 2h8a2 2 0 012 2v8a2 2 0 01-2 2H5a2 2 0 01-2-2V7z"/></svg></a>` : ''}
                ${isValidUrl(r.linkPlanilha) ? `<a href="${escapeHtml(r.linkPlanilha)}" target="_blank" rel="noopener" title="Abrir Planilha de Preço" class="p-1.5 rounded-md text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 transition"><svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></a>` : ''}
                ${isValidUrl(r.linkAta) ? `<a href="${escapeHtml(r.linkAta)}" target="_blank" rel="noopener" title="Abrir Link da Ata" class="p-1.5 rounded-md text-slate-400 hover:text-amber-600 hover:bg-amber-50 transition"><svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg></a>` : ''}
              </div>
            </td>
          </tr>`;
      }).join('');
    }

    function changePageSize() {
      state.pageSize = parseInt(document.getElementById('pageSizeSelect').value, 10);
      state.page = 1;
      renderTable();
    }
    function prevPage() { if (state.page > 1) { state.page--; renderTable(); } }
    function nextPage() { state.page++; renderTable(); }

    // ==================== RENDER CALENDAR / AGENDA VIEW ====================
    function setCalendarMode(mode) {
      state.calendarMode = mode;
      document.getElementById('calModeMonth').className = mode === 'month'
        ? 'px-3 py-1 text-xs font-semibold rounded-md bg-white text-slate-900 shadow-sm'
        : 'px-3 py-1 text-xs font-medium rounded-md text-slate-600 hover:text-slate-900';
      document.getElementById('calModeWeek').className = mode === 'week'
        ? 'px-3 py-1 text-xs font-semibold rounded-md bg-white text-slate-900 shadow-sm'
        : 'px-3 py-1 text-xs font-medium rounded-md text-slate-600 hover:text-slate-900';
      document.getElementById('calendarMonthContainer').classList.toggle('hidden', mode !== 'month');
      document.getElementById('calendarWeekContainer').classList.toggle('hidden', mode !== 'week');
      renderCalendar();
    }

    function calPrev() {
      const d = state.calendarDate;
      if (state.calendarMode === 'month') state.calendarDate = new Date(d.getFullYear(), d.getMonth() - 1, 1);
      else state.calendarDate = new Date(d.getFullYear(), d.getMonth(), d.getDate() - 7);
      renderCalendar();
    }
    function calNext() {
      const d = state.calendarDate;
      if (state.calendarMode === 'month') state.calendarDate = new Date(d.getFullYear(), d.getMonth() + 1, 1);
      else state.calendarDate = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 7);
      renderCalendar();
    }
    function calToday() {
      state.calendarDate = new Date();
      renderCalendar();
    }

    function renderCalendar() {
      const byDate = {};
      state.filtered.forEach(r => {
        if (!r.data) return;
        if (!byDate[r.data]) byDate[r.data] = [];
        byDate[r.data].push(r);
      });
      Object.values(byDate).forEach(arr => arr.sort((a, b) => (a.horario || '').localeCompare(b.horario || '')));

      const todayISO = getTodayISO();
      const d = state.calendarDate;

      if (state.calendarMode === 'month') {
        const y = d.getFullYear();
        const m = d.getMonth();
        document.getElementById('calTitle').textContent = new Date(y, m, 1).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

        const firstDay = new Date(y, m, 1).getDay();
        const daysInMonth = new Date(y, m + 1, 0).getDate();
        const totalCells = Math.ceil((firstDay + daysInMonth) / 7) * 7;

        let html = '';
        for (let i = 0; i < totalCells; i++) {
          const cellDate = new Date(y, m, 1 - firstDay + i);
          const isCurMonth = cellDate.getMonth() === m;
          const iso = `${cellDate.getFullYear()}-${String(cellDate.getMonth()+1).padStart(2,'0')}-${String(cellDate.getDate()).padStart(2,'0')}`;
          const isToday = iso === todayISO;
          const evs = byDate[iso] || [];

          const evHtml = evs.slice(0, 3).map(ev => {
            const st = getStatusStyle(ev.status);
            const label = displayOrgao(ev.orgao);
            return `
              <button onclick="AgendaModule.openDrawer('${ev.uid}')" class="w-full text-left px-1.5 py-1 rounded border text-[11px] leading-tight truncate hover:brightness-95 transition ${st.cal}" title="${escapeHtml((ev.horario || '') + ' ' + label + ' (' + ev.status + ')')}">
                <span class="font-bold">${escapeHtml(ev.horario || '')}</span> ${escapeHtml(label)}
              </button>`;
          }).join('');

          const moreHtml = evs.length > 3
            ? `<button onclick="AgendaModule.filterToSingleDay('${iso}')" class="w-full text-left px-1.5 py-0.5 text-[10px] font-bold text-indigo-600 hover:underline">+ ${evs.length - 3} pregões</button>`
            : '';

          html += `
            <div class="calendar-cell p-1.5 sm:p-2 ${isCurMonth ? 'bg-white' : 'bg-slate-50/70'} ${isToday ? 'ring-2 ring-inset ring-indigo-500 bg-indigo-50/20' : ''} flex flex-col gap-1">
              <div class="flex items-center justify-between">
                <span class="text-xs font-semibold ${isToday ? 'w-6 h-6 rounded-full bg-indigo-600 text-white flex items-center justify-center' : (isCurMonth ? 'text-slate-700' : 'text-slate-400')}">${cellDate.getDate()}</span>
                ${evs.length > 0 ? `<span class="text-[10px] font-semibold text-slate-400">${evs.length}</span>` : ''}
              </div>
              <div class="space-y-1 overflow-hidden">${evHtml}${moreHtml}</div>
            </div>`;
        }
        document.getElementById('calendarMonthGrid').innerHTML = html;
      } else {
        const start = new Date(d.getFullYear(), d.getMonth(), d.getDate() - d.getDay());
        const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 6);
        document.getElementById('calTitle').textContent = `${start.toLocaleDateString('pt-BR', { day:'2-digit', month:'short' })} – ${end.toLocaleDateString('pt-BR', { day:'2-digit', month:'short', year:'numeric' })}`;

        let html = '';
        const dayNames = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
        for (let i = 0; i < 7; i++) {
          const cur = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
          const iso = `${cur.getFullYear()}-${String(cur.getMonth()+1).padStart(2,'0')}-${String(cur.getDate()).padStart(2,'0')}`;
          const isToday = iso === todayISO;
          const evs = byDate[iso] || [];

          const cardsHtml = evs.length === 0
            ? `<div class="py-8 text-center text-xs text-slate-400">Livre</div>`
            : evs.map(ev => {
                const st = getStatusStyle(ev.status);
                return `
                  <div onclick="AgendaModule.openDrawer('${ev.uid}')" class="p-2.5 rounded-lg border bg-white hover:border-indigo-300 hover:shadow-sm cursor-pointer transition space-y-1">
                    <div class="flex items-center justify-between gap-1">
                      <span class="text-[11px] font-bold text-indigo-700 tabular-nums">${escapeHtml(ev.horario || '--:--')}</span>
                      <span class="px-1.5 py-0.5 rounded text-[10px] font-semibold border leading-none ${st.badge} truncate max-w-[100px]">${escapeHtml(ev.status)}</span>
                    </div>
                    <div class="text-xs font-bold text-slate-900 leading-snug line-clamp-2">${escapeHtml(displayOrgao(ev.orgao))}</div>
                    <div class="text-[11px] text-slate-500 truncate">${escapeHtml(ev.edital)} • ${escapeHtml(ev.portal || '')}</div>
                    <div class="text-[10px] font-medium text-slate-400 truncate">${escapeHtml(ev.empresa || '')} ${ev.uf ? '• ' + escapeHtml(ev.uf) : ''}</div>
                  </div>`;
              }).join('');

          html += `
            <div class="rounded-xl border ${isToday ? 'border-indigo-400 bg-indigo-50/30' : 'border-slate-200 bg-slate-50/50'} flex flex-col min-h-[340px]">
              <div class="px-3 py-2.5 border-b ${isToday ? 'border-indigo-200 bg-indigo-50/70' : 'border-slate-200/80 bg-white'} rounded-t-xl flex items-center justify-between">
                <div>
                  <span class="text-[11px] font-semibold uppercase ${isToday ? 'text-indigo-700' : 'text-slate-500'}">${dayNames[i]}</span>
                  <div class="text-sm font-bold ${isToday ? 'text-indigo-900' : 'text-slate-900'}">${cur.getDate()}/${String(cur.getMonth()+1).padStart(2,'0')}</div>
                </div>
                <span class="text-xs font-bold px-2 py-0.5 rounded-full ${evs.length ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400'}">${evs.length}</span>
              </div>
              <div class="p-2 space-y-2 flex-1">${cardsHtml}</div>
            </div>`;
        }
        document.getElementById('calendarWeekGrid').innerHTML = html;
      }
    }

    function filterToSingleDay(iso) {
      document.getElementById('dateFrom').value = iso;
      document.getElementById('dateTo').value = iso;
      onCustomDateChange();
      switchTab('list');
    }

    // ==================== RENDER ALERTS / PENDÊNCIAS VIEW ====================
    function renderAlerts() {
      const upcoming = state.records.filter(r => {
        const d = diffDaysFromToday(r.data);
        return d !== null && d >= 0 && d <= 7 && OPEN_STATUSES.has(r.status);
      }).sort((a, b) => (a.data + a.horario).localeCompare(b.data + b.horario));

      const overdue = state.records.filter(r => {
        const d = diffDaysFromToday(r.data);
        return d !== null && d < 0 && OPEN_STATUSES.has(r.status);
      }).sort((a, b) => b.data.localeCompare(a.data));

      const noValAtas = state.records.filter(r => r.status === 'Ata Assinada' && (r.valor === null || r.valor === undefined))
        .sort((a, b) => (b.data || '').localeCompare(a.data || ''));

      const dataIssues = state.records.filter(r => r.dataAlerta || (r.valor > 0 && r.status !== 'Ata Assinada'));

      const totalBadge = overdue.length + noValAtas.length + dataIssues.length;
      document.getElementById('alertsTabBadge').textContent = totalBadge;
      document.getElementById('alertCountUpcoming').textContent = upcoming.length;
      document.getElementById('alertCountOverdue').textContent = overdue.length;
      document.getElementById('alertCountNoVal').textContent = noValAtas.length;
      document.getElementById('alertCountDataIssues').textContent = dataIssues.length;

      renderAlertList('alertListUpcoming', upcoming, r => `${formatDateBR(r.data)} ${r.horario || ''} • ${r.portal || 'Portal n/d'} • ${r.status}`, 'Nenhum pregão agendado nos próximos 7 dias.');
      renderAlertList('alertListOverdue', overdue, r => `Data: ${formatDateBR(r.data)} • Status atual: ${r.status}`, 'Nenhum pregão vencido pendente.');
      renderAlertList('alertListNoVal', noValAtas, r => `Ata em ${formatDateBR(r.data)} • ${r.empresa || 'Sem empresa'} • Clique para lançar o valor`, 'Todas as Atas Assinadas estão com valor preenchido!');
      renderAlertList('alertListDataIssues', dataIssues, r => {
        const parts = [];
        if (r.dataAlerta) parts.push(r.dataAlerta);
        if (r.valor > 0 && r.status !== 'Ata Assinada') parts.push(`Valor ${formatBRL(r.valor)} lançado em status "${r.status}"`);
        return parts.join(' • ');
      }, 'Nenhuma inconsistência encontrada!');
    }

    function renderAlertList(containerId, items, subFn, emptyMsg) {
      const el = document.getElementById(containerId);
      if (items.length === 0) {
        el.innerHTML = `<div class="p-6 text-center text-xs text-slate-400">${emptyMsg}</div>`;
        return;
      }
      el.innerHTML = items.map(r => `
        <div onclick="AgendaModule.openDrawer('${r.uid}')" class="px-5 py-3 hover:bg-slate-50 cursor-pointer flex items-center justify-between gap-3 transition">
          <div class="min-w-0">
            <div class="text-xs sm:text-sm font-semibold text-slate-900 truncate">${escapeHtml(displayOrgao(r.orgao))} <span class="text-slate-400 font-normal">(${escapeHtml(r.edital || 'S/N')})</span></div>
            <div class="text-xs text-slate-500 mt-0.5 truncate" title="${escapeHtml(subFn(r))}">${escapeHtml(subFn(r))}</div>
          </div>
          <svg class="w-4 h-4 text-slate-400 shrink-0" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>
        </div>`).join('');
    }

    // ==================== TAB SWITCHING ====================
    function switchTab(tab) {
      state.tab = tab;
      ['list', 'calendar', 'alerts'].forEach(t => {
        document.getElementById(`view-${t}`).classList.toggle('hidden', t !== tab);
        const btn = document.getElementById(`tabBtn-${t}`);
        if (t === tab) {
          btn.className = 'tab-btn px-3.5 py-1.5 rounded-md text-xs sm:text-sm font-semibold transition flex items-center gap-1.5 bg-white text-slate-900 shadow-sm';
        } else {
          btn.className = 'tab-btn px-3.5 py-1.5 rounded-md text-xs sm:text-sm font-medium text-slate-600 hover:text-slate-900 transition flex items-center gap-1.5';
        }
      });
      if (tab === 'calendar') renderCalendar();
      if (tab === 'alerts') renderAlerts();
      ['list', 'calendar', 'alerts'].forEach(t => {
        const sideBtn = document.getElementById(`sideNav-${t}`);
        if (sideBtn) sideBtn.classList.toggle('is-active', t === tab);
      });
      const pageTitle = document.getElementById('modulePageTitle');
      if (pageTitle) pageTitle.textContent = tab === 'calendar' ? 'Calendário' : tab === 'alerts' ? 'Pendências' : 'Pregões';
      if (window.PlatformHub) window.PlatformHub.highlightAgendaTab(tab);
    }

    function renderAll() {
      renderKPIs();
      renderTable();
      if (state.tab === 'calendar') renderCalendar();
      renderAlerts();
      const sideBadge = document.getElementById('sideAlertsBadge');
      const mainBadge = document.getElementById('alertsTabBadge');
      if (sideBadge && mainBadge) sideBadge.textContent = mainBadge.textContent;
      if (window.PlatformHub) window.PlatformHub.updateSidebarBadges();
    }

    // ==================== SLIDE-OVER DETAIL DRAWER ====================
    function openDrawer(uid) {
      const rec = state.records.find(r => r.uid === uid);
      if (!rec) return;
      state.selectedUid = uid;

      document.getElementById('drawerEditalBadge').textContent = `Edital ${rec.edital || 'S/N'}`;
      document.getElementById('drawerIdLabel').textContent = rec.id ? `ID #${rec.id}` : '';
      document.getElementById('drawerTitle').textContent = displayOrgao(rec.orgao);
      document.getElementById('drawerSubtitle').textContent = `${rec.empresa || 'Sem empresa'} • ${rec.portal || 'Sem portal'} ${rec.uf ? '(' + rec.uf + ')' : ''}`;

      const dl = getDeadlineAlert(rec);
      const dlBadge = document.getElementById('drawerDeadlineBadge');
      if (dl) {
        dlBadge.className = `inline-flex items-center px-2 py-0.5 rounded text-xs font-bold ${dl.cls}`;
        dlBadge.textContent = dl.label;
      } else {
        dlBadge.className = 'hidden';
      }

      const alertBox = document.getElementById('drawerAlertBox');
      if (rec.dataAlerta) {
        alertBox.classList.remove('hidden');
        document.getElementById('drawerAlertText').textContent = rec.dataAlerta;
      } else {
        alertBox.classList.add('hidden');
      }

      // Ensure status exists in dropdown even for custom imported statuses
      const stSel = document.getElementById('editStatus');
      if (rec.status && ![...stSel.options].some(o => o.value === rec.status)) {
        const opt = document.createElement('option');
        opt.value = rec.status;
        opt.textContent = rec.status;
        stSel.appendChild(opt);
      }
      stSel.value = rec.status || '';
      document.getElementById('editValor').value = (rec.valor !== null && rec.valor !== undefined) ? rec.valor : '';
      document.getElementById('editData').value = rec.data || '';
      document.getElementById('editHorario').value = rec.horario || '';

      // Links buttons
      const links = [];
      if (isValidUrl(rec.linkPasta)) links.push(`<a href="${escapeHtml(rec.linkPasta)}" target="_blank" rel="noopener" class="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-lg bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 transition">📁 Pasta no Drive</a>`);
      if (isValidUrl(rec.linkPlanilha)) links.push(`<a href="${escapeHtml(rec.linkPlanilha)}" target="_blank" rel="noopener" class="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-lg bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 transition">📊 Planilha de Preço</a>`);
      if (isValidUrl(rec.linkAta)) links.push(`<a href="${escapeHtml(rec.linkAta)}" target="_blank" rel="noopener" class="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-lg bg-amber-50 text-amber-800 hover:bg-amber-100 border border-amber-200 transition">📄 Link da Ata</a>`);
      document.getElementById('drawerLinksSection').innerHTML = links.length ? links.join('') : '<span class="text-xs text-slate-400">Nenhum link externo cadastrado neste pregão.</span>';

      // Metadata
      document.getElementById('metaEmpresa').textContent = rec.empresa || '—';
      document.getElementById('metaPortal').textContent = rec.portal || '—';
      document.getElementById('metaModalidade').textContent = rec.modalidade || '—';
      document.getElementById('metaUF').textContent = rec.uf || '—';
      document.getElementById('metaPrazo').textContent = rec.prazoEntrega || '—';
      const adesaoVig = [rec.adesao ? `Adesão: ${rec.adesao}` : '', rec.vigenciaAta ? `Vigência: ${rec.vigenciaAta}` : ''].filter(Boolean).join(' • ');
      document.getElementById('metaAdesaoVig').textContent = adesaoVig || '—';

      document.getElementById('editObjeto').value = rec.objeto || '';

      const qWrap = document.getElementById('metaQuestWrap');
      if (rec.questionamento) {
        qWrap.classList.remove('hidden');
        document.getElementById('metaQuest').textContent = rec.questionamento;
      } else qWrap.classList.add('hidden');

      const pWrap = document.getElementById('metaPedidosWrap');
      if (rec.pedidosObs) {
        pWrap.classList.remove('hidden');
        document.getElementById('metaPedidos').textContent = rec.pedidosObs;
      } else pWrap.classList.add('hidden');

      renderNotesList(rec);

      document.getElementById('ag-drawerBackdrop').classList.remove('hidden');
      requestAnimationFrame(() => {
        document.getElementById('detailDrawer').classList.remove('translate-x-full');
      });
    }

    function closeDrawer() {
      document.getElementById('detailDrawer').classList.add('translate-x-full');
      setTimeout(() => {
        document.getElementById('ag-drawerBackdrop').classList.add('hidden');
      }, 200);
      state.selectedUid = null;
    }

    function saveDrawerField(field, value) {
      const rec = state.records.find(r => r.uid === state.selectedUid);
      if (!rec) return;
      rec[field] = value;
      if (field === 'data' && value) {
        rec.dataAlerta = '';
        document.getElementById('drawerAlertBox').classList.add('hidden');
      }
      state.meta.updatedAt = new Date().toISOString();
      saveToStorage();
      syncAgendaRecordToCloud(rec, false);
      applyFilters();
      if (window.PlatformHub) window.PlatformHub.onAgendaRecordUpdated(rec);

      const ind = document.getElementById('drawerSaveIndicator');
      ind.classList.remove('opacity-0');
      setTimeout(() => ind.classList.add('opacity-0'), 1800);
    }

    function deleteCurrentBid() {
      const rec = state.records.find(r => r.uid === state.selectedUid);
      if (!rec) return;
      if (window.CheckpointManager) window.CheckpointManager.capture('agenda', `Antes de excluir pregão ${rec.edital || rec.orgao}`);
      if (!confirm(`Remover o pregão "${rec.edital || 'S/N'} - ${displayOrgao(rec.orgao)}" da agenda local?`)) return;
      state.records = state.records.filter(r => r.uid !== state.selectedUid);
      state.meta.updatedAt = new Date().toISOString();
      saveToStorage();
      syncAgendaRecordToCloud(rec, true);
      closeDrawer();
      populateFilterDropdowns();
      applyFilters();
      showToast('Pregão removido da agenda.', '🗑️');
    }

    function renderNotesList(rec) {
      const notes = rec.notas || [];
      document.getElementById('notesCountLabel').textContent = `${notes.length} ${notes.length === 1 ? 'anotação' : 'anotações'}`;
      const el = document.getElementById('notesList');
      if (notes.length === 0) {
        el.innerHTML = `<p class="text-xs text-slate-400 italic py-2">Nenhuma anotação rápida registrada para este pregão ainda.</p>`;
        return;
      }
      el.innerHTML = notes.map((n, idx) => `
        <div class="p-3 rounded-lg bg-indigo-50/40 border border-indigo-100 text-xs space-y-1">
          <div class="flex items-center justify-between text-[11px] text-slate-500">
            <span class="font-semibold text-indigo-800">${escapeHtml(n.author || 'Equipe')}</span>
            <div class="flex items-center gap-2">
              <span>${new Date(n.at).toLocaleString('pt-BR', { day:'2-digit', month:'2-digit', year:'2-digit', hour:'2-digit', minute:'2-digit' })}</span>
              <button onclick="AgendaModule.deleteQuickNote(${idx})" class="text-slate-400 hover:text-rose-600" title="Remover nota">✕</button>
            </div>
          </div>
          <p class="text-slate-800 whitespace-pre-wrap leading-relaxed">${escapeHtml(n.text)}</p>
        </div>`).join('');
    }

    function addQuickNote() {
      const rec = state.records.find(r => r.uid === state.selectedUid);
      if (!rec) return;
      const input = document.getElementById('newNoteInput');
      const author = document.getElementById('newNoteAuthor').value.trim();
      const text = input.value.trim();
      if (!text) return;
      if (!Array.isArray(rec.notas)) rec.notas = [];
      rec.notas.unshift({ text, author: author || getAgUserName(), at: new Date().toISOString() });
      input.value = '';
      state.meta.updatedAt = new Date().toISOString();
      saveToStorage();
      syncAgendaRecordToCloud(rec, false);
      renderNotesList(rec);
      renderTable();
      showToast('Anotação salva no pregão!', '📝');
    }

    function deleteQuickNote(idx) {
      const rec = state.records.find(r => r.uid === state.selectedUid);
      if (!rec || !rec.notas) return;
      rec.notas.splice(idx, 1);
      saveToStorage();
      syncAgendaRecordToCloud(rec, false);
      renderNotesList(rec);
      renderTable();
    }

    // ==================== IMPORT SYSTEM (SHEETJS + GOOGLE SHEETS) ====================
    function openImportModal() {
      document.getElementById('sheetSelectorWrap').classList.add('hidden');
      document.getElementById('importModal').classList.remove('hidden');
    }
    function closeImportModal() {
      document.getElementById('importModal').classList.add('hidden');
    }
    function switchImportTab(tab) {
      document.getElementById('impPaneFile').classList.toggle('hidden', tab !== 'file');
      document.getElementById('impPaneSheets').classList.toggle('hidden', tab !== 'sheets');
      document.getElementById('impTabFile').className = tab === 'file' ? 'py-1.5 rounded-md bg-white text-slate-900 shadow-sm' : 'py-1.5 rounded-md text-slate-600 hover:text-slate-900';
      document.getElementById('impTabSheets').className = tab === 'sheets' ? 'py-1.5 rounded-md bg-white text-slate-900 shadow-sm' : 'py-1.5 rounded-md text-slate-600 hover:text-slate-900';
    }

    const dz = document.getElementById('dropZone');
    ['dragenter','dragover'].forEach(ev => dz.addEventListener(ev, e => { e.preventDefault(); dz.classList.add('border-indigo-500','bg-indigo-50/70'); }));
    ['dragleave','drop'].forEach(ev => dz.addEventListener(ev, e => { e.preventDefault(); dz.classList.remove('border-indigo-500','bg-indigo-50/70'); }));
    dz.addEventListener('drop', e => {
      const file = e.dataTransfer.files[0];
      if (file) processUploadedFile(file);
    });

    function handleFileSelect(e) {
      const file = e.target.files[0];
      if (file) processUploadedFile(file);
      e.target.value = '';
    }

    function processUploadedFile(file) {
      if (typeof XLSX === 'undefined') {
        showToast('Biblioteca SheetJS não carregada. Verifique sua conexão com a internet.', '⚠️');
        return;
      }
      const isCsv = /\.csv$/i.test(file.name);
      const reader = new FileReader();
      reader.onload = function(evt) {
        try {
          let wb;
          if (isCsv) {
            wb = XLSX.read(evt.target.result, { type: 'string', raw: true });
          } else {
            const data = new Uint8Array(evt.target.result);
            wb = XLSX.read(data, { type: 'array', cellDates: false });
          }
          state.pendingWorkbook = wb;
          state.pendingFileName = file.name;

          if (wb.SheetNames.length === 1) {
            importWorksheet(wb.Sheets[wb.SheetNames[0]], file.name);
          } else {
            const sel = document.getElementById('sheetSelect');
            sel.innerHTML = wb.SheetNames.map(n => `<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join('');
            const preferred = wb.SheetNames.find(n => n.toLowerCase() === 'agenda');
            if (preferred) sel.value = preferred;
            document.getElementById('sheetSelectorWrap').classList.remove('hidden');
          }
        } catch (err) {
          console.error(err);
          showToast('Erro ao ler arquivo: ' + err.message, '❌');
        }
      };
      if (isCsv) reader.readAsText(file, 'UTF-8');
      else reader.readAsArrayBuffer(file);
    }

    function confirmSheetImport() {
      if (!state.pendingWorkbook) return;
      const sheetName = document.getElementById('sheetSelect').value;
      importWorksheet(state.pendingWorkbook.Sheets[sheetName], `${state.pendingFileName} (${sheetName})`);
    }

    function normalizeHeader(h) {
      return String(h || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
    }

    function parseExcelDateCell(raw) {
      if (raw === null || raw === undefined || raw === '') return { iso: '', alert: '' };
      if (typeof raw === 'number') {
        if (raw > 20000 && raw < 80000) {
          const d = XLSX.SSF.parse_date_code(raw);
          if (d && d.y >= 2000 && d.y <= 2100) {
            return { iso: `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`, alert: '' };
          }
        }
        return { iso: '', alert: `Serial de data inválido (${raw})` };
      }
      const s = String(raw).trim();
      if (!s || s === '#VALUE!') return { iso: '', alert: s ? `Data inválida na planilha (${s})` : '' };
      const sFix = s.replace('/0225', '/2025').replace('/0226', '/2026');
      let m = sFix.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
      if (m) {
        let day = parseInt(m[1], 10), mon = parseInt(m[2], 10), yr = parseInt(m[3], 10);
        if (mon > 12 && day <= 12) { [day, mon] = [mon, day]; }
        const iso = `${yr}-${String(mon).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
        return { iso, alert: s !== sFix ? `Ano corrigido (${s} -> ${iso})` : '' };
      }
      m = sFix.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})/);
      if (m) return { iso: `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`, alert: '' };
      return { iso: '', alert: `Data não reconhecida (${s})` };
    }

    function parseExcelTimeCell(raw) {
      if (raw === null || raw === undefined || raw === '') return '';
      if (typeof raw === 'number' && raw >= 0 && raw < 1) {
        const totalMin = Math.round(raw * 24 * 60);
        return `${String(Math.floor(totalMin / 60) % 24).padStart(2,'0')}:${String(totalMin % 60).padStart(2,'0')}`;
      }
      return String(raw).replace(/\n/g, ' / ').replace(/\t/g, ' ').replace(/\s+/g, ' ').trim();
    }

    function parseMoneyCell(raw) {
      if (raw === null || raw === undefined || raw === '') return null;
      if (typeof raw === 'number') return Math.round(raw * 100) / 100;
      let s = String(raw).replace(/[R$\s]/g, '').trim();
      if (!s) return null;
      // Handle both BR format (1.234,56) and US format (1234.56 or 1,234.56)
      const hasComma = s.includes(',');
      const hasDot = s.includes('.');
      if (hasComma && hasDot) {
        if (s.lastIndexOf(',') > s.lastIndexOf('.')) {
          s = s.replace(/\./g, '').replace(',', '.');
        } else {
          s = s.replace(/,/g, '');
        }
      } else if (hasComma) {
        s = s.replace(',', '.');
      } else if (hasDot) {
        // If multiple dots (e.g. 1.234.567), they are thousand separators
        const parts = s.split('.');
        if (parts.length > 2) s = s.replace(/\./g, '');
      }
      const num = parseFloat(s);
      return isNaN(num) ? null : Math.round(num * 100) / 100;
    }

    function cleanPrazoVal(raw) {
      if (raw === null || raw === undefined || raw === '') return '';
      if (typeof raw === 'number') return Number.isInteger(raw) ? `${raw} dias` : String(raw);
      const s = String(raw).replace(/\t/g, ' ').trim();
      if (/^\d+\.0$/.test(s)) return `${parseInt(s, 10)} dias`;
      if (/^\d+$/.test(s)) return `${s} dias`;
      return s;
    }

    function getSheetCellLink(ws, rowIdx, colIdx, rawVal) {
      if (colIdx !== undefined && ws) {
        const addr = XLSX.utils.encode_cell({ r: rowIdx, c: colIdx });
        const cell = ws[addr];
        if (cell && cell.l && cell.l.Target && /^https?:\/\//i.test(cell.l.Target)) {
          return cell.l.Target.trim();
        }
      }
      if (rawVal === null || rawVal === undefined) return '';
      const s = String(rawVal).replace(/\t/g, ' ').trim();
      if (s === '.' || s === '..') return '';
      const matches = s.match(/https?:\/\/[^\s]+?(?=https?:\/\/|$)/g);
      if (matches && matches.length > 1) return matches[matches.length - 1].trim();
      return s;
    }

    function importWorksheet(ws, sourceName) {
      const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null, raw: true });
      if (!rows || rows.length < 2) {
        showToast('A planilha está vazia ou sem linhas de dados.', '⚠️');
        return;
      }

      let hdrIdx = 0;
      for (let i = 0; i < Math.min(rows.length, 10); i++) {
        if (rows[i].filter(c => c !== null && String(c).trim() !== '').length >= 3) {
          hdrIdx = i;
          break;
        }
      }

      const rawHeaders = rows[hdrIdx].map(h => h === null ? '' : String(h).trim());
      const normHeaders = rawHeaders.map(normalizeHeader);

      const map = {};
      // 1. Reconhecimento prioritário da estrutura oficial "Agenda Participação.xlsx" (Col A = 'a', Col B = '' vazia com Nº do Edital)
      if (normHeaders[0] === 'a' && normHeaders[1] === '') {
        map.id = 0;
        map.edital = 1;
      }

      normHeaders.forEach((h, idx) => {
        if (!h || h.startsWith('verifica')) return;
        if (h === 'a' || h === 'id' || h === 'idpregao') map.id ??= idx;
        else if ((h.includes('edital') || h.includes('pregao') || h.includes('numero')) && !h.includes('observa') && !h.includes('apos') && !h.includes('data')) map.edital ??= idx;
        else if (h === 'dia' || h.includes('data')) map.data ??= idx;
        else if (h.includes('horar') || h === 'hora') map.horario ??= idx;
        else if (h.includes('empresa') || h.includes('responsav')) map.empresa ??= idx;
        else if (h.includes('municip') || h.includes('orgao') || h.includes('consorc') || h.includes('licitante') || h.includes('cliente')) map.orgao ??= idx;
        else if (h === 'estado' || h === 'uf') map.uf ??= idx;
        else if (h.includes('portal') || h.includes('plataforma')) map.portal ??= idx;
        else if (h.includes('modalidade')) {
          if (map.modalidade === undefined) map.modalidade = idx;
          else if (map.status === undefined) map.status = idx;
        }
        else if (h.includes('situac') || h.includes('status') || h.includes('fase')) map.status ??= idx;
        else if (h.includes('objeto') || h.includes('observa') || h.includes('produt') || h.includes('descri')) map.objeto ??= idx;
        else if (h.includes('question')) map.questionamento ??= idx;
        else if (h.includes('valor')) map.valor ??= idx;
        else if (h.includes('prazo')) map.prazoEntrega ??= idx;
        else if (h.includes('pasta')) map.linkPasta ??= idx;
        else if (h.includes('planilha')) map.linkPlanilha ??= idx;
        else if (h.includes('linkata')) map.linkAta ??= idx;
        else if (h.includes('adesao')) map.adesao ??= idx;
        else if (h.includes('vigenc')) map.vigenciaAta ??= idx;
        else if (h.includes('quantojapediram')) map.pedidosObs ??= idx;
        else if (h.includes('anotac')) map.notasCol ??= idx;
      });

      // Fallback extra: se ainda não mapeou edital e a coluna B (idx 1) estiver sem cabeçalho mas tiver números de edital (ex: 34/2026)
      if (map.edital === undefined && normHeaders[1] === '') {
        const sampleRows = rows.slice(hdrIdx + 1, hdrIdx + 25);
        const editalLike = sampleRows.filter(r => r && r[1] && /\d+\s*[\/\-]\s*\d+/.test(String(r[1]))).length;
        if (editalLike >= 2) map.edital = 1;
      }

      const oldNotesMap = new Map();
      state.records.forEach(r => {
        if (r.notas && r.notas.length) {
          oldNotesMap.set(`${(r.edital||'').toLowerCase()}|${(r.orgao||'').toLowerCase()}`, r.notas);
        }
      });

      const imported = [];
      for (let i = hdrIdx + 1; i < rows.length; i++) {
        const row = rows[i];
        if (!row) continue;
        const corePresent = [map.orgao, map.edital, map.data, map.empresa, map.status]
          .filter(c => c !== undefined)
          .some(c => row[c] !== null && String(row[c]).trim() !== '');
        if (!corePresent) continue;

        const strVal = (k) => (map[k] !== undefined && row[map[k]] !== null && row[map[k]] !== undefined) ? String(row[map[k]]).replace(/\t/g, ' ').trim() : '';
        const dtParsed = map.data !== undefined ? parseExcelDateCell(row[map.data]) : { iso: '', alert: '' };
        const edital = strVal('edital');
        const orgao = strVal('orgao');
        const key = `${edital.toLowerCase()}|${orgao.toLowerCase()}`;

        // Restore exported notes if present in sheet
        let restoredNotes = oldNotesMap.get(key) || [];
        const rawNotesCol = strVal('notasCol');
        if (rawNotesCol && restoredNotes.length === 0) {
          restoredNotes = rawNotesCol.split(' | ').filter(Boolean).map(chunk => {
            const m = chunk.match(/^\[(.*?) - (.*?)\]: (.*)$/);
            return m ? { author: m[2], text: m[3], at: new Date().toISOString() } : { author: 'Importado', text: chunk, at: new Date().toISOString() };
          });
        }

        let alertMsg = dtParsed.alert;
        if (isValidUrl(orgao)) {
          alertMsg = alertMsg ? `${alertMsg} | Link no campo Órgão` : 'Link colado no campo Órgão/Município';
        }

        imported.push({
          uid: `imp-${Date.now()}-${i}`,
          id: strVal('id').replace(/\.0$/, '') || String(imported.length + 1),
          edital,
          data: dtParsed.iso,
          dataAlerta: alertMsg,
          horario: map.horario !== undefined ? parseExcelTimeCell(row[map.horario]) : '',
          empresa: strVal('empresa'),
          orgao,
          uf: strVal('uf').toUpperCase(),
          portal: strVal('portal'),
          modalidade: strVal('modalidade'),
          status: strVal('status') || 'Iniciar',
          objeto: strVal('objeto'),
          questionamento: strVal('questionamento'),
          valor: map.valor !== undefined ? parseMoneyCell(row[map.valor]) : null,
          prazoEntrega: map.prazoEntrega !== undefined ? cleanPrazoVal(row[map.prazoEntrega]) : '',
          linkPasta: getSheetCellLink(ws, i, map.linkPasta, map.linkPasta !== undefined ? row[map.linkPasta] : null),
          linkPlanilha: getSheetCellLink(ws, i, map.linkPlanilha, map.linkPlanilha !== undefined ? row[map.linkPlanilha] : null),
          linkAta: getSheetCellLink(ws, i, map.linkAta, map.linkAta !== undefined ? row[map.linkAta] : null),
          adesao: strVal('adesao').replace(/\.0$/, ''),
          vigenciaAta: map.vigenciaAta !== undefined ? (parseExcelDateCell(row[map.vigenciaAta]).iso || strVal('vigenciaAta')) : '',
          pedidosObs: strVal('pedidosObs'),
          notas: restoredNotes
        });
      }

      if (imported.length === 0) {
        showToast('Nenhum pregão válido identificado nesta aba.', '⚠️');
        return;
      }

      if (window.CheckpointManager) window.CheckpointManager.capture('agenda', `Antes de importar planilha: ${sourceName}`);
      state.records = imported;
      state.meta = { source: sourceName, updatedAt: new Date().toISOString() };
      saveToStorage();
      pushFullAgendaToCloud('Importação: ' + sourceName);
      populateFilterDropdowns();
      resetAllFilters();
      closeImportModal();
      showToast(`${imported.length} pregões importados com sucesso!`, '✓');
    }

    async function importFromGoogleSheets() {
      const rawUrl = document.getElementById('gsheetsUrlInput').value.trim();
      if (!rawUrl) { showToast('Cole o link do Google Sheets primeiro.', '⚠️'); return; }

      let csvUrl = rawUrl;
      const m = rawUrl.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
      if (m && !rawUrl.includes('output=csv') && !rawUrl.includes('format=csv')) {
        const gidMatch = rawUrl.match(/gid=(\d+)/);
        const gidParam = gidMatch ? `&gid=${gidMatch[1]}` : '';
        csvUrl = `https://docs.google.com/spreadsheets/d/${m[1]}/export?format=csv${gidParam}`;
      }

      const btn = document.getElementById('btnFetchSheets');
      btn.disabled = true;
      btn.textContent = 'Sincronizando...';
      try {
        const res = await fetch(csvUrl);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const csvText = await res.text();
        const wb = XLSX.read(csvText, { type: 'string', raw: true });
        importWorksheet(wb.Sheets[wb.SheetNames[0]], 'Google Sheets (Sincronizado)');
      } catch (err) {
        showToast('Não foi possível acessar o Google Sheets diretamente (CORS/permissão). Baixe como .xlsx/.csv e importe na aba ao lado.', '⚠️');
        console.error(err);
      } finally {
        btn.disabled = false;
        btn.textContent = 'Sincronizar do Google Sheets';
      }
    }

    function restoreInitialData() {
      if (window.CheckpointManager) window.CheckpointManager.capture('agenda', 'Antes de restaurar base original');
      if (!confirm('Deseja restaurar a base original auditada (924 pregões da Agenda Participação.xlsx)? As edições locais serão substituídas.')) return;
      state.records = JSON.parse(JSON.stringify(INITIAL_DATA));
      state.meta = { source: 'Agenda Participação.xlsx (Base Auditada)', updatedAt: new Date().toISOString() };
      saveToStorage();
      pushFullAgendaToCloud('Restauração da base original');
      populateFilterDropdowns();
      resetAllFilters();
      closeImportModal();
      showToast('Base original restaurada com sucesso!', '✓');
    }

    // ==================== EXPORT TO EXCEL (.XLSX) ====================
    function exportToExcel() {
      if (typeof XLSX === 'undefined') {
        showToast('Biblioteca SheetJS indisponível offline.', '⚠️');
        return;
      }
      const rows = state.records.map(r => ({
        'ID': r.id,
        'Nº do Edital': r.edital,
        'Data do Pregão': r.data ? formatDateBR(r.data) : '',
        'Horário': r.horario,
        'Empresa / Responsável': r.empresa,
        'Órgão / Município': r.orgao,
        'UF': r.uf,
        'Portal': r.portal,
        'Modalidade': r.modalidade,
        'Status': r.status,
        'Objeto / Observação': r.objeto,
        'Questionamento': r.questionamento,
        'Valor Ganho': r.valor ?? '',
        'Prazo de Entrega': r.prazoEntrega,
        'Link Pastas': r.linkPasta,
        'Planilha de Preço': r.linkPlanilha,
        'Link Ata': r.linkAta,
        'Adesão': r.adesao,
        'Vigência Ata': r.vigenciaAta,
        'Anotações da Equipe': (r.notas || []).map(n => `[${new Date(n.at).toLocaleDateString('pt-BR')} - ${n.author}]: ${n.text}`).join(' | ')
      }));

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Agenda');
      XLSX.writeFile(wb, `Agenda_Licitacoes_Atualizada_${getTodayISO()}.xlsx`);
      showToast('Planilha exportada em .xlsx!', '📥');
    }

