// Matching engine for Procurar Produtos
function extractRequirements(text){
  const raw=String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const s=raw.replace(/,/g,'.');const req=[];
  const patterns=[[/\b(\d+)\s*gb\s*(?:ddr\d\s*)?(?:de\s*)?(?:ram|memoria)?\b/g,m=>`${m[1]} gb`],[/\b(?:ssd|hd|nvme)\s*(\d+)\s*gb\b/g,m=>`${m[1]} gb`],[/\b(\d{1,2}\.?\d?)\s*(?:pol|polegadas|inch|\")\b/g,m=>`${m[1]} pol`],[/\b(\d+)\s*hz\b/g,m=>`${m[1]} hz`],[/\b(\d+)\s*w\b/g,m=>`${m[1]} w`],[/\b(\d+(?:[.]\d+)?)\s*kg\b/g,m=>`${m[1]} kg`],[/\b(\d{2,4})\s*g\b/g,m=>`${m[1]} g`],[/\b(\d{1,3}(?:[.]\d+)?)\s*cm\b/g,m=>`${m[1]} cm`],[/\b(?:tam(?:anho)?\s*)([3-7]|a[1-4]|m00|m[0-4])\b/g,m=>`tamanho ${m[1]}`],[/\b(\d{1,2})\s*(?:gomos?|paineis|painel)\b/g,m=>`${m[1]} gomos`]];
  patterns.forEach(([re,fn])=>{let m;while((m=re.exec(s))!==null){const v=fn(m);if(!req.includes(v))req.push(v)}});
  ['full hd','ips','bivolt','abnt2','windows 11','windows 10','office','nvme','sata','ddr3','ddr4','ddr5','core i3','core i5','core i7','ryzen','80 plus','pfc ativo','hdmi','vesa','microfibra','couro sintetico','termotec','ultra fusion','costurada','butil','brim','trancado','futsal','society','campo','volei','basquete','handebol','futevolei','tenis de mesa','kimono','karate','taekwondo','judo','jiu jitsu','fifa','fivb','cbv','cbfs','fiba','ihf','ittf'].forEach(t=>{if(s.includes(t)&&!req.includes(t))req.push(t)});
  return req;
}

function requirementsMatch(r,description){
  const d=norm(description),compactText=d.replace(/\s/g,'');
  return r.filter(x=>{const compact=norm(x).replace(/\s/g,'');if(d.includes(norm(x))||compactText.includes(compact))return true;if(x.endsWith(' pol')){const n=x.replace(' pol','').replace('.',' ');return d.includes(n+' polegadas')||d.includes(n+' pol')}if(x.endsWith('gb'))return d.includes(x.replace(' gb','gb'));if(x.endsWith(' gomos')){const n=x.replace(' gomos','');return new RegExp(`\\b${n}\\s*(?:gomos?|paineis)\\b|\\bgomos?\\s*${n}\\b`).test(d)}return d.includes(compact)});
}

function matchProduct(p,text){
  const qNorm=norm(text);
  const fName=norm(p.name),fSpecs=norm([p.description,p.specs,p.fullSpec].join(' ')),fBrand=norm(p.brand),fCode=norm(p.code),fCat=norm([p.category,p.note,p.ncm].join(' '));
  const desc=[fName,fSpecs,fBrand,fCode,fCat].join(' ');
  const STOPWORDS=new Set(['de','da','do','das','dos','em','no','na','nos','nas','ou','ao','aos','as','os','um','uma','uns','umas','para','pra','com','sem','por','pelo','pela','que','como','mais','menos','entre','sobre','ate','seu','sua','seus','suas','este','esta','esse','essa','isto','isso','ser','ter','estar','deve','devendo','pode','podendo','indicado','indicada','indicados','indicadas','confeccionado','confeccionada','fabricado','fabricada','produzido','produzida','proporcionando','garantindo','oferecendo','possuindo','contendo','apresentando','desenvolvido','desenvolvida','ideal','alta','alto','qualidade','conforto','durabilidade','resistencia','acabamento','excelente','otimo','melhor','padrao','minimo','maximo','conforme','produto','produtos','item','itens','unidade','unidades','tipo','tipos','modelo','modelos','marca','uso','categoria','categorias','especificacao','especificacoes','tecnica','tecnicas','caracteristicas','geral','gerais']);
  const KEEP_SHORT=new Set(['pu','hd','pc','tv','lg','hp','wd','2u','5g','4k','a1','a2','a3','a4','m0','m1','m2','m3','m4','i3','i5','i7']);
  const words=qNorm.split(' ').filter(w=>(w.length>=3||KEEP_SHORT.has(w))&&!STOPWORDS.has(w));
  const unique=[...new Set(words)],hayWords=desc.split(' '),nameWords=fName.split(' ');
  const hits=unique.filter(w=>fuzzyTokenHit(w,desc,hayWords));
  const nameHits=unique.filter(w=>fuzzyTokenHit(w,fName,nameWords));
  const lexical=unique.length?hits.length/unique.length:1;
  const nameRatio=unique.length?nameHits.length/unique.length:0;
  const req=extractRequirements(text),reqHits=requirementsMatch(req,desc),reqScore=req.length?reqHits.length/req.length:lexical;
  let exactBonus=0;
  if(qNorm.length>=3&&fName.includes(qNorm))exactBonus+=0.18;
  if(qNorm.length>=2&&fCode&&fCode===qNorm)exactBonus+=0.25;
  const rawSim=(lexical*0.42)+(reqScore*0.38)+(nameRatio*0.20)+exactBonus;
  let score=text.trim()?Math.round(Math.min(1,rawSim)*100):100;
  if(p.homologated&&score>0&&score<100)score=Math.min(100,score+1);
  const rankWeight=(score*1000)+(nameHits.length*50)+(hits.length*15)+(reqHits.length*10)-(req.length-reqHits.length)*5+(exactBonus*100);
  const matchedFields=[];
  if(nameHits.length)matchedFields.push('Nome');
  if(hits.some(w=>fuzzyTokenHit(w,fSpecs,fSpecs.split(' '))))matchedFields.push('Especificações');
  if(hits.some(w=>fuzzyTokenHit(w,fBrand,fBrand.split(' '))))matchedFields.push('Marca');
  if(hits.some(w=>fuzzyTokenHit(w,fCode,fCode.split(' '))))matchedFields.push('Código/SKU');
  if(hits.some(w=>fuzzyTokenHit(w,fCat,fCat.split(' '))))matchedFields.push('Categoria');
  const wordMisses=unique.filter(w=>!hits.includes(w));
  return {p,score,rankWeight,req,reqHits,wordHits:hits,wordMisses,matchedFields,missing:req.filter(r=>!reqHits.includes(r)),lexical};
}

function renderMatch(requireTextToast=false){
  populateFilterDropdowns();
  updateFilterBadges();
  const text=document.getElementById('specInput').value.trim();
  const supplier=document.getElementById('searchSupplierFilter').value;
  const brand=document.getElementById('searchBrandFilter').value;
  const category=document.getElementById('searchCategoryFilter').value;
  const minP=Number(document.getElementById('searchMinPrice').value)||0;
  const maxP=Number(document.getElementById('searchMaxPrice').value)||0;
  const sortMode=document.getElementById('searchSortSelect').value;
  const hideUnavail=document.getElementById('searchHideUnavailable').checked;
  const onlyFav=document.getElementById('searchOnlyFavorites').checked;
  const onlyOut=document.getElementById('searchOutdatedOnly').checked;

  const hasFilters=Boolean(supplier||brand||category||minP||maxP||hideUnavail||onlyFav||onlyOut||activeModality||activeSeal||activeLevel||activeSize||activeMaterial||activeUserChip);
  document.getElementById('clearSearchBtn').classList.toggle('hidden',!text&&!hasFilters);

  if(!text&&!hasFilters){
    if(requireTextToast)toast('Digite um termo de busca ou selecione um filtro.','error');
    document.getElementById('matchCount').textContent='Aguardando busca';
    document.getElementById('matchResults').innerHTML='<div class="panel p-8 text-center"><div class="w-12 h-12 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mx-auto text-xl">⌕</div><p class="text-[13px] font-bold mt-3">Sua busca começa aqui</p><p class="text-[11px] text-slate-400 mt-1">Digite o produto, SKU, cole a especificação do edital ou clique em <b>Filtros</b>.</p></div>';
    return;
  }

  const pool=products.filter(p=>{
    const cat=p.category||inferCategory(p);
    const best=bestOffer(p),price=best?.price||0;
    if(supplier&&!(p.offers||[]).some(o=>o.supplier===supplier))return false;
    if(brand&&p.brand!==brand)return false;
    if(category&&cat!==category)return false;
    if(minP>0&&price<minP)return false;
    if(maxP>0&&price>maxP)return false;
    if(hideUnavail&&p.unavailable)return false;
    if(onlyFav&&!p.favorite)return false;
    if(onlyOut&&getDaysSinceUpdate(best?.date)<60)return false;
    if(!matchesAllSharedChipFilters(p))return false;
    return true;
  });

  lastMatch=pool.map(p=>matchProduct(p,text));
  let shown=text?lastMatch.filter(x=>x.score>=12):lastMatch;

  shown.sort((a,b)=>{
    const pa=bestOffer(a.p)?.price||0,pb=bestOffer(b.p)?.price||0;
    if(sortMode==='price-asc')return pa-pb||(b.rankWeight-a.rankWeight);
    if(sortMode==='price-desc')return pb-pa||(b.rankWeight-a.rankWeight);
    if(sortMode==='name-asc')return String(a.p.name).localeCompare(String(b.p.name),'pt-BR');
    return (b.rankWeight-a.rankWeight)||(pa-pb);
  });

  const displayList=shown.slice(0,24);
  document.getElementById('matchCount').textContent=`${shown.length} encontrado(s)`;
  document.getElementById('matchSubline').textContent=`Analisados ${pool.length} produtos`;

  if(!displayList.length){
    document.getElementById('matchResults').innerHTML='<div class="panel p-7 text-center text-xs text-slate-500">Nenhum produto encontrado com esses critérios.</div>';
    return;
  }
  document.getElementById('matchResults').innerHTML=`<div class="grid grid-cols-1 xl:grid-cols-2 gap-3">${displayList.map(x=>productCard(x.p,text?x:null)).join('')}</div>`;
}

