function saveProductUpdate(p){openCardMenuId=null;saveLocal();renderCatalog(true);renderMatch(false);syncProducts([p])}

document.addEventListener('click',async e=>{
  if(!e.target.closest('#module-produtos'))return;
  const toggleMenu=e.target.closest('[data-toggle-menu]');
  if(toggleMenu){
    const id=toggleMenu.dataset.toggleMenu;
    openCardMenuId=(openCardMenuId===id?null:id);
    renderCatalog(true);renderMatch(false);return;
  }
  if(!e.target.closest('.card-menu')&&openCardMenuId){
    openCardMenuId=null;renderCatalog(true);renderMatch(false);
  }

  const balloon=e.target.closest('[data-open-spec-balloon]');
  if(balloon){openSpecBalloonModal(balloon.dataset.openSpecBalloon,balloon.dataset.offer);return}

  const add=e.target.closest('[data-add-quote]');
  if(add){addQuoteItem(add.dataset.addQuote,add.dataset.offer);return}
  const sendProp=e.target.closest('[data-send-proposta]');
  if(sendProp){
    openCardMenuId=null;
    const p=products.find(x=>x.id===sendProp.dataset.sendProposta);
    if(p){
      const o=(p.offers||[]).find(x=>x.id===sendProp.dataset.offer)||bestOffer(p);
      const mult=getBidMultiplier();
      const unitBid=o?Math.round(Number(o.price)*mult*100)/100:0;
      if(window.PlatformHub){
        window.PlatformHub.sendProdutosToProposta([{
          name:p.name, specs:p.specs||'', fullSpec:resolveOfficialSpec(p).isOfficial?resolveOfficialSpec(p).text:'', brand:o?.brand||p.brand||'', code:o?.code||p.code||'',
          unit:p.unit||'UN', qty:1, price:unitBid, costPrice:o?Number(o.price):0
        }], 'append');
      }
    }
    return;
  }

  const fav=e.target.closest('[data-fav-toggle]');
  if(fav){const p=products.find(x=>x.id===fav.dataset.favToggle);if(p){p.favorite=!p.favorite;saveProductUpdate(p);toast(p.favorite?'Adicionado aos Favoritos ⭐':'Removido dos Favoritos.')}return}

  const wonBtn=e.target.closest('[data-won-btn]');
  if(wonBtn){const p=products.find(x=>x.id===wonBtn.dataset.wonBtn);if(p){p.homologated=!p.homologated;saveProductUpdate(p);toast(p.homologated?'Marcado como Já Ganho 🏆':'Desmarcado.')}return}

  const stk=e.target.closest('[data-stock-toggle]');
  if(stk){const p=products.find(x=>x.id===stk.dataset.stockToggle);if(p){p.unavailable=!p.unavailable;saveProductUpdate(p);toast(p.unavailable?'Marcado como Sem Estoque.':'Marcado como Em Estoque.','success')}return}

  const copySku=e.target.closest('[data-copy-sku]');
  if(copySku){const val=copySku.dataset.copySku;if(val)navigator.clipboard?.writeText(val).then(()=>toast(`Código "${val}" copiado!`,'success'));return}

  const copyPrice=e.target.closest('[data-copy-price]');
  if(copyPrice){const val=Number(copyPrice.dataset.copyPrice||0).toFixed(2).replace('.',',');navigator.clipboard?.writeText(val).then(()=>toast(`Preço R$ ${val} copiado!`,'success'));return}

  const copyFull=e.target.closest('[data-copy-full]');
  if(copyFull){const p=products.find(x=>x.id===copyFull.dataset.copyFull);if(p){openCardMenuId=null;const txt=`${p.name} | Marca: ${p.brand||'—'} | Cód: ${p.code||'—'} | Un: ${p.unit||'UN'}${p.specs?' | Especificações: '+p.specs:''}`;navigator.clipboard?.writeText(txt).then(()=>toast('Ficha técnica copiada!','success'));renderCatalog(true);renderMatch(false)}return}

  const openEq=e.target.closest('[data-open-equiv]');
  if(openEq){const p=products.find(x=>x.id===openEq.dataset.openEquiv);openCardMenuId=null;renderCatalog(true);renderMatch(false);if(p)openEquivalentsModal(p);return}

  const cmp=e.target.closest('[data-toggle-compare]');
  if(cmp){
    const id=cmp.dataset.toggleCompare;openCardMenuId=null;
    if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);
    else{if(compareIds.length>=4){toast('Máximo 4 produtos no comparador.','error');return}compareIds.push(id)}
    updateCompareBar();renderCatalog(true);renderMatch(false);return;
  }

  const editMan=e.target.closest('[data-edit-manual]');
  if(editMan){const p=products.find(x=>x.id===editMan.dataset.editManual);openCardMenuId=null;renderCatalog(true);renderMatch(false);if(p)openManualModal(p);return}
});

// Equivalents Modal
function openEquivalentsModal(refProd){
  const list=findEquivalentProducts(refProd);
  document.getElementById('equivModalTitle').textContent=`Equivalentes para: ${refProd.name}`;
  document.getElementById('equivModalSub').textContent=`Referência: ${refProd.brand||'—'} · Cód. ${refProd.code||'—'} · ${money(bestOffer(refProd)?.price||0)}`;
  const body=document.getElementById('equivModalBody');
  body.innerHTML=list.length?list.map(p=>{const best=bestOffer(p);return `<div class="border border-slate-200 rounded-xl p-3 flex items-center justify-between gap-3"><div class="min-w-0"><div class="text-xs font-extrabold">${escapeHtml(p.name)}</div><div class="text-[10px] text-slate-500 mt-0.5"><b>${escapeHtml(p.brand||'')}</b> · Cód. ${escapeHtml(p.code||'—')} · Fornecedor: <b>${escapeHtml(best?.supplier||'')}</b></div></div><div class="text-right shrink-0"><div class="text-sm font-extrabold tabular-nums">${money(best?.price||0)}</div><button type="button" class="btn btn-primary !py-1 !px-2.5 !text-[10px] mt-1" data-add-quote="${escapeHtml(p.id)}" data-offer="${escapeHtml(best?.id||'')}">＋ Cotar</button></div></div>`}).join(''):'<div class="p-6 text-center text-xs text-slate-400">Nenhum produto equivalente encontrado.</div>';
  document.getElementById('equivalentsModal').classList.remove('overlay-hidden');
}
document.getElementById('closeEquivModalBtn').addEventListener('click',()=>document.getElementById('equivalentsModal').classList.add('overlay-hidden'));

// Side-by-side Compare Modal
function updateCompareBar(){const bar=document.getElementById('compareFloatingBar');document.getElementById('compareCountLabel').textContent=compareIds.length;bar.classList.toggle('hidden',compareIds.length===0)}
document.getElementById('clearCompareBtn').addEventListener('click',()=>{compareIds=[];updateCompareBar();renderCatalog(true);renderMatch(false)});
document.getElementById('openCompareModalBtn').addEventListener('click',()=>{
  const items=compareIds.map(id=>products.find(p=>p.id===id)).filter(Boolean);
  if(items.length<2){toast('Selecione pelo menos 2 produtos.','error');return}
  const lowestPrice=Math.min(...items.map(p=>bestOffer(p)?.price||999999));
  document.getElementById('compareModalBody').innerHTML=`<table class="data-table"><thead><tr><th>Atributo</th>${items.map(p=>`<th>${escapeHtml(p.name)}</th>`).join('')}</tr></thead><tbody>
    <tr><td><b>Menor Custo</b></td>${items.map(p=>{const pr=bestOffer(p)?.price||0;return `<td class="font-extrabold text-sm ${pr===lowestPrice?'text-emerald-600':''}">${money(pr)}</td>`}).join('')}</tr>
    <tr><td><b>Lance Calculado</b></td>${items.map(p=>`<td class="font-bold text-blue-700">${money(getBidPrice(bestOffer(p)?.price||0))}</td>`).join('')}</tr>
    <tr><td><b>Fornecedor</b></td>${items.map(p=>`<td>${escapeHtml(bestOffer(p)?.supplier||'—')}</td>`).join('')}</tr>
    <tr><td><b>Marca / Código</b></td>${items.map(p=>`<td>${escapeHtml(p.brand||'—')} · Cód. ${escapeHtml(p.code||'—')}</td>`).join('')}</tr>
    <tr><td><b>Especificações</b></td>${items.map(p=>`<td class="text-[11px] leading-relaxed">${escapeHtml(p.specs||p.description||'—')}</td>`).join('')}</tr>
    <tr><td><b>Ação</b></td>${items.map(p=>{const b=bestOffer(p);return `<td><button class="btn btn-primary !py-1 !px-3" data-add-quote="${escapeHtml(p.id)}" data-offer="${escapeHtml(b?.id||'')}">＋ Cotar</button></td>`}).join('')}</tr>
  </tbody></table>`;
  document.getElementById('compareModal').classList.remove('overlay-hidden');
});
