document.getElementById('manualProductForm').addEventListener('submit',e=>{
  e.preventDefault();
  const id=document.getElementById('mpId').value.trim(),code=document.getElementById('mpCode').value.trim(),brand=document.getElementById('mpBrand').value.trim(),unit=document.getElementById('mpUnit').value.trim()||'UN',ncm=document.getElementById('mpNcm').value.trim(),name=document.getElementById('mpName').value.trim(),supplier=document.getElementById('mpSupplier').value.trim(),price=Number(document.getElementById('mpPrice').value)||0,category=document.getElementById('mpCategory').value.trim(),specs=document.getElementById('mpSpecs').value.trim(),fullSpec=(document.getElementById('mpFullSpec')?.value||'').replace(/\r\n/g,'\n'),note=document.getElementById('mpNote').value.trim(),datasheetUrl=document.getElementById('mpDatasheet').value.trim(),homologated=document.getElementById('mpHomologated').checked,favorite=document.getElementById('mpFavorite').checked,unavailable=document.getElementById('mpUnavailable').checked;
  if(!name||!supplier||price<=0){toast('Preencha nome, fornecedor e preço válido.','error');return}
  let p=id?products.find(x=>x.id===id):null;
  if(!p){
    p={id:uid(),name,description:name,brand,code,ncm,unit,groupKey:norm(code||name).replace(/ /g,'-'),category:category||inferCategory({name,description:name,specs}),specs,fullSpec,isManualSpec:Boolean(fullSpec.trim()),manualSpecUpdatedAt:fullSpec.trim()?new Date().toISOString():'',note,datasheetUrl,homologated,favorite,unavailable,offers:[{id:uid(),supplier,price,date:today(),source:'TEXT',code,brand,datasheetUrl}]};
    products.unshift(p);
  }else{
    p.name=name;p.description=name;p.brand=brand;p.code=code;p.ncm=ncm;p.unit=unit;p.category=category||inferCategory({name,description:name,specs});p.specs=specs;p.fullSpec=fullSpec;p.isManualSpec=Boolean(fullSpec.trim());if(fullSpec.trim())p.manualSpecUpdatedAt=new Date().toISOString();p.note=note;p.datasheetUrl=datasheetUrl;p.homologated=homologated;p.favorite=favorite;p.unavailable=unavailable;
    let off=(p.offers||[]).find(o=>norm(o.supplier)===norm(supplier))||p.offers?.[0];
    if(off){if(Number(off.price)!==price){off.previousPrice=Number(off.price);off.previousDate=off.date||today()}off.supplier=supplier;off.price=price;off.date=today();off.code=code;off.brand=brand;off.datasheetUrl=datasheetUrl}
    else{p.offers=[{id:uid(),supplier,price,date:today(),source:'TEXT',code,brand,datasheetUrl}]}
  }
  document.getElementById('manualProductModal').classList.add('overlay-hidden');
  saveProductUpdate(p);toast('Produto salvo!','success');
});

// Diagnostics & Import Log Modal
function openDiagnosticsModal(mode='diag'){
  const body=document.getElementById('diagModalBody');
  if(mode==='log'){
    document.getElementById('diagModalTitle').textContent='Histórico de Importações (Log)';
    body.innerHTML=importLogs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Data/Hora</th><th>Arquivo</th><th>Fornecedor</th><th>Novos</th><th>Atualiz.</th></tr></thead><tbody>${importLogs.map(l=>`<tr><td>${escapeHtml(l.date)}</td><td><b>${escapeHtml(l.file)}</b></td><td>${escapeHtml(l.supplier||'—')}</td><td class="text-emerald-600 font-bold">+${l.saved}</td><td class="text-blue-600 font-bold">${l.updated}</td></tr>`).join('')}</tbody></table></div>`:'<div class="p-6 text-center text-xs text-slate-400">Nenhuma importação registrada ainda.</div>';
  }else{
    document.getElementById('diagModalTitle').textContent='Diagnóstico da Base';
    const noSku=products.filter(p=>!p.code).length,noBrand=products.filter(p=>!p.brand||p.brand==='—').length,noSpecs=products.filter(p=>!p.specs||p.specs.trim().length<8).length,totalInc=products.filter(isIncompleteProduct).length;
    body.innerHTML=`<div class="grid grid-cols-3 gap-3 text-center"><div class="panel p-3"><div class="small-title">Sem SKU</div><div class="metric mt-1 text-amber-600">${noSku}</div></div><div class="panel p-3"><div class="small-title">Sem Marca</div><div class="metric mt-1 text-amber-600">${noBrand}</div></div><div class="panel p-3"><div class="small-title">Espec. Curta</div><div class="metric mt-1 text-amber-600">${noSpecs}</div></div></div><div class="flex justify-end"><button type="button" id="filterIncompleteBtn" class="btn btn-primary" ${totalInc===0?'disabled':''}>Filtrar ${totalInc} itens incompletos</button></div>`;
    setTimeout(()=>{const btn=document.getElementById('filterIncompleteBtn');if(btn)btn.addEventListener('click',()=>{onlyIncompleteFilter=true;document.getElementById('diagnosticsModal').classList.add('overlay-hidden');showView('catalog');renderCustomFilterChips();renderCatalog()})},30);
  }
  document.getElementById('diagnosticsModal').classList.remove('overlay-hidden');
}
document.getElementById('openDiagnosticsNav')?.addEventListener('click',()=>{if(window.PlatformHub)window.PlatformHub.switchModule('produtos');openDiagnosticsModal('diag');});
document.getElementById('openImportLogNav')?.addEventListener('click',()=>{if(window.PlatformHub)window.PlatformHub.switchModule('produtos');openDiagnosticsModal('log');});
document.getElementById('closeDiagModalBtn').addEventListener('click',()=>document.getElementById('diagnosticsModal').classList.add('overlay-hidden'));


// Quote / Lote Assembly
function openQuote(){document.getElementById('drawerBackdrop').classList.remove('overlay-hidden');document.getElementById('quoteDrawer').classList.add('open');renderQuote()}
function closeQuote(){document.getElementById('drawerBackdrop').classList.add('overlay-hidden');document.getElementById('quoteDrawer').classList.remove('open')}
function addQuoteItem(pid,oid,qtyToAdd=1){
  const p=products.find(x=>x.id===pid);if(!p)return;
  let o=(p.offers||[]).find(x=>x.id===oid)||bestOffer(p);
  if(!o){toast('Produto sem oferta válida.','error');return}
  const found=quote.find(x=>x.productId===pid&&x.offerId===o.id);
  if(found)found.qty+=qtyToAdd;
  else quote.push({id:uid(),productId:pid,offerId:o.id,name:p.name,supplier:o.supplier,brand:o.brand||p.brand,code:o.code||p.code,unit:p.unit||'UN',price:Number(o.price),qty:qtyToAdd});
  renderQuote();openQuote();toast('Adicionado ao Lote!','success');
}

function renderQuote(){
  document.getElementById('quoteCountTop').textContent=quote.length;
  const _qn=document.getElementById('quoteCountNav');if(_qn)_qn.textContent=quote.length;
  if(window.PlatformHub)window.PlatformHub.updateSidebarBadges();
  const mult=getBidMultiplier();
  if(!quote.length){document.getElementById('quoteItems').innerHTML='<div class="text-center text-xs text-slate-400 py-10">Nenhum item adicionado à proposta.</div>'}
  else{
    document.getElementById('quoteItems').innerHTML=quote.map(q=>{const unitBid=q.price*mult;return `<div class="border border-slate-200 rounded-xl p-3 bg-white"><div class="flex justify-between gap-2"><div class="min-w-0"><div class="text-[11px] font-extrabold leading-snug">${escapeHtml(q.name)}</div><div class="text-[9px] text-slate-400 mt-0.5">${escapeHtml(q.supplier)} · Cód. ${escapeHtml(q.code||'—')} · ${money(q.price)}</div></div><button data-remove-quote="${q.id}" class="text-rose-500 font-bold text-sm">×</button></div><div class="grid grid-cols-2 gap-2 mt-2.5"><div><label class="field-label">Qtd.</label><input type="number" min="1" step="1" class="field !py-1.5 text-xs" value="${q.qty}" data-quote-qty="${q.id}"></div><div><label class="field-label">Custo Unit.</label><input type="number" min="0" step="0.01" class="field !py-1.5 text-xs" value="${q.price}" data-quote-price="${q.id}"></div></div><div class="flex justify-between text-[10px] font-bold text-slate-600 mt-2 pt-1.5 border-t border-slate-100"><span>Custo: ${money(q.price*q.qty)}</span><span class="text-emerald-700">Lance: ${money(unitBid*q.qty)}</span></div></div>`}).join('');
  }
  const subtotal=quote.reduce((s,q)=>s+q.price*q.qty,0),total=subtotal*mult,profit=subtotal*((Number(calcParams.margin)||0)/100);
  document.getElementById('quoteSubtotal').textContent=money(subtotal);
  document.getElementById('quoteProfitTotal').textContent=money(profit);
  document.getElementById('quoteGrandTotal').textContent=money(total);
}

['openQuoteBtn','openQuoteNav'].forEach(id=>{const _el=document.getElementById(id);if(_el)_el.addEventListener('click',openQuote);});
document.getElementById('closeQuoteBtn').addEventListener('click',closeQuote);
document.getElementById('drawerBackdrop').addEventListener('click',closeQuote);
['quoteTax','quoteFreight','quoteMargin'].forEach(id=>{
  document.getElementById(id).addEventListener('input',()=>{
    calcParams.tax=Math.max(0,Number(document.getElementById('quoteTax').value)||0);
    calcParams.freight=Math.max(0,Number(document.getElementById('quoteFreight').value)||0);
    calcParams.margin=Math.max(0,Number(document.getElementById('quoteMargin').value)||0);
    saveCalcParams();renderQuote();renderCatalog(true);renderMatch(false);
  });
});
document.getElementById('quoteItems').addEventListener('change',e=>{const q=quote.find(x=>x.id===e.target.dataset.quoteQty||x.id===e.target.dataset.quotePrice);if(!q)return;if(e.target.dataset.quoteQty)q.qty=Math.max(1,Number(e.target.value)||1);if(e.target.dataset.quotePrice)q.price=Math.max(0,Number(e.target.value)||0);renderQuote()});
document.getElementById('quoteItems').addEventListener('click',e=>{const b=e.target.closest('[data-remove-quote]');if(b){quote=quote.filter(x=>x.id!==b.dataset.removeQuote);renderQuote()}});
document.getElementById('clearQuoteBtn').addEventListener('click',()=>{quote=[];renderQuote()});

document.getElementById('runBatchEditalBtn').addEventListener('click',()=>{
  const raw=document.getElementById('batchEditalInput').value.trim();if(!raw){toast('Cole pelo menos uma linha.','error');return}
  let added=0;const activePool=products.filter(p=>!p.unavailable);
  raw.split(/\r?\n/).map(l=>l.trim()).filter(Boolean).forEach(line=>{
    let qty=1,desc=line;const m=line.match(/^(\d+)\s*(?:x|un|und|unidades|pç|pc|-|\.)?\s+(.+)$/i);
    if(m){qty=Math.max(1,Number(m[1])||1);desc=m[2]}
    const scored=activePool.map(p=>matchProduct(p,desc)).filter(x=>x.score>=20).sort((a,b)=>(b.score-a.score)||((bestOffer(a.p)?.price||999999)-(bestOffer(b.p)?.price||999999)));
    if(scored.length){const off=bestOffer(scored[0].p);if(off){addQuoteItem(scored[0].p.id,off.id,qty);added++}}
  });
  if(added>0){document.getElementById('batchEditalInput').value='';toast(`${added} item(ns) adicionado(s) ao Lote!`,'success')}else{toast('Nenhum item compatível encontrado.','error')}
});

document.getElementById('copyQuoteSummaryBtn').addEventListener('click',()=>{
  if(!quote.length){toast('Lote vazio.','error');return}
  const mult=getBidMultiplier();
  const lines=quote.map((q,i)=>`${i+1}. ${q.name} (${q.brand||'—'} | Cód. ${q.code||'—'} | ${q.supplier}) - Qtd: ${q.qty} - Custo: ${money(q.price)} - Lance: ${money(q.price*mult)}`);
  const sum=quote.reduce((s,q)=>s+q.price*q.qty,0);
  lines.push(`\nCusto Total: ${money(sum)} | Total Lance: ${money(sum*mult)}`);
  navigator.clipboard?.writeText(lines.join('\n')).then(()=>toast('Resumo copiado!','success'));
});

function exportQuote(){
  if(!quote.length){toast('Lote vazio.','error');return}
  const mult=getBidMultiplier();
  const rows=quote.map(q=>({Item:q.name,Codigo:q.code,Marca:q.brand,Fornecedor:q.supplier,Unidade:q.unit,Quantidade:q.qty,Custo_Unitario:q.price,Subtotal_Custo:q.price*q.qty,Impostos_pct:calcParams.tax,Frete_pct:calcParams.freight,Margem_pct:calcParams.margin,Preco_Unitario_Lance:Number((q.price*mult).toFixed(2)),Total_Lance_Sugerido:Number((q.price*q.qty*mult).toFixed(2))}));
  if(window.XLSX){const ws=XLSX.utils.json_to_sheet(rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Cotacao');XLSX.writeFile(wb,'cotacao_pregao_'+today()+'.xlsx')}
  toast('Proposta exportada!','success');
}
document.getElementById('exportQuoteBtn').addEventListener('click',exportQuote);

// Import & Parsing
const fileInput=document.getElementById('fileInput'),dropzone=document.getElementById('dropzone');
document.getElementById('chooseFilesBtn').addEventListener('click',()=>fileInput.click());
document.getElementById('catalogImportBtn').addEventListener('click',()=>showView('import'));
fileInput.addEventListener('change',async e=>{for(const f of e.target.files){try{await handleFile(f)}catch(err){toast(`Falha ao processar ${f.name}: ${err.message}`,'error')}}fileInput.value=''});
['dragenter','dragover'].forEach(ev=>dropzone.addEventListener(ev,e=>{e.preventDefault();dropzone.classList.add('dragover')}));
['dragleave','drop'].forEach(ev=>dropzone.addEventListener(ev,e=>{e.preventDefault();dropzone.classList.remove('dragover')}));
dropzone.addEventListener('drop',async e=>{for(const f of e.dataTransfer.files){try{await handleFile(f)}catch(err){toast(`Falha ao processar ${f.name}: ${err.message}`,'error')}}});

function parseBRL(v){if(typeof v==='number')return v;let s=String(v??'').trim().replace(/R\$\s?/i,'').replace(/\s/g,'');if(!s)return 0;if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');const n=Number(s.replace(/[^\d.-]/g,''));return Number.isFinite(n)?n:0}
function detectSource(name){return (name.split('.').pop()||'').toUpperCase()}

async function handleFile(file){
  const ext=detectSource(file.name);activeSource=SOURCE_LABEL[ext]||ext;let rows=[],supplier='';
  if(ext==='XML'){
    const xml=await file.text();const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw new Error('XML inválido.');
    supplier=doc.querySelector('emit xNome')?.textContent?.trim()||'';
    doc.querySelectorAll('det').forEach(d=>{const p=d.querySelector('prod');if(!p)return;rows.push({description:p.querySelector('xProd')?.textContent?.trim()||'',code:p.querySelector('cProd')?.textContent?.trim()||'',ncm:p.querySelector('NCM')?.textContent?.trim()||'',unit:p.querySelector('uCom')?.textContent?.trim()||'UN',price:parseBRL(p.querySelector('vUnCom')?.textContent||0),supplier,brand:'',datasheetUrl:'',homologated:false,source:'XML'})});
  }else if(['XLSX','XLS','CSV','ODS'].includes(ext)){
    if(!window.XLSX)throw new Error('SheetJS não carregado.');
    const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});const matrix=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''});
    if(matrix.length<2)throw new Error('Planilha vazia.');
    pendingSheet={matrix,source:SOURCE_LABEL[ext],supplier:'',filename:file.name};openMapping(matrix);return;
  }else if(ext==='PDF'){
    if(!window.pdfjsLib)throw new Error('PDF.js não carregado.');
    pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    const doc=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let all='';
    for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i);const content=await page.getTextContent();const lineMap=new Map();content.items.forEach(item=>{const y=Math.round(item.transform?.[5]||0);lineMap.set(y,(lineMap.get(y)||'')+' '+item.str)});all+=[...lineMap.entries()].sort((a,b)=>b[0]-a[0]).map(x=>x[1].trim()).join('\n')+'\n'}
    rows=parseTextRows(all,'PDF');
  }else if(ext==='DOCX'){
    if(!window.mammoth)throw new Error('Mammoth.js não carregado.');
    const ab=await file.arrayBuffer();const html=await mammoth.convertToHtml({arrayBuffer:ab});const temp=document.createElement('div');temp.innerHTML=html.value;
    const tableRows=[...temp.querySelectorAll('tr')].map(tr=>[...tr.querySelectorAll('th,td')].map(td=>td.textContent.trim())).filter(r=>r.length);
    if(tableRows.length>1){pendingSheet={matrix:tableRows,source:'DOCX',supplier:'',filename:file.name};openMapping(tableRows);return}
    rows=parseTextRows((await mammoth.extractRawText({arrayBuffer:ab})).value,'DOCX');
  }else throw new Error('Formato não suportado.');
  if(!rows.length)throw new Error('Nenhum item encontrado.');
  showAudit(rows,supplier,activeSource,file.name);
}

function parseTextRows(text,source='Texto'){const out=[];String(text).split(/\r?\n/).map(l=>l.trim()).filter(Boolean).forEach(line=>{const prices=[...line.matchAll(/(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+\.\d{2}/g)];if(!prices.length)return;const m=prices[prices.length-1],price=parseBRL(m[0]);let desc=line.slice(0,m.index).replace(/[|;\-–—\s]+$/,'').trim(),code='';const split=desc.split(/[|;\t]/);if(split.length>1){code=split[0].trim();desc=split.slice(1).join(' ').trim()}if(desc.length<3||price<=0)return;out.push({description:desc,code,ncm:'',unit:'UN',price,supplier:'',brand:'',datasheetUrl:'',homologated:false,source})});return out}

function openMapping(matrix){const headers=matrix[0].map((v,i)=>String(v||`Coluna ${i+1}`).trim());pendingSheet={...pendingSheet,headers,data:matrix.slice(1)};const fields=[['description','Descrição'],['price','Coluna de Preço'],['supplier','Fornecedor'],['code','Código / SKU'],['ncm','NCM'],['brand','Marca'],['unit','Unidade']];const synonyms={description:['descricao','descrição','desc','especificacao','produto','item','nome'],price:['preco','preço','valor','atacado','sul/sudeste','vlr unit','unitario'],supplier:['fornecedor','empresa','razao'],code:['codigo','código','cod','sku','referencia'],ncm:['ncm'],brand:['marca','fabricante'],unit:['unidade','un','und']};const mapping={};fields.forEach(([k])=>{mapping[k]=headers.findIndex(h=>synonyms[k].some(s=>norm(h).includes(norm(s))))});pendingSheet.mapping=mapping;document.getElementById('mappingFields').innerHTML=fields.map(([k,lbl])=>`<div><label class="field-label">${lbl}</label><select class="field" data-map="${k}"><option value="-1">— Não mapear —</option>${headers.map((h,i)=>`<option value="${i}" ${mapping[k]===i?'selected':''}>${escapeHtml(h)}</option>`).join('')}</select></div>`).join('');document.getElementById('mappingPanel').classList.remove('hidden');document.getElementById('auditPanel').classList.add('hidden');toast('Escolha a Coluna de Preço e aplique o mapeamento.','success')}

document.getElementById('applyMappingBtn').addEventListener('click',()=>{if(!pendingSheet)return;const map={...pendingSheet.mapping};document.querySelectorAll('#module-produtos [data-map]').forEach(s=>map[s.dataset.map]=Number(s.value));if(map.description<0||map.price<0){toast('Mapeie Descrição e Coluna de Preço.','error');return}const rows=pendingSheet.data.map(r=>({description:r[map.description]??'',price:parseBRL(r[map.price]),supplier:map.supplier>=0?r[map.supplier]:'',code:map.code>=0?r[map.code]:'',ncm:map.ncm>=0?r[map.ncm]:'',brand:map.brand>=0?r[map.brand]:'',unit:map.unit>=0?r[map.unit]:'UN',datasheetUrl:'',homologated:false,source:pendingSheet.source})).filter(r=>String(r.description).trim()&&r.price>0);if(!rows.length){toast('Nenhum registro válido.','error');return}showAudit(rows,'',pendingSheet.source,pendingSheet.filename);document.getElementById('mappingPanel').classList.add('hidden')});

let currentAuditFile='Importação Manual';
function showAudit(rows,supplier,source,filename='Importação'){currentAuditFile=filename||source||'Importação';stagedRows=rows.map(r=>({...r,price:Number(r.price)||0,source:r.source||source||'Texto'}));document.getElementById('auditSupplier').value=supplier||rows.find(r=>r.supplier)?.supplier||'';document.getElementById('auditSource').value=source||rows[0]?.source||'Texto';document.getElementById('mappingPanel').classList.add('hidden');document.getElementById('auditPanel').classList.remove('hidden');renderAudit();document.getElementById('auditPanel').scrollIntoView({behavior:'smooth',block:'start'})}

function renderAudit(){document.getElementById('auditSummary').textContent=`${stagedRows.length} linha(s) para revisão`;document.getElementById('auditBody').innerHTML=stagedRows.map((r,i)=>{const bad=!r.price||r.price<=0;return `<tr class="${bad?'bg-rose-50/70':''}"><td><input class="audit-input min-w-[210px]" data-audit="description" data-index="${i}" value="${escapeHtml(r.description)}"></td><td><input class="audit-input" data-audit="code" data-index="${i}" value="${escapeHtml(r.code)}"></td><td><input class="audit-input" data-audit="ncm" data-index="${i}" value="${escapeHtml(r.ncm)}"></td><td><input class="audit-input" data-audit="brand" data-index="${i}" value="${escapeHtml(r.brand)}"></td><td><input class="audit-input !min-w-[55px]" data-audit="unit" data-index="${i}" value="${escapeHtml(r.unit||'UN')}"></td><td><input type="number" step="0.01" min="0" class="audit-input" data-audit="price" data-index="${i}" value="${r.price||''}"></td><td><input class="audit-input min-w-[160px]" data-audit="datasheetUrl" data-index="${i}" value="${escapeHtml(r.datasheetUrl)}" placeholder="https://..."></td><td><input type="checkbox" class="accent-emerald-600" data-audit="homologated" data-index="${i}" ${r.homologated?'checked':''}></td><td><button data-delete-audit="${i}" class="text-rose-500 font-bold">✕</button></td></tr>`}).join('')}
document.getElementById('auditBody').addEventListener('input',e=>{const i=Number(e.target.dataset.index),k=e.target.dataset.audit;if(k&&stagedRows[i])stagedRows[i][k]=k==='price'?Number(e.target.value)||0:e.target.value});
document.getElementById('auditBody').addEventListener('change',e=>{const i=Number(e.target.dataset.index),k=e.target.dataset.audit;if(k==='homologated'&&stagedRows[i])stagedRows[i].homologated=e.target.checked;if(k==='price'&&stagedRows[i]){stagedRows[i].price=Number(e.target.value)||0;renderAudit()}});
document.getElementById('auditBody').addEventListener('click',e=>{const b=e.target.closest('[data-delete-audit]');if(b){stagedRows.splice(Number(b.dataset.deleteAudit),1);renderAudit()}});
document.getElementById('clearAuditBtn').addEventListener('click',()=>{stagedRows=[];document.getElementById('auditPanel').classList.add('hidden')});

function findProductForRow(r){const code=norm(r.code),desc=norm(r.description),supplier=norm(r.supplier||document.getElementById('auditSupplier').value);if(code){const matches=products.filter(p=>norm(p.code)===code);const exact=matches.find(p=>norm(p.description||p.name)===desc||norm(p.name)===desc);if(exact)return exact;const sm=matches.find(p=>(p.offers||[]).some(o=>norm(o.supplier)===supplier));if(sm)return sm;if(matches.length===1)return matches[0]}return products.find(p=>norm(p.description||p.name)===desc||norm(p.name)===desc)||null}

function mergeAuditRows(){
  if(!stagedRows.length)return;
  if(window.CheckpointManager)window.CheckpointManager.capture('produtos',`Antes de importar ${stagedRows.length} item(ns) (${currentAuditFile})`);
  const defaultSupplier=document.getElementById('auditSupplier').value.trim();let saved=0,updated=0,invalid=0;const changed=new Map();
  stagedRows.forEach(r=>{
    const supplier=String(r.supplier||defaultSupplier||'').trim(),price=Number(r.price);
    if(!r.description?.trim()||!supplier||!Number.isFinite(price)||price<=0){invalid++;return}
    let p=findProductForRow(r);
    if(!p){p={id:uid(),name:r.description.trim(),description:r.description.trim(),brand:r.brand||'',code:r.code||'',ncm:r.ncm||'',unit:r.unit||'UN',groupKey:norm(r.code||r.description).replace(/ /g,'-'),category:r.category||inferCategory(r),specs:r.specs||'',homologated:!!r.homologated,datasheetUrl:r.datasheetUrl||'',offers:[]};products.push(p);saved++}
    else{if(r.brand)p.brand=r.brand;if(r.ncm)p.ncm=r.ncm;if(r.description)p.description=r.description;if(r.specs)p.specs=r.specs;if(r.category)p.category=r.category;if(r.datasheetUrl)p.datasheetUrl=r.datasheetUrl;if(r.homologated)p.homologated=true;updated++}
    const offer=(p.offers||[]).find(o=>(norm(o.supplier)===norm(supplier))&&((r.code&&norm(o.code)===norm(r.code))||(!r.code&&norm(p.description)===norm(r.description))));
    if(offer){offer.previousPrice=Number(offer.price);offer.previousDate=offer.date||today();offer.price=price;offer.date=today();offer.source=r.source||document.getElementById('auditSource').value}
    else{p.offers=p.offers||[];p.offers.push({id:uid(),supplier,price,date:today(),source:r.source||document.getElementById('auditSource').value,code:r.code||'',brand:r.brand||'',datasheetUrl:r.datasheetUrl||''})}
    changed.set(p.id,p);
  });
  importLogs.unshift({date:new Date().toLocaleString('pt-BR'),file:currentAuditFile,supplier:defaultSupplier||'Múltiplos',saved,updated});
  localStorage.setItem(IMPORT_LOG_KEY,JSON.stringify(importLogs.slice(0,50)));
  saveLocal();document.getElementById('auditPanel').classList.add('hidden');stagedRows=[];renderCatalog();syncProducts([...changed.values()]);
  toast(`${saved} novo(s), ${updated} atualizado(s).`,'success');showView('catalog');
}
