function renderHistory(){const all=products.flatMap(p=>(p.offers||[]).filter(o=>o.previousPrice!=null).map(o=>({p,o,variation:priceChange(o)})));document.getElementById('historyDown').textContent=all.filter(x=>x.variation<0).length;document.getElementById('historyUp').textContent=all.filter(x=>x.variation>0).length;document.getElementById('historyTotal').textContent=all.length;document.getElementById('historyBody').innerHTML=all.sort((a,b)=>(b.o.date||'').localeCompare(a.o.date||'')).map(({p,o,variation})=>`<tr><td><b>${escapeHtml(p.name)}</b></td><td>${escapeHtml(o.supplier)}</td><td>${money(o.previousPrice)}</td><td><b>${money(o.price)}</b></td><td><b class="${variation<0?'price-down':'price-up'}">${variation<0?'↓':'↑'} ${pct(variation)}</b></td><td>${fmtDate(o.date)}</td></tr>`).join('')||'<tr><td colspan="6" class="text-center text-slate-400 py-8">Ainda não há alterações registradas.</td></tr>'}

// Firebase (Cloud Firestore)
const FIRESTORE_RULES_CODE=`rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /produtos/{productId} {
      allow read, write: if true;
    }
  }
}`;
document.getElementById('appsScriptCode').textContent=FIRESTORE_RULES_CODE;
const cfgInput=document.getElementById('firebaseConfigInput'),colInput=document.getElementById('firebaseCollectionInput');
let fbRuntime=null,fbRuntimeKey='';

function parseFirebaseConfig(raw){if(!raw)return null;if(typeof raw==='object'&&raw.apiKey&&raw.projectId)return raw;const txt=String(raw).trim();if(!txt)return null;try{const p=JSON.parse(txt);if(p?.apiKey&&p?.projectId)return p}catch(_){}const out={};['apiKey','authDomain','projectId','storageBucket','messagingSenderId','appId'].forEach(k=>{const m=txt.match(new RegExp(k+`\\s*:\\s*["']([^"']+)["']`));if(m)out[k]=m[1].trim()});return (out.apiKey&&out.projectId)?out:null}
function getFirebaseConfig(){try{const p=parseFirebaseConfig(localStorage.getItem(FIREBASE_CFG_KEY));if(p)return p}catch(_){}return parseFirebaseConfig(DEFAULT_FIREBASE_CONFIG)}
function getCollectionName(){try{const c=(localStorage.getItem(FIREBASE_COL_KEY)||'').trim();if(c)return c}catch(_){}return DEFAULT_FIRESTORE_COLLECTION}
function openSettings(){document.getElementById('settingsModal').classList.remove('overlay-hidden');const cfg=getFirebaseConfig();cfgInput.value=cfg?JSON.stringify(cfg,null,2):'';colInput.value=getCollectionName()}
function closeSettings(){document.getElementById('settingsModal').classList.add('overlay-hidden')}
['settingsBtn','openSettingsSidebar'].forEach(id=>{const _el=document.getElementById(id);if(_el)_el.addEventListener('click',openSettings);});
document.getElementById('closeSettingsBtn').addEventListener('click',closeSettings);
document.getElementById('settingsModal').addEventListener('click',e=>{if(e.target.id==='settingsModal')closeSettings()});

document.getElementById('saveSettingsBtn').addEventListener('click',()=>{const p=parseFirebaseConfig(cfgInput.value.trim());if(p)localStorage.setItem(FIREBASE_CFG_KEY,JSON.stringify(p,null,2));localStorage.setItem(FIREBASE_COL_KEY,(colInput.value.trim()||'produtos').replace(/[^a-zA-Z0-9_-]/g,''));fbRuntime=null;fbRuntimeKey='';toast('Configuração salva!','success')});

document.getElementById('copyAppsScriptBtn').addEventListener('click',()=>navigator.clipboard?.writeText(FIRESTORE_RULES_CODE).then(()=>toast('Regras copiadas!','success')));

async function getFirebaseContext(){
  const cfg=getFirebaseConfig();if(!cfg)return null;
  const key=cfg.projectId+'|'+cfg.apiKey;if(fbRuntime&&fbRuntimeKey===key)return fbRuntime;
  const [appMod,fsMod]=await Promise.all([import('https://www.gstatic.com/firebasejs/13.3.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/13.3.0/firebase-firestore.js')]);
  const appName='cotacao_'+cfg.projectId,app=appMod.getApps().find(a=>a.name===appName)||appMod.initializeApp(cfg,appName);
  fbRuntime={db:fsMod.getFirestore(app),fs:fsMod,cfg};fbRuntimeKey=key;return fbRuntime;
}

async function fetchTeamProducts(showMsg=true){
  const cfg=getFirebaseConfig();if(!cfg)return false;
  try{
    const ctx=await getFirebaseContext(),colName=getCollectionName(),snap=await ctx.fs.getDocs(ctx.fs.collection(ctx.db,colName));
    const remote=[];snap.forEach(d=>{const data=d.data();if(data&&data.id)remote.push(data)});
    if(remote.length){
      const remoteMap=new Map(remote.map(p=>[p.id,p])),seedMap=new Map(seedProducts.map(p=>[p.id,p])),merged=[],used=new Set();
      seedProducts.forEach(sp=>{used.add(sp.id);if(remoteMap.has(sp.id)){const rp=remoteMap.get(sp.id),copy=structuredCloneSafe(sp);copy.homologated=!!rp.homologated;copy.favorite=!!rp.favorite;copy.unavailable=!!rp.unavailable;if(rp.note)copy.note=rp.note;if(rp.datasheetUrl)copy.datasheetUrl=rp.datasheetUrl;if(rp.fullSpec){copy.fullSpec=rp.fullSpec;copy.isManualSpec=true;copy.manualSpecUpdatedAt=rp.manualSpecUpdatedAt||'';}merged.push(copy)}else{merged.push(structuredCloneSafe(sp))}});
      remote.forEach(rp=>{if(!used.has(rp.id)&&!seedMap.has(rp.id))merged.push(rp)});
      products=merged;saveLocal();
    }
    syncState='connected';setSyncBadge();renderCatalog(true);renderMatch(false);renderHistory();
    document.getElementById('connectionHelp').textContent=`Conectado ao projeto ${cfg.projectId}. ${remote.length} doc(s) na nuvem.`;
    if(showMsg)toast(`Sincronizado (${remote.length} docs no Firestore).`,'success');
    return true;
  }catch(err){syncState='local';setSyncBadge();if(showMsg)toast('Erro Firebase: '+(err?.message||err),'error');return false}
}

async function syncProducts(items){
  const cfg=getFirebaseConfig();if(!cfg)return false;
  const list=(items||[]).filter(p=>p&&p.id);if(!list.length)return true;
  try{
    const ctx=await getFirebaseContext(),colName=getCollectionName();
    for(let i=0;i<list.length;i+=450){
      const batch=ctx.fs.writeBatch(ctx.db);
      list.slice(i,i+450).forEach(p=>{const clean=JSON.parse(JSON.stringify(p));clean.updatedAt=new Date().toISOString();batch.set(ctx.fs.doc(ctx.db,colName,String(clean.id)),clean,{merge:true})});
      await batch.commit();
    }
    syncState='connected';setSyncBadge();return true;
  }catch(err){syncState='local';setSyncBadge();return false}
}

document.getElementById('testConnectionBtn').addEventListener('click',()=>fetchTeamProducts(true));
async function syncAllWithFirebase(){
  const cfg=getFirebaseConfig();
  if(!cfg){toast('Configure o Firebase em ⚙ Firebase antes de sincronizar.','error');return false;}
  const btn=document.getElementById('syncNowBtn');
  const origHtml=btn?btn.innerHTML:'';
  if(btn){btn.disabled=true;btn.innerHTML='↻ <span class="hidden sm:inline">Sincronizando...</span>';}
  try{
    toast('Sincronizando base com o banco de dados...');
    const ctx=await getFirebaseContext(),colName=getCollectionName(),snap=await ctx.fs.getDocs(ctx.fs.collection(ctx.db,colName));
    const remote=[];snap.forEach(d=>{const data=d.data();if(data&&data.id)remote.push(data)});
    const remoteMap=new Map(remote.map(p=>[p.id,p]));
    const localMap=new Map(products.map(p=>[p.id,p]));
    const seedMap=new Map(seedProducts.map(p=>[p.id,p]));
    const merged=[],used=new Set();
    // Keep all local/seed products and merge remote flags
    products.forEach(lp=>{
      used.add(lp.id);
      if(remoteMap.has(lp.id)){
        const rp=remoteMap.get(lp.id),copy=structuredCloneSafe(lp);
        copy.homologated=!!(lp.homologated||rp.homologated);
        copy.favorite=!!(lp.favorite||rp.favorite);
        copy.unavailable=!!(lp.unavailable||rp.unavailable);
        if(!copy.note&&rp.note)copy.note=rp.note;
        if(!copy.datasheetUrl&&rp.datasheetUrl)copy.datasheetUrl=rp.datasheetUrl;
        merged.push(copy);
      }else{
        merged.push(structuredCloneSafe(lp));
      }
    });
    // Also ensure any seedProduct not yet in products is included
    seedProducts.forEach(sp=>{
      if(!used.has(sp.id)){used.add(sp.id);merged.push(structuredCloneSafe(sp));}
    });
    // Also bring any remote-only products added by team members
    remote.forEach(rp=>{
      if(!used.has(rp.id)&&!seedMap.has(rp.id)){used.add(rp.id);merged.push(rp);}
    });
    products=merged;saveLocal();
    // Push any products missing on remote or with updated price/date/specs
    const toPush=products.filter(p=>{
      const rp=remoteMap.get(p.id);
      if(!rp)return true;
      const lp0=p.offers&&p.offers[0]?p.offers[0].price:0;
      const rp0=rp.offers&&rp.offers[0]?rp.offers[0].price:0;
      const ld0=p.offers&&p.offers[0]?p.offers[0].date:'';
      const rd0=rp.offers&&rp.offers[0]?rp.offers[0].date:'';
      return lp0!==rp0||ld0!==rd0||p.specs!==rp.specs||!!p.homologated!==!!rp.homologated||!!p.favorite!==!!rp.favorite||!!p.unavailable!==!!rp.unavailable||(p.note||'')!==(rp.note||'');
    });
    if(toPush.length>0){
      const ok=await syncProducts(toPush);
      if(!ok)throw new Error('Falha ao enviar lote para o Firestore.');
    }
    syncState='connected';setSyncBadge();renderCatalog(true);renderMatch(false);renderHistory();
    const totalCloud=Math.max(remote.length,products.length);
    const helpEl=document.getElementById('connectionHelp');
    if(helpEl)helpEl.textContent=`Conectado ao projeto ${cfg.projectId}. ${totalCloud} doc(s) sincronizados na nuvem.`;
    if(toPush.length>0){
      toast(`Base enviada para o banco de dados! ${toPush.length} item(ns) enviados e tudo está sincronizado (${products.length} produtos).`,'success');
    }else{
      toast(`Tudo está sincronizado com o banco de dados! (${products.length} produtos atualizados).`,'success');
    }
    return true;
  }catch(err){
    syncState='local';setSyncBadge();
    toast('Erro ao sincronizar com o banco de dados: '+(err?.message||err),'error');
    return false;
  }finally{
    if(btn){btn.disabled=false;btn.innerHTML=origHtml;}
  }
}
